// 402句動詞データ（自動生成）
const PV_DATA = [{"no": 1, "stage": 1, "verb": "drop by", "meaning": "ちょっと立ち寄る", "def": "to visit someone briefly, usually without planning", "ex1": "Feel free to drop by my office anytime.", "ja1": "いつでも気軽に私のオフィスに立ち寄ってください。", "ex2": "Please drop by my desk if you have any questions about the proposal.", "ja2": "提案について質問があれば私の席に立ち寄ってください。", "note": "", "nuance": "予定を立てずにふらっと行く軽さがある。長居しない前提。", "groups": ["visit_casually"], "etymology": "drop（ポトリと落ちる）＋by（そばを）\n→ すぐそばを通り過ぎるイメージ\n→ そこから「ちょっと立ち寄る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-2,32,32)\"><path d=\"M32 14 Q44 30 44 38 Q44 48 32 48 Q20 48 20 38 Q20 30 32 14 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 12 Q8 -2 16 12\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2.2\"/></g></svg>"}, {"no": 2, "stage": 1, "verb": "come over", "meaning": "（自分のところへ）来る、遊びに来る", "def": "to come to where the speaker is, especially to a home", "ex1": "Do you want to come over for dinner tonight?", "ja1": "今夜うちに夕食を食べに来ない？", "ex2": "Could you come over to our office next Tuesday for the kickoff?", "ja2": "キックオフのため来週火曜に弊社オフィスへお越しいただけますか。", "note": "", "nuance": "相手の家・場所へ来てもらう表現。自分を基点に「こちらへ」というニュアンス。", "groups": [], "etymology": "come（来る）＋over（越えて）\n→ 何かを越えて広がる・一通り目を通すイメージ\n→ そこから「（自分のところへ）来る、遊びに来る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#9A5B2E\"/><g transform=\"rotate(-8,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 2 A6 6 0 1 1 2 8\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2.2\"/><path d=\"M2 8 L0 4 M2 8 L6 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 3, "stage": 1, "verb": "look for", "meaning": "探す", "def": "to try to find something or someone", "ex1": "I'm looking for my keys.", "ja1": "鍵を探しています。", "ex2": "We are looking for a vendor who can support 24-hour operations.", "ja2": "24時間対応できるベンダーを探しています。", "note": "", "nuance": "探している最中であることに焦点。見つかるかは分からない段階。", "groups": [], "etymology": "look（見る）＋for（求めて）\n→ 目的物を求めて手を伸ばすイメージ\n→ そこから「探す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"rotate(-7,32,32)\"><path d=\"M14 32 Q32 16 50 32 Q32 48 14 32 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"32\" cy=\"32\" r=\"7\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/><path d=\"M0 8 L11 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 4, "stage": 1, "verb": "get on", "meaning": "（バス・電車・飛行機に）乗る", "def": "to board a bus, train, plane, or other large vehicle", "ex1": "Let's get on the next train.", "ja1": "次の電車に乗ろう。", "ex2": "The team got on the shuttle bus to the client's site.", "ja2": "チームは客先へ向かうシャトルバスに乗った。", "note": "大型の乗り物に使う", "nuance": "バスや電車など大きい乗り物への搭乗。乗車動作そのものを指す。", "groups": ["board_vehicle"], "etymology": "get（得る・～になる）＋on（接触・継続）\n→ くっついたまま続く・作動し続けるイメージ\n→ そこから「（バス・電車・飛行機に）乗る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(5,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 5, "stage": 1, "verb": "get in", "meaning": "（車などに）乗り込む、中に入る", "def": "to enter a car or small vehicle; to enter a place", "ex1": "Get in the car, we're late.", "ja1": "車に乗って、遅れているよ。", "ex2": "Please get in the taxi first; I'll bring the documents.", "ja2": "先にタクシーに乗ってください、書類は私が持っていきます。", "note": "車・タクシーなど小型の乗り物", "nuance": "車やタクシーなど小さい乗り物に「入り込む」イメージ。get onとの対比で覚える。", "groups": ["vehicle_actions"], "etymology": "get（得る・～になる）＋in（中へ）\n→ 外から中に入る・参加や到着のイメージ\n→ そこから「（車などに）乗り込む、中に入る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"rotate(5,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 6, "stage": 1, "verb": "get off", "meaning": "（バス・電車などから）降りる", "def": "to leave a bus, train, plane, or other large vehicle", "ex1": "We get off at the next stop.", "ja1": "次の停留所で降ります。", "ex2": "We got off the train one stop early to reach the venue on foot.", "ja2": "会場まで歩くため、一駅手前で電車を降りた。", "note": "", "nuance": "get onの反対。大きい乗り物から降りる動作。", "groups": ["vehicle_actions"], "etymology": "get（得る・～になる）＋off（離れて）\n→ くっついていた物が離れる・停止や出発のイメージ\n→ そこから「（バス・電車などから）降りる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#1B2A41\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(5,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 7, "stage": 1, "verb": "clean up", "meaning": "きれいに片づける、掃除する", "def": "to make a place clean and tidy", "ex1": "Please clean up your room before dinner.", "ja1": "夕食の前に部屋を片づけてください。", "ex2": "Let's clean up the meeting room before the client arrives.", "ja2": "顧客が到着する前に会議室を片づけよう。", "note": "", "nuance": "散らかった状態を整える。仕上げまでのニュアンスを含む。", "groups": ["tidy_up"], "etymology": "clean（きれいにする）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「きれいに片づける、掃除する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#8A4B8A\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-6,32,32)\"><path d=\"M40 16 L24 44\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/><path d=\"M24 44 L16 50 M24 44 L20 50 M24 44 L28 50\" stroke=\"#C79A3D\" stroke-width=\"2\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 8, "stage": 1, "verb": "look up", "meaning": "（辞書などで）調べる", "def": "to search for information in a dictionary, book, or online", "ex1": "Look up the word in the dictionary.", "ja1": "その単語を辞書で調べなさい。", "ex2": "I looked up the specification in the product manual.", "ja2": "製品マニュアルで仕様を調べた。", "note": "", "nuance": "辞書やネットで能動的に調べる行為。単に見るのとは違う。", "groups": [], "etymology": "look（見る）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「（辞書などで）調べる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-4,32,32)\"><path d=\"M14 32 Q32 16 50 32 Q32 48 14 32 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"32\" cy=\"32\" r=\"7\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 9, "stage": 1, "verb": "put on", "meaning": "身につける、着る", "def": "to place clothing or accessories on your body", "ex1": "Put on your coat, it's cold outside.", "ja1": "コートを着なさい、外は寒いよ。", "ex2": "He put on a tie before the client presentation.", "ja2": "顧客プレゼンの前に彼はネクタイを締めた。", "note": "動作を表す（着ている状態は wear）", "nuance": "身につける動作そのもの。着ている状態はwearと区別。", "groups": ["clothing_wear"], "etymology": "put（置く）＋on（接触・継続）\n→ くっついたまま続く・作動し続けるイメージ\n→ そこから「身につける、着る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"rotate(-6,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 10, "stage": 1, "verb": "take off", "meaning": "脱ぐ", "def": "to remove clothing or something you are wearing", "ex1": "Take off your shoes at the entrance.", "ja1": "玄関で靴を脱いでください。", "ex2": "Please take off your badge before leaving the secure area.", "ja2": "セキュリティエリアを出る前にバッジを外してください。", "note": "Stage 6 の take off*2（離陸する）と区別", "nuance": "脱ぐ動作。Stage6の「離陸する」とは全くの別義。", "groups": ["clothing_wear"], "etymology": "take（取る）＋off（離れて）\n→ くっついていた物が離れる・停止や出発のイメージ\n→ そこから「脱ぐ」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"rotate(0,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 11, "stage": 1, "verb": "come back", "meaning": "戻ってくる、帰ってくる", "def": "to return to a place", "ex1": "Come back home before it gets dark.", "ja1": "暗くなる前に帰ってきなさい。", "ex2": "She came back from the site visit with several issues.", "ja2": "彼女は現地訪問から戻り、いくつかの課題を持ち帰った。", "note": "", "nuance": "話し手のいる場所へ戻ってくる。come backは聞き手側視点。", "groups": ["return"], "etymology": "come（来る）＋back（後ろ・元へ）\n→ 元の場所や状態に戻るイメージ\n→ そこから「戻ってくる、帰ってくる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"rotate(6,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M14 4 Q4 4 4 12 M4 12 L0 9 M4 12 L8 12\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 12, "stage": 1, "verb": "go back", "meaning": "戻る、帰る（自分から離れた元の場所へ）", "def": "to return to a place you were before", "ex1": "I need to go back to the office.", "ja1": "オフィスに戻らないといけない。", "ex2": "Let's go back to the previous slide.", "ja2": "前のスライドに戻りましょう。", "note": "話し手から離れる方向が go back", "nuance": "話し手から離れた場所へ戻る。go backは元の場所側の視点。", "groups": ["return"], "etymology": "go（行く）＋back（後ろ・元へ）\n→ 元の場所や状態に戻るイメージ\n→ そこから「戻る、帰る（自分から離れた元の場所へ）」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"rotate(4,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M14 4 Q4 4 4 12 M4 12 L0 9 M4 12 L8 12\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 13, "stage": 1, "verb": "come up with", "meaning": "（案・解決策を）思いつく", "def": "to think of an idea, plan, or solution", "ex1": "She came up with a great idea.", "ja1": "彼女はすばらしい案を思いついた。", "ex2": "The team came up with three options for the migration plan.", "ja2": "チームは移行計画の案を3つ考え出した。", "note": "", "nuance": "アイデアを思いつく瞬間の閃きを表す。会議などでよく使う。", "groups": [], "etymology": "come（来る）＋with（一緒に）\n→ 対象と一緒に行動するイメージ\n→ そこから「（案・解決策を）思いつく」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"rotate(-4,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 2 L8 14 M2 8 L14 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 14, "stage": 1, "verb": "hang up", "meaning": "電話を切る", "def": "to end a phone call", "ex1": "Don't hang up, I'm not finished.", "ja1": "電話を切らないで、まだ話は終わっていない。", "ex2": "Don't hang up until you have confirmed the next meeting date.", "ja2": "次回の日程を確認するまで電話を切らないでください。", "note": "", "nuance": "電話を切る動作。相手より先に切ると少し唐突な印象を与えることも。", "groups": [], "etymology": "hang（掛ける）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「電話を切る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#8A4B8A\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(11,32,32)\"><circle cx=\"24\" cy=\"32\" r=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"40\" cy=\"32\" r=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 15, "stage": 1, "verb": "go for", "meaning": "（〜を）選ぶ、〜にする", "def": "to choose or decide on something", "ex1": "I'll go for the chicken.", "ja1": "私はチキンにします。", "ex2": "The client went for the cloud-based solution.", "ja2": "顧客はクラウド型のソリューションを選んだ。", "note": "", "nuance": "複数の選択肢から一つを選ぶ、決断のニュアンス。", "groups": ["choose"], "etymology": "go（行く）＋for（求めて）\n→ 目的物を求めて手を伸ばすイメージ\n→ そこから「（〜を）選ぶ、〜にする」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#2E6B4F\"/><g transform=\"rotate(-8,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/><path d=\"M0 8 L11 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 16, "stage": 1, "verb": "run away", "meaning": "逃げる、家出する", "def": "to escape from a place or situation", "ex1": "The dog ran away from the yard.", "ja1": "犬が庭から逃げ出した。", "ex2": "We shouldn't run away from the risks in this proposal.", "ja2": "この提案のリスクから目を背けるべきではない。", "note": "", "nuance": "問題や責任から逃げるという比喩でもよく使われる。", "groups": ["escape_run_away"], "etymology": "run（走る）＋away（遠くへ）\n→ その場から遠ざかる・消えていくイメージ\n→ そこから「逃げる、家出する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"rotate(8,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-dasharray=\"3 2\" stroke-linecap=\"round\"/><path d=\"M11 3 L16 8 L11 13\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 17, "stage": 1, "verb": "move in", "meaning": "引っ越してくる、入居する", "def": "to start living in a new home", "ex1": "We moved in last month.", "ja1": "私たちは先月引っ越してきた。", "ex2": "The new team moves in to the fourth floor next Monday.", "ja2": "新チームは来週月曜に4階へ移ってくる。", "note": "", "nuance": "新しい生活の場に入居する、始まりの動き。", "groups": ["move_house"], "etymology": "move（動く）＋in（中へ）\n→ 外から中に入る・参加や到着のイメージ\n→ そこから「引っ越してくる、入居する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-12,32,32)\"><rect x=\"16\" y=\"24\" width=\"32\" height=\"24\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M16 24 L32 14 L48 24\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 18, "stage": 1, "verb": "move out", "meaning": "引っ越して出ていく、退去する", "def": "to stop living in a place and leave it", "ex1": "He moved out of his parents' house.", "ja1": "彼は実家を出た。", "ex2": "The department moved out of the old building last quarter.", "ja2": "その部署は前四半期に旧ビルから移転した。", "note": "", "nuance": "住んでいた場所を出ていく。荷物をまとめて去るイメージ。", "groups": ["move_house"], "etymology": "move（動く）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「引っ越して出ていく、退去する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#1B2A41\"/><g transform=\"rotate(-14,32,32)\"><rect x=\"16\" y=\"24\" width=\"32\" height=\"24\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M16 24 L32 14 L48 24\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 19, "stage": 1, "verb": "show up", "meaning": "現れる、姿を見せる", "def": "to arrive or appear, especially at an event", "ex1": "He showed up an hour late.", "ja1": "彼は1時間遅れて現れた。", "ex2": "Two of the attendees didn't show up for the review meeting.", "ja2": "レビュー会議に出席者2名が現れなかった。", "note": "", "nuance": "予定の場に姿を見せる。現れなかった場合の含みで使われることも多い。", "groups": ["appear"], "etymology": "show（見せる）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「現れる、姿を見せる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#1B2A41\"/><g transform=\"rotate(4,32,32)\"><path d=\"M14 32 Q32 16 50 32 Q32 48 14 32 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"32\" cy=\"32\" r=\"7\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 20, "stage": 1, "verb": "turn up", "meaning": "ひょっこり現れる、（なくし物が）出てくる", "def": "to appear, often unexpectedly; to be found by chance", "ex1": "My lost wallet turned up in the car.", "ja1": "なくした財布が車の中から出てきた。", "ex2": "The missing invoice turned up in the shared folder.", "ja2": "見つからなかった請求書が共有フォルダから出てきた。", "note": "show up より「予想外」の含みが強い", "nuance": "予想外に見つかる・現れるという偶然性が強い。show upより意外性がある。", "groups": ["appear"], "etymology": "turn（向きを変える）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「ひょっこり現れる、（なくし物が）出てくる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-15,32,32)\"><path d=\"M32 32 m-4,0 a4,4 0 1,0 8,0 a8,8 0 1,0 -16,0 a12,12 0 1,0 24,0 a16,16 0 1,0 -32,0\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 21, "stage": 1, "verb": "come up", "meaning": "（話題・用事が）持ち上がる、起こる", "def": "to arise or be mentioned unexpectedly", "ex1": "Your name came up in the meeting.", "ja1": "会議であなたの名前が出た。", "ex2": "A scheduling conflict came up, so we need to reschedule.", "ja2": "予定が重なったので日程を再調整する必要があります。", "note": "Stage 2 の come up*2 と区別", "nuance": "話題や用事が自然発生的に持ち上がる、受け身的なニュアンス。", "groups": ["opportunity_arises"], "etymology": "come（来る）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「（話題・用事が）持ち上がる、起こる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"rotate(-10,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 22, "stage": 1, "verb": "put off", "meaning": "延期する、先延ばしにする", "def": "to postpone something to a later time", "ex1": "We put off the meeting until next week.", "ja1": "会議を来週に延期した。", "ex2": "The client asked us to put off the release until April.", "ja2": "顧客からリリースを4月まで延期するよう依頼された。", "note": "", "nuance": "予定を先延ばしにする。やる気がないというより都合による延期。", "groups": ["postpone"], "etymology": "put（置く）＋off（離れて）\n→ くっついていた物が離れる・停止や出発のイメージ\n→ そこから「延期する、先延ばしにする」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#9A5B2E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(0,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 23, "stage": 1, "verb": "come in", "meaning": "入ってくる", "def": "to enter a room or building", "ex1": "Please come in and have a seat.", "ja1": "どうぞ入って座ってください。", "ex2": "New requirements came in after the design was fixed.", "ja2": "設計確定後に新しい要件が入ってきた。", "note": "", "nuance": "屋内・室内へ入る、シンプルな移動。", "groups": ["enter_various"], "etymology": "come（来る）＋in（中へ）\n→ 外から中に入る・参加や到着のイメージ\n→ そこから「入ってくる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#1B2A41\"/><g transform=\"rotate(-12,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 24, "stage": 1, "verb": "stay in", "meaning": "家にいる、外出しない", "def": "to remain at home instead of going out", "ex1": "Let's stay in and watch a movie.", "ja1": "家にいて映画を見よう。", "ex2": "I stayed in over the weekend to prepare for Monday's presentation.", "ja2": "月曜のプレゼン準備のため週末は家にこもった。", "note": "", "nuance": "外出せず家にとどまる選択を表す。", "groups": ["home_or_out"], "etymology": "stay（とどまる）＋in（中へ）\n→ 外から中に入る・参加や到着のイメージ\n→ そこから「家にいる、外出しない」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"rotate(-12,32,32)\"><path d=\"M22 20 L22 44 L42 44 L42 30 M22 32 L42 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M22 44 L20 50 M42 44 L44 50\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 25, "stage": 1, "verb": "take on", "meaning": "（仕事・責任を）引き受ける", "def": "to accept work or responsibility", "ex1": "She took on the new project.", "ja1": "彼女は新しいプロジェクトを引き受けた。", "ex2": "Our team took on the maintenance work from April.", "ja2": "4月から当チームが保守業務を引き受けた。", "note": "", "nuance": "仕事や役割を自分から引き受ける、積極性を伴う。", "groups": ["undertake_continue_work"], "etymology": "take（取る）＋on（接触・継続）\n→ くっついたまま続く・作動し続けるイメージ\n→ そこから「（仕事・責任を）引き受ける」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"rotate(-8,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 26, "stage": 1, "verb": "move on", "meaning": "次に進む、気持ちを切り替える", "def": "to leave one thing and start the next", "ex1": "Let's move on to the next topic.", "ja1": "次の議題に移りましょう。", "ex2": "Let's move on to the next agenda item.", "ja2": "次の議題に移りましょう。", "note": "", "nuance": "前の話題や状況から気持ちを切り替えて次へ進む。", "groups": ["move_on_over"], "etymology": "move（動く）＋on（接触・継続）\n→ くっついたまま続く・作動し続けるイメージ\n→ そこから「次に進む、気持ちを切り替える」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"rotate(8,32,32)\"><rect x=\"16\" y=\"24\" width=\"32\" height=\"24\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M16 24 L32 14 L48 24\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 27, "stage": 1, "verb": "give up", "meaning": "あきらめる、やめる", "def": "to stop trying; to quit a habit", "ex1": "Don't give up so easily.", "ja1": "そんなに簡単にあきらめないで。", "ex2": "We won't give up on meeting the deadline.", "ja2": "納期を守ることをあきらめません。", "note": "", "nuance": "努力や試みをやめる、諦めのニュアンスが強い。", "groups": ["give_up_in"], "etymology": "give（与える）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「あきらめる、やめる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#1B2A41\"/><g transform=\"rotate(7,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 28, "stage": 1, "verb": "get to", "meaning": "〜に到着する", "def": "to arrive at a place", "ex1": "What time do we get to Tokyo?", "ja1": "何時に東京に着きますか。", "ex2": "Please get to the venue 15 minutes before the meeting.", "ja2": "会議の15分前には会場に着いてください。", "note": "Stage 2 / Stage 8 に別語義あり", "nuance": "目的地に到着する動作そのもの。到達点に焦点。", "groups": ["get_to_senses"], "etymology": "get（得る・～になる）＋to（～へ）\n→ 目的地・相手に向かうイメージ\n→ そこから「〜に到着する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-1,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L12 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><circle cx=\"14\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/></g></svg>"}, {"no": 29, "stage": 1, "verb": "keep up", "meaning": "遅れずについていく", "def": "to move or progress at the same rate as others", "ex1": "I can't keep up with you, walk slower.", "ja1": "ついていけないよ、もっとゆっくり歩いて。", "ex2": "It's hard to keep up with the changes in the requirements.", "ja2": "要件の変更についていくのは大変だ。", "note": "後ろに with を伴うことが多い", "nuance": "他者や基準についていく努力を表す。with を伴うことが多い。", "groups": ["catch_up_behind"], "etymology": "keep（保つ）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「遅れずについていく」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#8A4B8A\"/><g transform=\"rotate(-3,32,32)\"><rect x=\"16\" y=\"24\" width=\"32\" height=\"24\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M16 24 L32 14 L48 24\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 30, "stage": 1, "verb": "hold down", "meaning": "（仕事を）続ける／押さえつける", "def": "to keep a job over time; to keep something from moving", "ex1": "He has held down the same job for ten years.", "ja1": "彼は同じ仕事を10年続けている。", "ex2": "She has held down the project manager role for three years.", "ja2": "彼女は3年間プロジェクトマネージャーを務めている。", "note": "", "nuance": "仕事や地位を維持する意味と、物理的に押さえる意味の両方がある。", "groups": ["undertake_continue_work"], "etymology": "hold（持つ・保つ）＋down（下へ）\n→ 下向き・減少や書き留めるイメージ\n→ そこから「（仕事を）続ける／押さえつける」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(8,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 16 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 31, "stage": 1, "verb": "hand in", "meaning": "提出する", "def": "to submit something to a person in authority", "ex1": "Hand in your report by Friday.", "ja1": "金曜までにレポートを提出してください。", "ex2": "Please hand in your expense report by the end of the month.", "ja2": "月末までに経費精算書を提出してください。", "note": "", "nuance": "書類などを正式に提出する、事務的な響き。", "groups": ["submit"], "etymology": "hand（手渡す）＋in（中へ）\n→ 外から中に入る・参加や到着のイメージ\n→ そこから「提出する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"rotate(11,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 32, "stage": 1, "verb": "get away", "meaning": "逃げる、（休暇で）出かける", "def": "to escape; to leave for a short break or trip", "ex1": "The thief got away before the police arrived.", "ja1": "泥棒は警察が来る前に逃げた。", "ex2": "I couldn't get away from the office until eight.", "ja2": "8時までオフィスを離れられなかった。", "note": "", "nuance": "その場や状況から逃れる、束の間の解放感も含む。", "groups": ["escape_run_away"], "etymology": "get（得る・～になる）＋away（遠くへ）\n→ その場から遠ざかる・消えていくイメージ\n→ そこから「逃げる、（休暇で）出かける」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#2E6B4F\"/><g transform=\"rotate(0,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-dasharray=\"3 2\" stroke-linecap=\"round\"/><path d=\"M11 3 L16 8 L11 13\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 33, "stage": 1, "verb": "go ahead", "meaning": "先に進める、（許可して）どうぞ", "def": "to proceed with something; to give permission to start", "ex1": "Go ahead, I'm listening.", "ja1": "どうぞ、聞いていますよ。", "ex2": "Shall we go ahead with the current schedule?", "ja2": "現行のスケジュールで進めてよろしいですか。", "note": "", "nuance": "許可を与える／計画を進める、前向きな後押しのニュアンス。", "groups": [], "etymology": "go（行く）＋ahead（先へ）\n→ 前方・先に進むイメージ\n→ そこから「先に進める、（許可して）どうぞ」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"rotate(-1,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L10 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><path d=\"M12 3 L12 13 M15 3 L15 13\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 34, "stage": 1, "verb": "come from", "meaning": "〜の出身である、〜に由来する", "def": "to originate from a place or source", "ex1": "Where do you come from?", "ja1": "ご出身はどちらですか。", "ex2": "Most of our revenue comes from the domestic market.", "ja2": "売上の大半は国内市場によるものです。", "note": "", "nuance": "出身や由来を述べる、事実を淡々と伝える表現。", "groups": [], "etymology": "come（来る）＋from（～から）\n→ ある地点から離れるイメージ\n→ そこから「〜の出身である、〜に由来する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#9A5B2E\"/><g transform=\"rotate(-15,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"2\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/><path d=\"M4 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 35, "stage": 1, "verb": "go together", "meaning": "似合う、調和する", "def": "to match or suit each other well", "ex1": "Those shoes and that bag go together nicely.", "ja1": "その靴とそのバッグはよく合う。", "ex2": "Cost reduction and quality improvement don't always go together.", "ja2": "コスト削減と品質向上は必ずしも両立しない。", "note": "", "nuance": "複数のものが調和して合うという評価的な意味合い。", "groups": ["match_suit"], "etymology": "go（行く）＋together（一つに）\n→ バラバラだった物が一つにまとまるイメージ\n→ そこから「似合う、調和する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#8A4B8A\"/><g transform=\"rotate(-4,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 2 L8 8 L0 14 M16 2 L8 8 L16 14\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 36, "stage": 1, "verb": "get into", "meaning": "中に入る／〜に夢中になる", "def": "to enter a place; to become interested in something", "ex1": "How did you get into the building?", "ja1": "どうやって建物に入ったのですか。", "ex2": "It took time to get into the details of the contract.", "ja2": "契約の詳細に踏み込むのに時間がかかった。", "note": "", "nuance": "物理的に中へ入る意味と、趣味にはまる意味の両方で使われる。", "groups": ["enter_various"], "etymology": "get（得る・～になる）＋into（中へ変化）\n→ ある状態の中に入り込む・変化を伴うイメージ\n→ そこから「中に入る／〜に夢中になる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#9A5B2E\"/><g transform=\"rotate(-15,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 37, "stage": 1, "verb": "put up", "meaning": "（看板・テントなどを）掲げる、建てる", "def": "to build or place something in position", "ex1": "They put up a new sign outside.", "ja1": "外に新しい看板を掲げた。", "ex2": "They put up a notice about the system maintenance.", "ja2": "システムメンテナンスの掲示を出した。", "note": "Stage 2 / Stage 5 に別語義あり", "nuance": "看板やテントを設置する意味と、人を泊める意味（Stage2）がある。", "groups": ["put_up_senses"], "etymology": "put（置く）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「（看板・テントなどを）掲げる、建てる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#1B2A41\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-8,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 38, "stage": 1, "verb": "go away", "meaning": "立ち去る、（症状などが）消える", "def": "to leave a place; to disappear", "ex1": "Go away, I'm busy.", "ja1": "あっちへ行って、忙しいの。", "ex2": "The problem won't go away unless we fix the root cause.", "ja2": "根本原因を直さない限り問題はなくならない。", "note": "", "nuance": "立ち去れという命令にも、症状が消えるという意味にも使う。", "groups": ["leave_place"], "etymology": "go（行く）＋away（遠くへ）\n→ その場から遠ざかる・消えていくイメージ\n→ そこから「立ち去る、（症状などが）消える」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#1B2A41\"/><g transform=\"rotate(-8,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-dasharray=\"3 2\" stroke-linecap=\"round\"/><path d=\"M11 3 L16 8 L11 13\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 39, "stage": 1, "verb": "go down", "meaning": "下がる、（日が）沈む", "def": "to decrease; to move downward", "ex1": "Prices went down last month.", "ja1": "先月、価格が下がった。", "ex2": "Our operating costs went down by ten percent.", "ja2": "運用コストが10パーセント下がった。", "note": "Stage 7 の go down*2 と区別", "nuance": "数値が下がる意味と、日が沈む意味の両方で頻出。", "groups": ["go_down_senses"], "etymology": "go（行く）＋down（下へ）\n→ 下向き・減少や書き留めるイメージ\n→ そこから「下がる、（日が）沈む」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"rotate(-14,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 16 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 40, "stage": 1, "verb": "get behind", "meaning": "遅れをとる、滞る", "def": "to fall behind a schedule or fail to keep up", "ex1": "I got behind on my work.", "ja1": "仕事が遅れてしまった。", "ex2": "The project got behind schedule by two weeks.", "ja2": "プロジェクトは2週間スケジュールが遅れた。", "note": "Stage 6 の get behind*2 と区別", "nuance": "予定より遅れてしまう状態。責任のニュアンスを伴うことも。", "groups": ["catch_up_behind"], "etymology": "get（得る・～になる）＋behind（後ろに）\n→ 後方に取り残されるイメージ\n→ そこから「遅れをとる、滞る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-2,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M3 3 L3 13 M6 3 L6 13\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 41, "stage": 1, "verb": "go out", "meaning": "外出する、出かける", "def": "to leave home for an activity", "ex1": "Let's go out for dinner.", "ja1": "夕食に出かけよう。", "ex2": "The team went out for dinner after the release.", "ja2": "リリース後、チームは夕食に出かけた。", "note": "", "nuance": "気分転換や食事などのために外出する、日常的な表現。", "groups": ["home_or_out"], "etymology": "go（行く）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「外出する、出かける」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-1,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 42, "stage": 1, "verb": "go up to", "meaning": "〜に近づく、歩み寄る", "def": "to approach someone or something", "ex1": "He went up to her and said hello.", "ja1": "彼は彼女に近づいてあいさつした。", "ex2": "He went up to the client and introduced himself.", "ja2": "彼は顧客に歩み寄って自己紹介した。", "note": "", "nuance": "人や物に歩み寄る動作、対人的な近づき方を表す。", "groups": [], "etymology": "go（行く）＋to（～へ）\n→ 目的地・相手に向かうイメージ\n→ そこから「〜に近づく、歩み寄る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#2E6B4F\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(8,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L12 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><circle cx=\"14\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/></g></svg>"}, {"no": 43, "stage": 1, "verb": "turn on", "meaning": "（電源・明かりを）つける", "def": "to start a machine, light, or device", "ex1": "Turn on the light, please.", "ja1": "電気をつけてください。", "ex2": "Please turn on the projector before the meeting starts.", "ja2": "会議が始まる前にプロジェクターをつけてください。", "note": "元リストの turn on/off を分割", "nuance": "電源を入れる動作。日常会話で最頻出クラス。", "groups": ["power"], "etymology": "turn（向きを変える）＋on（接触・継続）\n→ くっついたまま続く・作動し続けるイメージ\n→ そこから「（電源・明かりを）つける」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#9A5B2E\"/><g transform=\"rotate(-7,32,32)\"><path d=\"M32 32 m-4,0 a4,4 0 1,0 8,0 a8,8 0 1,0 -16,0 a12,12 0 1,0 24,0 a16,16 0 1,0 -32,0\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 44, "stage": 1, "verb": "turn off", "meaning": "（電源・明かりを）消す", "def": "to stop a machine, light, or device", "ex1": "Turn off the air conditioner before you leave.", "ja1": "出かける前にエアコンを消して。", "ex2": "Turn off your microphone when you are not speaking.", "ja2": "話していないときはマイクをオフにしてください。", "note": "元リストの turn on/off を分割", "nuance": "電源を切る動作。turn onと対で覚えるべき基本語。", "groups": ["power"], "etymology": "turn（向きを変える）＋off（離れて）\n→ くっついていた物が離れる・停止や出発のイメージ\n→ そこから「（電源・明かりを）消す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#9A5B2E\"/><g transform=\"rotate(-13,32,32)\"><path d=\"M32 32 m-4,0 a4,4 0 1,0 8,0 a8,8 0 1,0 -16,0 a12,12 0 1,0 24,0 a16,16 0 1,0 -32,0\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 45, "stage": 1, "verb": "run into", "meaning": "偶然出会う／（問題に）ぶつかる", "def": "to meet by chance; to encounter a problem", "ex1": "I ran into an old friend at the station.", "ja1": "駅で昔の友人に偶然会った。", "ex2": "We ran into a problem during the data migration.", "ja2": "データ移行中に問題にぶつかった。", "note": "", "nuance": "偶然の遭遇と、問題への遭遇の両方に使える便利な表現。", "groups": ["encounter"], "etymology": "run（走る）＋into（中へ変化）\n→ ある状態の中に入り込む・変化を伴うイメージ\n→ そこから「偶然出会う／（問題に）ぶつかる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"rotate(5,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 46, "stage": 1, "verb": "put away", "meaning": "片づける、しまう", "def": "to return something to its proper place", "ex1": "Put away your toys.", "ja1": "おもちゃを片づけなさい。", "ex2": "Please put away the confidential documents after the meeting.", "ja2": "会議後は機密書類をしまってください。", "note": "", "nuance": "元の場所に戻してしまう、片づけの完了を意味する。", "groups": ["tidy_up"], "etymology": "put（置く）＋away（遠くへ）\n→ その場から遠ざかる・消えていくイメージ\n→ そこから「片づける、しまう」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#8A4B8A\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-10,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-dasharray=\"3 2\" stroke-linecap=\"round\"/><path d=\"M11 3 L16 8 L11 13\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 47, "stage": 1, "verb": "turn out", "meaning": "結局〜になる、〜と判明する", "def": "to happen or end in a particular way; to prove to be", "ex1": "The party turned out to be a big success.", "ja1": "パーティーは大成功に終わった。", "ex2": "The estimate turned out to be too optimistic.", "ja2": "見積もりは楽観的すぎたと判明した。", "note": "", "nuance": "結果的にそうなった、という予想外の結末を表すことが多い。", "groups": ["turn_out_end_up"], "etymology": "turn（向きを変える）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「結局〜になる、〜と判明する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"rotate(-15,32,32)\"><path d=\"M32 32 m-4,0 a4,4 0 1,0 8,0 a8,8 0 1,0 -16,0 a12,12 0 1,0 24,0 a16,16 0 1,0 -32,0\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 48, "stage": 1, "verb": "look up to", "meaning": "尊敬する", "def": "to admire and respect someone", "ex1": "I look up to my grandfather.", "ja1": "私は祖父を尊敬している。", "ex2": "The younger members look up to him as a mentor.", "ja2": "若手メンバーは彼をメンターとして尊敬している。", "note": "反意は look down on", "nuance": "尊敬の対象として見上げる比喩。look down onの反対。", "groups": [], "etymology": "look（見る）＋to（～へ）\n→ 目的地・相手に向かうイメージ\n→ そこから「尊敬する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-12,32,32)\"><path d=\"M14 32 Q32 16 50 32 Q32 48 14 32 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"32\" cy=\"32\" r=\"7\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L12 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><circle cx=\"14\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/></g></svg>"}, {"no": 49, "stage": 1, "verb": "ask for", "meaning": "求める、頼む", "def": "to request something", "ex1": "He asked for a glass of water.", "ja1": "彼は水を1杯頼んだ。", "ex2": "The client asked for a revised quotation.", "ja2": "顧客は見積もりの修正を求めた。", "note": "", "nuance": "何かを求める、依頼する行為。丁寧さは文脈次第。", "groups": [], "etymology": "ask（尋ねる）＋for（求めて）\n→ 目的物を求めて手を伸ばすイメージ\n→ そこから「求める、頼む」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(11,32,32)\"><path d=\"M14 20 Q14 16 18 16 L46 16 Q50 16 50 20 L50 36 Q50 40 46 40 L26 40 L18 48 L20 40 L18 40 Q14 40 14 36 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/><path d=\"M0 8 L11 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 50, "stage": 1, "verb": "shut up", "meaning": "黙る", "def": "to stop talking", "ex1": "Shut up and listen.", "ja1": "黙って聞きなさい。", "ex2": "Telling a colleague to shut up would be unacceptable at work.", "ja2": "同僚に「黙れ」と言うのは職場では許されない。", "note": "かなり無礼。目上には使わない", "nuance": "かなり強い命令で、目上には使えない。ビジネスでは避けるべき表現。", "groups": ["imperative_expr"], "etymology": "shut（閉める）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「黙る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"rotate(11,32,32)\"><rect x=\"20\" y=\"14\" width=\"24\" height=\"38\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"38\" cy=\"34\" r=\"2\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 51, "stage": 1, "verb": "throw away", "meaning": "捨てる", "def": "to dispose of something you no longer want", "ex1": "Don't throw away those documents.", "ja1": "その書類を捨てないで。", "ex2": "Don't throw away the meeting notes; we may need them for the report.", "ja2": "議事メモを捨てないで、報告書で必要になるかもしれない。", "note": "", "nuance": "不要なものを処分する、シンプルな廃棄行為。", "groups": ["discard"], "etymology": "throw（投げる）＋away（遠くへ）\n→ その場から遠ざかる・消えていくイメージ\n→ そこから「捨てる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#8A4B8A\"/><g transform=\"rotate(-8,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-dasharray=\"3 2\" stroke-linecap=\"round\"/><path d=\"M11 3 L16 8 L11 13\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 53, "stage": 2, "verb": "freshen up", "meaning": "さっぱりする、身支度を整える", "def": "to wash and make yourself look tidy", "ex1": "I'd like to freshen up before dinner.", "ja1": "夕食前に身支度を整えたい。", "ex2": "Let's freshen up before we meet the client.", "ja2": "顧客に会う前に身なりを整えよう。", "note": "", "nuance": "身だしなみを整える、軽く洗顔・化粧直しするイメージ。", "groups": [], "etymology": "freshen（新鮮にする）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「さっぱりする、身支度を整える」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-1,32,32)\"><path d=\"M14 32 Q20 22 26 32 Q32 42 38 32 Q44 22 50 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 54, "stage": 2, "verb": "check in", "meaning": "チェックインする、受付を済ませる", "def": "to register at a hotel, airport, or event", "ex1": "We checked in at the hotel around three.", "ja1": "3時ごろホテルにチェックインした。", "ex2": "Please check in at the reception desk on the first floor.", "ja2": "1階の受付で受付を済ませてください。", "note": "", "nuance": "ホテルや空港での手続き。手続き完了までを含む。", "groups": ["hotel_checkin"], "etymology": "check（確認する）＋in（中へ）\n→ 外から中に入る・参加や到着のイメージ\n→ そこから「チェックインする、受付を済ませる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#1B2A41\"/><g transform=\"rotate(-3,32,32)\"><path d=\"M32 20 Q24 14 16 18 L16 44 Q24 40 32 46 Q40 40 48 44 L48 18 Q40 14 32 20 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 55, "stage": 2, "verb": "check out", "meaning": "チェックアウトする", "def": "to pay and leave a hotel", "ex1": "We have to check out by eleven.", "ja1": "11時までにチェックアウトしないといけない。", "ex2": "I checked out early to make the morning meeting.", "ja2": "朝の会議に間に合うよう早めにチェックアウトした。", "note": "Stage 3 / 6 に別語義あり", "nuance": "ホテルの精算・退室。Stage3・6の別義と区別が必要。", "groups": ["hotel_checkin"], "etymology": "check（確認する）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「チェックアウトする」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#1B2A41\"/><g transform=\"rotate(1,32,32)\"><path d=\"M32 20 Q24 14 16 18 L16 44 Q24 40 32 46 Q40 40 48 44 L48 18 Q40 14 32 20 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 56, "stage": 2, "verb": "pick out", "meaning": "選び出す", "def": "to choose one thing from a group", "ex1": "She picked out a dress for the party.", "ja1": "彼女はパーティー用のドレスを選んだ。", "ex2": "Please pick out three candidates for the interview.", "ja2": "面接の候補者を3名選んでください。", "note": "", "nuance": "複数の中から目的のものを選び取る、選別のニュアンス。", "groups": ["choose"], "etymology": "pick（つまむ・選ぶ）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「選び出す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-15,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 57, "stage": 2, "verb": "get together", "meaning": "集まる", "def": "to meet with other people socially or for a purpose", "ex1": "Let's get together this weekend.", "ja1": "今週末に集まろう。", "ex2": "Can we get together to review the draft?", "ja2": "草案を確認するために集まれますか。", "note": "Stage 3 に別語義あり", "nuance": "人が集まる意味。Stage3のget together*2（まとめる）と別。", "groups": ["gather"], "etymology": "get（得る・～になる）＋together（一つに）\n→ バラバラだった物が一つにまとまるイメージ\n→ そこから「集まる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"rotate(-14,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 2 L8 8 L0 14 M16 2 L8 8 L16 14\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 58, "stage": 2, "verb": "go through", "meaning": "一通り目を通す／（つらい経験を）経る", "def": "to examine in detail; to experience something difficult", "ex1": "I went through my old photos.", "ja1": "古い写真を一通り見た。", "ex2": "Let's go through the agenda before we start.", "ja2": "始める前に議題に目を通しましょう。", "note": "", "nuance": "内容を一通り確認する意味と、つらい経験を経る意味の両方。", "groups": ["skim_review"], "etymology": "go（行く）＋through（通り抜けて）\n→ 最初から最後まで通り抜けるイメージ\n→ そこから「一通り目を通す／（つらい経験を）経る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"rotate(-3,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-dasharray=\"3 2\"/><path d=\"M0 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 59, "stage": 2, "verb": "put down", "meaning": "下に置く", "def": "to place something on a surface", "ex1": "Put down your bag and relax.", "ja1": "かばんを置いてくつろいで。", "ex2": "He put down his pen and looked at the screen.", "ja2": "彼はペンを置いて画面を見た。", "note": "Stage 3 / 4 に別語義あり", "nuance": "物を下に置く単純動作。Stage3・4に比喩的な別義あり。", "groups": ["put_down_senses"], "etymology": "put（置く）＋down（下へ）\n→ 下向き・減少や書き留めるイメージ\n→ そこから「下に置く」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-6,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 16 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 60, "stage": 2, "verb": "try on", "meaning": "試着する", "def": "to put on clothing to see if it fits or suits you", "ex1": "Can I try on these shoes?", "ja1": "この靴を試着できますか。", "ex2": "She tried on the uniform before the trade show.", "ja2": "展示会の前に彼女は制服を試着した。", "note": "", "nuance": "服を実際に着てサイズ感を確認する行為。", "groups": ["clothing_wear"], "etymology": "try（試す）＋on（接触・継続）\n→ くっついたまま続く・作動し続けるイメージ\n→ そこから「試着する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(7,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"14\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"32\" cy=\"32\" r=\"7\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"32\" cy=\"32\" r=\"2\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 61, "stage": 2, "verb": "hold on", "meaning": "少し待つ、電話を切らずに待つ", "def": "to wait for a short time", "ex1": "Hold on, I'm almost ready.", "ja1": "待って、もうすぐ準備できる。", "ex2": "Could you hold on while I transfer your call?", "ja2": "お電話をおつなぎしますので少々お待ちください。", "note": "", "nuance": "少し待ってという指示。電話でもよく使われる。", "groups": ["wait"], "etymology": "hold（持つ・保つ）＋on（接触・継続）\n→ くっついたまま続く・作動し続けるイメージ\n→ そこから「少し待つ、電話を切らずに待つ」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#9A5B2E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(13,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 62, "stage": 2, "verb": "give out", "meaning": "（無料サンプルなどを）配る", "def": "to distribute something to a group of people", "ex1": "They gave out free samples at the store.", "ja1": "店で無料サンプルを配っていた。", "ex2": "Please give out the handouts before the session starts.", "ja2": "セッション開始前に資料を配ってください。", "note": "Stage 2 の give out*2 と区別", "nuance": "無償で配布する行為。give out*2（尽きる）と混同注意。", "groups": ["distribute"], "etymology": "give（与える）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「（無料サンプルなどを）配る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"rotate(-6,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 63, "stage": 2, "verb": "pick up", "meaning": "拾い上げる／車で迎えに行く", "def": "to lift something up; to collect someone in a vehicle", "ex1": "Pick up the towel from the floor.", "ja1": "床のタオルを拾って。", "ex2": "I'll pick you up at the station at nine.", "ja2": "9時に駅までお迎えに行きます。", "note": "Stage 3 / 7 / 8 に別語義あり", "nuance": "拾う・迎えに行く・電話に出るなど文脈で意味が広がる基本語。", "groups": ["pick_up_senses"], "etymology": "pick（つまむ・選ぶ）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「拾い上げる／車で迎えに行く」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-10,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 64, "stage": 2, "verb": "fall over", "meaning": "つまずいて転ぶ", "def": "to fall to the ground", "ex1": "He tripped and fell over.", "ja1": "彼はつまずいて転んだ。", "ex2": "The display panel fell over during setup.", "ja2": "設営中に展示パネルが倒れた。", "note": "", "nuance": "つまずいて転ぶ、やや不注意による転倒のニュアンス。", "groups": ["fall_down"], "etymology": "fall（落ちる）＋over（越えて）\n→ 何かを越えて広がる・一通り目を通すイメージ\n→ そこから「つまずいて転ぶ」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#9A5B2E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-3,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 2 A6 6 0 1 1 2 8\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2.2\"/><path d=\"M2 8 L0 4 M2 8 L6 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 65, "stage": 2, "verb": "get up", "meaning": "起きる、立ち上がる", "def": "to get out of bed; to rise to your feet", "ex1": "I get up at six every morning.", "ja1": "毎朝6時に起きる。", "ex2": "He got up to greet the visitors.", "ja2": "彼は来客を迎えるために立ち上がった。", "note": "", "nuance": "起床や起立の動作、日常的で頻出。", "groups": ["get_up_stand_up"], "etymology": "get（得る・～になる）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「起きる、立ち上がる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#9A5B2E\"/><g transform=\"rotate(7,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 66, "stage": 2, "verb": "run out of", "meaning": "〜を切らす、使い果たす", "def": "to have no more of something left", "ex1": "We ran out of milk.", "ja1": "牛乳を切らしてしまった。", "ex2": "We're running out of time, so let's decide today.", "ja2": "時間がなくなってきたので今日決めましょう。", "note": "", "nuance": "在庫や時間を使い果たす、切迫感を伴う表現。", "groups": ["use_up"], "etymology": "run（走る）＋of（～の）\n→ 対象を分離・限定するイメージ\n→ そこから「〜を切らす、使い果たす」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"rotate(5,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M4 4 L12 12 M4 12 L12 4\" stroke=\"#B5392F\" stroke-width=\"1.8\" stroke-linecap=\"round\" opacity=\"0.7\"/></g></svg>"}, {"no": 67, "stage": 2, "verb": "walk out", "meaning": "途中で出ていく、席を立つ", "def": "to leave suddenly, often in protest", "ex1": "She walked out in the middle of the movie.", "ja1": "彼女は映画の途中で出ていった。", "ex2": "Two members walked out of the negotiation.", "ja2": "交渉の場から2名が席を立って出ていった。", "note": "", "nuance": "抗議や不満を示して途中で退席する強いニュアンス。", "groups": ["leave_place"], "etymology": "walk（歩く）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「途中で出ていく、席を立つ」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"rotate(14,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 68, "stage": 2, "verb": "catch up", "meaning": "追いつく、遅れを取り戻す", "def": "to reach the same level or position as others", "ex1": "Go ahead, I'll catch up.", "ja1": "先に行って、追いつくから。", "ex2": "We need to catch up on the delayed tasks.", "ja2": "遅れているタスクを取り戻す必要がある。", "note": "Stage 4 に別語義あり", "nuance": "距離や遅れを取り戻す努力を表す。catch up*2（近況を話す）とは別義。", "groups": ["catch_up_behind"], "etymology": "catch（捕まえる）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「追いつく、遅れを取り戻す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#2E6B4F\"/><g transform=\"rotate(-4,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 69, "stage": 2, "verb": "work out", "meaning": "うまくいく／運動する", "def": "to end successfully; to do physical exercise", "ex1": "I work out at the gym twice a week.", "ja1": "週2回ジムで運動している。", "ex2": "I'm sure the new process will work out.", "ja2": "新しい手順はうまくいくと思う。", "note": "Stage 3 / 4 に別語義あり", "nuance": "運動する意味とうまくいく意味、両方頻出の基本語。", "groups": ["succeed"], "etymology": "work（働く・作用させる）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「うまくいく／運動する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"rotate(6,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"10\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M32 14 L32 20 M32 44 L32 50 M14 32 L20 32 M44 32 L50 32 M20 20 L24 24 M40 40 L44 44 M44 20 L40 24 M24 40 L20 44\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 70, "stage": 2, "verb": "turn back", "meaning": "引き返す", "def": "to return the way you came", "ex1": "It started raining, so we turned back.", "ja1": "雨が降り出したので引き返した。", "ex2": "Once the contract is signed, we can't turn back.", "ja2": "契約を結んだら後戻りはできない。", "note": "", "nuance": "来た道を引き返す、後戻りの動作。", "groups": ["turn_direction"], "etymology": "turn（向きを変える）＋back（後ろ・元へ）\n→ 元の場所や状態に戻るイメージ\n→ そこから「引き返す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-1,32,32)\"><path d=\"M32 32 m-4,0 a4,4 0 1,0 8,0 a8,8 0 1,0 -16,0 a12,12 0 1,0 24,0 a16,16 0 1,0 -32,0\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M14 4 Q4 4 4 12 M4 12 L0 9 M4 12 L8 12\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 71, "stage": 2, "verb": "go after", "meaning": "追いかける、（目標を）狙う", "def": "to chase or pursue someone or something", "ex1": "The dog went after the ball.", "ja1": "犬はボールを追いかけた。", "ex2": "We're going after the mid-size enterprise market.", "ja2": "我々は中堅企業市場を狙っている。", "note": "", "nuance": "対象を追いかける、目標を追求する意味も。", "groups": [], "etymology": "go（行く）＋after（後を追って）\n→ 対象の後ろについていくイメージ\n→ そこから「追いかける、（目標を）狙う」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#9A5B2E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-2,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-dasharray=\"2 2\"/><path d=\"M9 3 L15 8 L9 13\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 72, "stage": 2, "verb": "stand up", "meaning": "立ち上がる", "def": "to rise to a standing position", "ex1": "Everyone stood up when the music started.", "ja1": "音楽が始まると全員が立ち上がった。", "ex2": "Please stand up and introduce yourself.", "ja2": "立って自己紹介をしてください。", "note": "Stage 2 の stand up*2 と区別", "nuance": "起立する動作。stand up*2（すっぽかす）とは全く別の意味。", "groups": ["get_up_stand_up"], "etymology": "stand（立つ）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「立ち上がる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"rotate(-15,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 73, "stage": 2, "verb": "speak up", "meaning": "大きな声で話す、意見を述べる", "def": "to speak more loudly; to express your opinion openly", "ex1": "Could you speak up? I can't hear you.", "ja1": "もっと大きな声で話してもらえますか、聞こえません。", "ex2": "If you disagree, please speak up in the meeting.", "ja2": "反対なら会議で意見を述べてください。", "note": "", "nuance": "声を張って話す、または意見を表明する勇気を示す表現。", "groups": ["speak_loudly"], "etymology": "speak（話す）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「大きな声で話す、意見を述べる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"rotate(-5,32,32)\"><path d=\"M14 20 Q14 16 18 16 L46 16 Q50 16 50 20 L50 36 Q50 40 46 40 L26 40 L18 48 L20 40 L18 40 Q14 40 14 36 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 74, "stage": 2, "verb": "pass on", "meaning": "（情報を）伝える、渡す", "def": "to give information or an item to another person", "ex1": "Can you pass on the message to your sister?", "ja1": "お姉さんに伝言を伝えてもらえますか。", "ex2": "I'll pass on your feedback to the development team.", "ja2": "いただいたご意見を開発チームに伝えます。", "note": "", "nuance": "情報や伝言を人から人へ伝える、仲介のニュアンス。", "groups": ["convey_info"], "etymology": "pass（通す・渡す）＋on（接触・継続）\n→ くっついたまま続く・作動し続けるイメージ\n→ そこから「（情報を）伝える、渡す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"rotate(3,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 75, "stage": 2, "verb": "come along", "meaning": "一緒に来る／進展する", "def": "to accompany someone; to make progress", "ex1": "Why don't you come along with us?", "ja1": "一緒に来ませんか。", "ex2": "How is the proposal coming along?", "ja2": "提案書の進み具合はいかがですか。", "note": "Stage 5 に別語義あり", "nuance": "一緒について行く意味と、物事が進展する意味がある。", "groups": [], "etymology": "come（来る）＋along（沿って）\n→ 一緒に・並んで進むイメージ\n→ そこから「一緒に来る／進展する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"rotate(2,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 5 L16 5 M0 11 L16 11\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 76, "stage": 2, "verb": "come up*2", "meaning": "（機会・話が）出てくる、生じる", "def": "to become available or arise, e.g. an opportunity", "ex1": "A cheap ticket came up at the last minute.", "ja1": "直前に安いチケットが出てきた。", "ex2": "If a suitable position comes up, I'll let you know.", "ja2": "適したポジションが空いたらお知らせします。", "note": "Stage 1 の come up と区別", "nuance": "come up（Stage1、話題が上がる）とは別に、機会が生じる意味。", "groups": ["opportunity_arises"], "etymology": "come（来る）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「（機会・話が）出てくる、生じる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"rotate(-10,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 77, "stage": 2, "verb": "stand out", "meaning": "目立つ、際立つ", "def": "to be noticeably better or different from others", "ex1": "Her red coat stood out in the crowd.", "ja1": "彼女の赤いコートは人混みで目立った。", "ex2": "This proposal stands out because of its cost advantage.", "ja2": "この提案はコスト面の優位性で際立っている。", "note": "", "nuance": "周囲より際立って目立つ、良い意味での卓越。", "groups": ["stand_out_show_off"], "etymology": "stand（立つ）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「目立つ、際立つ」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-6,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 78, "stage": 2, "verb": "go over to", "meaning": "〜へ移動する、〜側につく", "def": "to move to another place or switch to another side", "ex1": "Let's go over to the café across the street.", "ja1": "通りの向かいのカフェへ行こう。", "ex2": "Several clients went over to a competitor.", "ja2": "何社かの顧客が競合他社に移った。", "note": "", "nuance": "場所を移動する意味と、立場を変える（寝返る）意味がある。", "groups": ["head_toward"], "etymology": "go（行く）＋to（～へ）\n→ 目的地・相手に向かうイメージ\n→ そこから「〜へ移動する、〜側につく」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(12,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L12 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><circle cx=\"14\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/></g></svg>"}, {"no": 79, "stage": 2, "verb": "head to", "meaning": "〜へ向かう", "def": "to go in the direction of a place", "ex1": "We're heading to the beach.", "ja1": "私たちはビーチへ向かっている。", "ex2": "I'm heading to the client's office now.", "ja2": "これから顧客のオフィスへ向かいます。", "note": "", "nuance": "目的地に向かって進む、方向性を示す表現。", "groups": ["head_toward"], "etymology": "head（向かう）＋to（～へ）\n→ 目的地・相手に向かうイメージ\n→ そこから「〜へ向かう」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#9A5B2E\"/><g transform=\"rotate(-12,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L12 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><circle cx=\"14\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/></g></svg>"}, {"no": 80, "stage": 2, "verb": "look around", "meaning": "見て回る", "def": "to look at the things around you; to browse a place", "ex1": "We looked around the museum for two hours.", "ja1": "2時間ほど博物館を見て回った。", "ex2": "Feel free to look around the factory floor.", "ja2": "工場内を自由に見て回ってください。", "note": "", "nuance": "特定の目的なく周囲を見て回る、観光的なニュアンス。", "groups": [], "etymology": "look（見る）＋around（周りに）\n→ あちこち・ぐるりと回るイメージ\n→ そこから「見て回る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#9A5B2E\"/><g transform=\"rotate(9,32,32)\"><path d=\"M14 32 Q32 16 50 32 Q32 48 14 32 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"32\" cy=\"32\" r=\"7\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 2 A6 6 0 1 1 2 8\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2.2\"/><path d=\"M2 8 L0 4 M2 8 L6 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 81, "stage": 2, "verb": "get through", "meaning": "やり遂げる、乗り切る", "def": "to finish or survive something difficult", "ex1": "I finally got through the exam period.", "ja1": "ようやく試験期間を乗り切った。", "ex2": "We got through the whole agenda in an hour.", "ja2": "1時間で議題をすべて片づけた。", "note": "", "nuance": "困難を乗り越えて終える、達成感を伴う表現。", "groups": ["accomplish_through"], "etymology": "get（得る・～になる）＋through（通り抜けて）\n→ 最初から最後まで通り抜けるイメージ\n→ そこから「やり遂げる、乗り切る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(9,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-dasharray=\"3 2\"/><path d=\"M0 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 82, "stage": 2, "verb": "turn in", "meaning": "提出する／床につく", "def": "to submit something; to go to bed", "ex1": "I'm tired, so I'll turn in early tonight.", "ja1": "疲れたので今夜は早く寝ます。", "ex2": "Please turn in the timesheet by Friday.", "ja2": "金曜までに勤務表を提出してください。", "note": "Stage 6 に別語義あり", "nuance": "書類提出の意味と、就寝の意味の両方（Stage6に別義あり）。", "groups": ["submit"], "etymology": "turn（向きを変える）＋in（中へ）\n→ 外から中に入る・参加や到着のイメージ\n→ そこから「提出する／床につく」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#1B2A41\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-11,32,32)\"><path d=\"M32 32 m-4,0 a4,4 0 1,0 8,0 a8,8 0 1,0 -16,0 a12,12 0 1,0 24,0 a16,16 0 1,0 -32,0\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 83, "stage": 2, "verb": "get along", "meaning": "仲良くやる、うまくやっていく", "def": "to have a good relationship with someone", "ex1": "The two brothers get along well.", "ja1": "その兄弟は仲がいい。", "ex2": "He gets along well with the client's team.", "ja2": "彼は顧客側のチームとうまくやっている。", "note": "", "nuance": "人間関係が良好であることを表す、穏やかな表現。", "groups": ["relationship_harmony"], "etymology": "get（得る・～になる）＋along（沿って）\n→ 一緒に・並んで進むイメージ\n→ そこから「仲良くやる、うまくやっていく」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(14,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 5 L16 5 M0 11 L16 11\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 84, "stage": 2, "verb": "fool around", "meaning": "ふざける、時間を無駄にする", "def": "to behave in a silly way; to waste time", "ex1": "Stop fooling around and finish your homework.", "ja1": "ふざけるのをやめて宿題を終わらせなさい。", "ex2": "We can't fool around; the deadline is tomorrow.", "ja2": "ふざけている場合ではない、締切は明日だ。", "note": "", "nuance": "ふざけて時間を無駄にする、やや否定的なニュアンス。", "groups": ["slack_off_group"], "etymology": "fool（ふざける）＋around（周りに）\n→ あちこち・ぐるりと回るイメージ\n→ そこから「ふざける、時間を無駄にする」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#8A4B8A\"/><g transform=\"rotate(-12,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"16\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"27\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><circle cx=\"37\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><path d=\"M26 38 Q32 42 38 38\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 2 A6 6 0 1 1 2 8\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2.2\"/><path d=\"M2 8 L0 4 M2 8 L6 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 85, "stage": 2, "verb": "give back", "meaning": "返す、返却する", "def": "to return something to its owner", "ex1": "Give back my umbrella, please.", "ja1": "私の傘を返してください。", "ex2": "Please give back the security card when you leave.", "ja2": "退出時にセキュリティカードを返却してください。", "note": "", "nuance": "借りた物を返す、返却の基本表現。", "groups": ["return_money"], "etymology": "give（与える）＋back（後ろ・元へ）\n→ 元の場所や状態に戻るイメージ\n→ そこから「返す、返却する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#2E6B4F\"/><g transform=\"rotate(-13,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M14 4 Q4 4 4 12 M4 12 L0 9 M4 12 L8 12\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 86, "stage": 2, "verb": "find out", "meaning": "判明する、突き止める", "def": "to discover a fact or piece of information", "ex1": "I found out that the shop was closed.", "ja1": "その店が閉まっていると分かった。", "ex2": "We need to find out why the system failed.", "ja2": "システム障害の原因を突き止める必要がある。", "note": "", "nuance": "調査や発見の結果、事実を知ることになる表現。", "groups": [], "etymology": "find（見つける）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「判明する、突き止める」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"rotate(8,32,32)\"><path d=\"M14 32 Q32 16 50 32 Q32 48 14 32 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"32\" cy=\"32\" r=\"7\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 87, "stage": 2, "verb": "show off", "meaning": "見せびらかす、披露する", "def": "to display something proudly to impress others", "ex1": "He likes to show off his new car.", "ja1": "彼は新しい車を見せびらかしたがる。", "ex2": "The demo is a chance to show off the new features.", "ja2": "デモは新機能を披露する好機だ。", "note": "", "nuance": "自慢げに見せる、やや誇示的なニュアンスを含む。", "groups": ["stand_out_show_off"], "etymology": "show（見せる）＋off（離れて）\n→ くっついていた物が離れる・停止や出発のイメージ\n→ そこから「見せびらかす、披露する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#9A5B2E\"/><g transform=\"rotate(-2,32,32)\"><path d=\"M14 32 Q32 16 50 32 Q32 48 14 32 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"32\" cy=\"32\" r=\"7\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 88, "stage": 2, "verb": "call back", "meaning": "折り返し電話する", "def": "to return a phone call", "ex1": "I'll call you back after lunch.", "ja1": "昼食後に折り返します。", "ex2": "He is in a meeting; may he call you back at three?", "ja2": "彼は会議中です。3時に折り返してもよろしいでしょうか。", "note": "", "nuance": "電話を折り返す、ビジネスでも頻出の丁寧な表現。", "groups": ["call_phone"], "etymology": "call（呼ぶ）＋back（後ろ・元へ）\n→ 元の場所や状態に戻るイメージ\n→ そこから「折り返し電話する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"rotate(-6,32,32)\"><path d=\"M32 16 Q22 16 22 28 L22 38 L18 44 L46 44 L42 38 L42 28 Q42 16 32 16 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M28 44 Q28 48 32 48 Q36 48 36 44\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M14 4 Q4 4 4 12 M4 12 L0 9 M4 12 L8 12\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 89, "stage": 2, "verb": "go off", "meaning": "（警報などが）鳴る、（機器が）止まる", "def": "to make a sudden loud noise; to stop working", "ex1": "My alarm went off at five.", "ja1": "目覚ましが5時に鳴った。", "ex2": "The fire alarm went off during the presentation.", "ja2": "プレゼン中に火災報知器が鳴った。", "note": "", "nuance": "警報が鳴る意味と、機器が停止する意味の両方。", "groups": [], "etymology": "go（行く）＋off（離れて）\n→ くっついていた物が離れる・停止や出発のイメージ\n→ そこから「（警報などが）鳴る、（機器が）止まる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#1B2A41\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(9,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 90, "stage": 2, "verb": "go with", "meaning": "〜に合う／〜を選ぶ", "def": "to match something; to choose an option", "ex1": "This tie goes with your shirt.", "ja1": "このネクタイはあなたのシャツに合う。", "ex2": "Let's go with the second proposal.", "ja2": "2つ目の案でいきましょう。", "note": "", "nuance": "選択の意味と、調和・適合の意味の両方がある。", "groups": ["match_suit"], "etymology": "go（行く）＋with（一緒に）\n→ 対象と一緒に行動するイメージ\n→ そこから「〜に合う／〜を選ぶ」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#2E6B4F\"/><g transform=\"rotate(-9,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 2 L8 14 M2 8 L14 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 91, "stage": 2, "verb": "stay together", "meaning": "一緒にいる、離れずにいる", "def": "to remain with each other", "ex1": "Let's stay together so we don't get lost.", "ja1": "はぐれないように一緒にいよう。", "ex2": "The team stayed together even after the reorganization.", "ja2": "組織再編の後もチームは離れずにいた。", "note": "", "nuance": "離れずに一緒にいる、結束を保つニュアンス。", "groups": ["relationship_harmony"], "etymology": "stay（とどまる）＋together（一つに）\n→ バラバラだった物が一つにまとまるイメージ\n→ そこから「一緒にいる、離れずにいる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-5,32,32)\"><path d=\"M22 20 L22 44 L42 44 L42 30 M22 32 L42 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M22 44 L20 50 M42 44 L44 50\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 2 L8 8 L0 14 M16 2 L8 8 L16 14\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 92, "stage": 2, "verb": "get around", "meaning": "（あちこち）移動する／（噂が）広まる", "def": "to travel from place to place; to spread among people", "ex1": "It's easy to get around Tokyo by train.", "ja1": "東京は電車で移動しやすい。", "ex2": "News of the merger got around quickly.", "ja2": "合併の話はすぐに広まった。", "note": "Stage 3 に別語義あり", "nuance": "移動の自由度を表す意味と、噂が広まる意味がある。", "groups": [], "etymology": "get（得る・～になる）＋around（周りに）\n→ あちこち・ぐるりと回るイメージ\n→ そこから「（あちこち）移動する／（噂が）広まる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(1,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 2 A6 6 0 1 1 2 8\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2.2\"/><path d=\"M2 8 L0 4 M2 8 L6 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 93, "stage": 2, "verb": "get to*2", "meaning": "〜する機会を得る", "def": "to have the opportunity to do something", "ex1": "I got to meet my favorite author.", "ja1": "好きな作家に会う機会を得た。", "ex2": "I got to present at the annual conference.", "ja2": "年次カンファレンスで発表する機会をもらった。", "note": "Stage 1 の get to（到着する）と区別", "nuance": "get to（Stage1、到着）とは別に、機会を得るという意味。", "groups": ["get_to_senses"], "etymology": "get（得る・～になる）＋to（～へ）\n→ 目的地・相手に向かうイメージ\n→ そこから「〜する機会を得る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-1,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L12 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><circle cx=\"14\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/></g></svg>"}, {"no": 94, "stage": 2, "verb": "listen up", "meaning": "注目して聞く", "def": "to pay attention to what is about to be said", "ex1": "Listen up, everyone!", "ja1": "みんな、聞いて。", "ex2": "Listen up, I'll explain the new safety rules.", "ja2": "聞いてください、新しい安全ルールを説明します。", "note": "通常は命令形で使う", "nuance": "注目して聞くよう促す、命令形で使われることが多い。", "groups": ["imperative_expr"], "etymology": "listen（聞く）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「注目して聞く」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"rotate(-14,32,32)\"><path d=\"M32 16 Q22 16 22 28 L22 38 L18 44 L46 44 L42 38 L42 28 Q42 16 32 16 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M28 44 Q28 48 32 48 Q36 48 36 44\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 95, "stage": 2, "verb": "stand up*2", "meaning": "（約束を）すっぽかす", "def": "to fail to meet someone as arranged", "ex1": "He stood me up on Saturday.", "ja1": "彼は土曜に私をすっぽかした。", "ex2": "The supplier stood us up for the second meeting.", "ja2": "その業者は2回目の打ち合わせをすっぽかした。", "note": "目的語は人（stand someone up）", "nuance": "約束をすっぽかす、相手に対して失礼な行為を表す。", "groups": [], "etymology": "stand（立つ）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「（約束を）すっぽかす」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"rotate(-15,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 96, "stage": 2, "verb": "see off", "meaning": "見送る", "def": "to go with someone to their point of departure to say goodbye", "ex1": "I saw my friend off at the airport.", "ja1": "空港で友人を見送った。", "ex2": "We saw the visitors off at the entrance.", "ja2": "来客を入口で見送った。", "note": "", "nuance": "空港や駅で見送る、別れの場面での表現。", "groups": [], "etymology": "see（見る）＋off（離れて）\n→ くっついていた物が離れる・停止や出発のイメージ\n→ そこから「見送る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#1B2A41\"/><g transform=\"rotate(14,32,32)\"><path d=\"M14 32 Q32 16 50 32 Q32 48 14 32 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"32\" cy=\"32\" r=\"7\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 97, "stage": 2, "verb": "meet up", "meaning": "待ち合わせて会う", "def": "to meet someone at an arranged time and place", "ex1": "Let's meet up at seven in front of the station.", "ja1": "7時に駅前で待ち合わせよう。", "ex2": "Let's meet up before the client meeting to align.", "ja2": "顧客との会議前にすり合わせのため会いましょう。", "note": "", "nuance": "事前に約束して落ち合う、待ち合わせのニュアンス。", "groups": ["gather"], "etymology": "meet（会う）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「待ち合わせて会う」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#2E6B4F\"/><g transform=\"rotate(10,32,32)\"><circle cx=\"24\" cy=\"32\" r=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"40\" cy=\"32\" r=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 98, "stage": 2, "verb": "look back on", "meaning": "振り返る", "def": "to think about something that happened in the past", "ex1": "I look back on my school days with a smile.", "ja1": "学生時代を笑顔で振り返る。", "ex2": "Looking back on the project, we learned a lot.", "ja2": "プロジェクトを振り返ると、多くを学んだ。", "note": "", "nuance": "過去を懐かしく振り返る、内省的な表現。", "groups": ["reflect_step_back"], "etymology": "look（見る）＋on（接触・継続）\n→ くっついたまま続く・作動し続けるイメージ\n→ そこから「振り返る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(2,32,32)\"><path d=\"M14 32 Q32 16 50 32 Q32 48 14 32 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"32\" cy=\"32\" r=\"7\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 99, "stage": 2, "verb": "give out*2", "meaning": "尽きる、（機械が）壊れる", "def": "to run out; to stop working properly", "ex1": "My phone battery gave out.", "ja1": "スマホの電池が切れた。", "ex2": "The old server finally gave out last week.", "ja2": "古いサーバーが先週ついに動かなくなった。", "note": "Stage 2 の give out（配る）と区別", "nuance": "尽きる・壊れるという、物や体力の限界を表す。", "groups": ["break_malfunction"], "etymology": "give（与える）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「尽きる、（機械が）壊れる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"rotate(-6,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 100, "stage": 2, "verb": "pay for", "meaning": "〜の代金を払う、負担する", "def": "to pay the cost of something", "ex1": "I'll pay for the coffee.", "ja1": "コーヒー代は私が払います。", "ex2": "The company pays for the training courses.", "ja2": "会社が研修費用を負担する。", "note": "", "nuance": "代金を負担する、支払いの基本表現。", "groups": ["pay_related"], "etymology": "pay（払う）＋for（求めて）\n→ 目的物を求めて手を伸ばすイメージ\n→ そこから「〜の代金を払う、負担する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(3,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"14\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M28 26 L36 26 M28 32 L36 32 M28 38 L36 38\" stroke=\"#C79A3D\" stroke-width=\"2\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/><path d=\"M0 8 L11 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 101, "stage": 2, "verb": "put up*2", "meaning": "（人を）泊める", "def": "to let someone stay at your home or arrange lodging", "ex1": "We can put you up for the night.", "ja1": "一晩泊めてあげられますよ。", "ex2": "The company put us up in a hotel near the site.", "ja2": "会社は現場近くのホテルに宿泊を手配してくれた。", "note": "Stage 1 の put up と区別", "nuance": "看板の設置（Stage1）とは別に、人を泊める意味。", "groups": ["put_up_senses"], "etymology": "put（置く）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「（人を）泊める」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#1B2A41\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-8,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 102, "stage": 2, "verb": "hang out", "meaning": "ぶらぶら過ごす、一緒に時間を過ごす", "def": "to spend time relaxing, especially with other people", "ex1": "We hung out at the park all afternoon.", "ja1": "午後はずっと公園で過ごした。", "ex2": "The team hung out together after the release party.", "ja2": "リリースの打ち上げの後、チームで一緒に過ごした。", "note": "", "nuance": "リラックスして時間を過ごす、カジュアルな社交表現。", "groups": ["socialize_catch_up"], "etymology": "hang（掛ける）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「ぶらぶら過ごす、一緒に時間を過ごす」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#9A5B2E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-11,32,32)\"><circle cx=\"24\" cy=\"32\" r=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"40\" cy=\"32\" r=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 102, "stage": 3, "verb": "throw out", "meaning": "捨てる／（案を）却下する", "def": "to discard something; to reject an idea or proposal", "ex1": "Throw out the empty boxes.", "ja1": "空き箱を捨てて。", "ex2": "The committee threw out our first proposal.", "ja2": "委員会は我々の最初の提案を却下した。", "note": "", "nuance": "不要と判断して処分する、断固とした廃棄・却下のニュアンス。", "groups": ["discard"], "etymology": "throw（投げる）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「捨てる／（案を）却下する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(1,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 103, "stage": 3, "verb": "come around", "meaning": "立ち寄る／考えを変えて同意する", "def": "to visit someone; to change your opinion and agree", "ex1": "Come around for a coffee sometime.", "ja1": "いつかコーヒーでも飲みに寄ってください。", "ex2": "He finally came around to our way of thinking.", "ja2": "彼はついに我々の考え方に同意した。", "note": "Stage 4 / 5 に別語義あり", "nuance": "立ち寄る意味と、意識を取り戻す意味（Stage4）がある。", "groups": ["come_around_senses"], "etymology": "come（来る）＋around（周りに）\n→ あちこち・ぐるりと回るイメージ\n→ そこから「立ち寄る／考えを変えて同意する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-9,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 2 A6 6 0 1 1 2 8\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2.2\"/><path d=\"M2 8 L0 4 M2 8 L6 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 104, "stage": 3, "verb": "take in", "meaning": "理解する、頭に入れる", "def": "to understand and absorb information", "ex1": "There was too much to take in at once.", "ja1": "一度に理解するには情報が多すぎた。", "ex2": "It took a while to take in all the requirements.", "ja2": "要件をすべて把握するのに時間がかかった。", "note": "Stage 4 に別語義あり", "nuance": "情報を吸収し理解する意味と、だまされる意味（Stage4）がある。", "groups": ["understand"], "etymology": "take（取る）＋in（中へ）\n→ 外から中に入る・参加や到着のイメージ\n→ そこから「理解する、頭に入れる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-10,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 105, "stage": 3, "verb": "try out", "meaning": "試してみる", "def": "to test something to see if it works or if you like it", "ex1": "Let's try out the new recipe.", "ja1": "新しいレシピを試してみよう。", "ex2": "We tried out the tool in a small pilot project.", "ja2": "小規模なパイロットでそのツールを試した。", "note": "", "nuance": "試験的に使ってみる、お試しのニュアンス。", "groups": [], "etymology": "try（試す）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「試してみる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#2E6B4F\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-6,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"14\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"32\" cy=\"32\" r=\"7\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"32\" cy=\"32\" r=\"2\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 106, "stage": 3, "verb": "turn into", "meaning": "〜に変わる、〜に発展する", "def": "to change or develop into something else", "ex1": "The rain turned into snow.", "ja1": "雨が雪に変わった。", "ex2": "A small bug turned into a major incident.", "ja2": "小さな不具合が重大障害に発展した。", "note": "", "nuance": "状態や性質が変化する、変身・変質を表す。", "groups": [], "etymology": "turn（向きを変える）＋into（中へ変化）\n→ ある状態の中に入り込む・変化を伴うイメージ\n→ そこから「〜に変わる、〜に発展する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#2E6B4F\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(10,32,32)\"><path d=\"M32 32 m-4,0 a4,4 0 1,0 8,0 a8,8 0 1,0 -16,0 a12,12 0 1,0 24,0 a16,16 0 1,0 -32,0\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 107, "stage": 3, "verb": "watch out", "meaning": "気をつける、注意する", "def": "to be careful about a danger or problem", "ex1": "Watch out! There's a car coming.", "ja1": "気をつけて、車が来ているよ。", "ex2": "Watch out for hidden costs in the contract.", "ja2": "契約書の隠れたコストに注意してください。", "note": "", "nuance": "危険を警告する、注意喚起の定番表現。", "groups": ["be_careful"], "etymology": "watch（見張る）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「気をつける、注意する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#8A4B8A\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(3,32,32)\"><path d=\"M14 32 Q32 16 50 32 Q32 48 14 32 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"32\" cy=\"32\" r=\"7\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 108, "stage": 3, "verb": "get together*2", "meaning": "（物・情報を）まとめる", "def": "to gather things or information into one place", "ex1": "Let me get my things together.", "ja1": "荷物をまとめさせてください。", "ex2": "Could you get the figures together before the meeting?", "ja2": "会議の前に数値をまとめてもらえますか。", "note": "Stage 2 の get together（集まる）と区別", "nuance": "集まる（Stage2）とは別に、物や情報をまとめる意味。", "groups": ["organize"], "etymology": "get（得る・～になる）＋together（一つに）\n→ バラバラだった物が一つにまとまるイメージ\n→ そこから「（物・情報を）まとめる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"rotate(-14,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 2 L8 8 L0 14 M16 2 L8 8 L16 14\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 109, "stage": 3, "verb": "make from", "meaning": "（原料）から作る", "def": "to produce something from a raw material that is changed in the process", "ex1": "Wine is made from grapes.", "ja1": "ワインはぶどうから作られる。", "ex2": "This packaging is made from recycled paper.", "ja2": "この包装材は再生紙から作られている。", "note": "原料が原形をとどめない場合", "nuance": "原料が姿を変えて別物になる場合に使う（ワイン←ぶどう）。", "groups": ["made_of_from"], "etymology": "make（作る）＋from（～から）\n→ ある地点から離れるイメージ\n→ そこから「（原料）から作る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#2E6B4F\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(3,32,32)\"><rect x=\"18\" y=\"34\" width=\"10\" height=\"12\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><rect x=\"28\" y=\"26\" width=\"10\" height=\"20\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><rect x=\"38\" y=\"18\" width=\"10\" height=\"28\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"2\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/><path d=\"M4 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 110, "stage": 3, "verb": "make of", "meaning": "（材料）でできている", "def": "to be composed of a material that is still recognizable", "ex1": "The desk is made of wood.", "ja1": "その机は木でできている。", "ex2": "The casing is made of aluminum.", "ja2": "筐体はアルミでできている。", "note": "材料が見て分かる場合。make from と対比で覚える", "nuance": "材料が見た目にそのまま残る場合に使う（木製の机）。make fromとの対比が重要。", "groups": ["made_of_from"], "etymology": "make（作る）＋of（～の）\n→ 対象を分離・限定するイメージ\n→ そこから「（材料）でできている」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"rotate(-7,32,32)\"><rect x=\"18\" y=\"34\" width=\"10\" height=\"12\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><rect x=\"28\" y=\"26\" width=\"10\" height=\"20\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><rect x=\"38\" y=\"18\" width=\"10\" height=\"28\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M4 4 L12 12 M4 12 L12 4\" stroke=\"#B5392F\" stroke-width=\"1.8\" stroke-linecap=\"round\" opacity=\"0.7\"/></g></svg>"}, {"no": 111, "stage": 3, "verb": "break up", "meaning": "別れる／解散する", "def": "to end a relationship; for a group to separate", "ex1": "They broke up after three years.", "ja1": "彼らは3年付き合って別れた。", "ex2": "The meeting broke up at noon.", "ja2": "会議は正午に散会した。", "note": "Stage 3 の break up*2 と区別", "nuance": "関係が終わる意味と、細かく分ける意味（Stage3の別項目）がある。", "groups": ["break_up_apart"], "etymology": "break（壊す・分ける）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「別れる／解散する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#8A4B8A\"/><g transform=\"rotate(-1,32,32)\"><path d=\"M16 32 L26 32 L30 22 L36 42 L40 32 L48 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linejoin=\"round\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 112, "stage": 3, "verb": "get back", "meaning": "戻る、帰る", "def": "to return to a place", "ex1": "I got back home at ten.", "ja1": "10時に帰宅した。", "ex2": "I'll get back to the office after the site visit.", "ja2": "現地訪問の後オフィスに戻ります。", "note": "Stage 3 に get back*2 あり", "nuance": "戻る動作と、取り戻す意味（Stage3の別項目）の両方。", "groups": ["return"], "etymology": "get（得る・～になる）＋back（後ろ・元へ）\n→ 元の場所や状態に戻るイメージ\n→ そこから「戻る、帰る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"rotate(0,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M14 4 Q4 4 4 12 M4 12 L0 9 M4 12 L8 12\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 113, "stage": 3, "verb": "bring up", "meaning": "（話題を）持ち出す", "def": "to mention a subject in conversation", "ex1": "Don't bring up that subject at dinner.", "ja1": "夕食の席でその話題を出さないで。", "ex2": "She brought up the budget issue in the meeting.", "ja2": "彼女は会議で予算の問題を持ち出した。", "note": "Stage 5 に別語義あり", "nuance": "会話の中で話題を持ち出す、提起のニュアンス。", "groups": ["bring_up_senses"], "etymology": "bring（持ってくる）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「（話題を）持ち出す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#1B2A41\"/><g transform=\"rotate(3,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 114, "stage": 3, "verb": "take out", "meaning": "取り出す、持ち出す", "def": "to remove something from a place or container", "ex1": "Take out the trash, please.", "ja1": "ごみを出してください。", "ex2": "He took out his laptop and started the demo.", "ja2": "彼はノートPCを取り出してデモを始めた。", "note": "Stage 7 に別語義あり", "nuance": "取り出す動作。Stage7に保険契約という比喩的な別義あり。", "groups": ["take_out_senses"], "etymology": "take（取る）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「取り出す、持ち出す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#2E6B4F\"/><g transform=\"rotate(14,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 115, "stage": 3, "verb": "give away", "meaning": "ただであげる／（秘密を）漏らす", "def": "to give something for free; to reveal something secret", "ex1": "They gave away free tickets.", "ja1": "無料チケットを配っていた。", "ex2": "Don't give away the pricing before the negotiation.", "ja2": "交渉の前に価格を漏らさないでください。", "note": "", "nuance": "無料で譲る意味と、秘密を漏らす意味の両方。", "groups": ["reveal_secret"], "etymology": "give（与える）＋away（遠くへ）\n→ その場から遠ざかる・消えていくイメージ\n→ そこから「ただであげる／（秘密を）漏らす」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"rotate(-9,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-dasharray=\"3 2\" stroke-linecap=\"round\"/><path d=\"M11 3 L16 8 L11 13\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 116, "stage": 3, "verb": "look out", "meaning": "注意する、用心する", "def": "to be careful and pay attention to possible danger", "ex1": "Look out for the step.", "ja1": "段差に気をつけて。", "ex2": "Look out for errors in the migrated data.", "ja2": "移行データの誤りに注意してください。", "note": "watch out とほぼ同義", "nuance": "危険に注意せよという警告。watch outとほぼ同義。", "groups": ["be_careful"], "etymology": "look（見る）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「注意する、用心する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#8A4B8A\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(4,32,32)\"><path d=\"M14 32 Q32 16 50 32 Q32 48 14 32 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"32\" cy=\"32\" r=\"7\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 117, "stage": 3, "verb": "keep away", "meaning": "近づかない、遠ざける", "def": "to stay at a distance; to prevent from coming near", "ex1": "Keep away from the edge.", "ja1": "端に近づかないで。", "ex2": "Keep unauthorized staff away from the server room.", "ja2": "権限のない社員をサーバー室に近づけないでください。", "note": "", "nuance": "距離を置く、近づかせないという予防的な表現。", "groups": ["avoid_stay_away"], "etymology": "keep（保つ）＋away（遠くへ）\n→ その場から遠ざかる・消えていくイメージ\n→ そこから「近づかない、遠ざける」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"rotate(7,32,32)\"><rect x=\"16\" y=\"24\" width=\"32\" height=\"24\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M16 24 L32 14 L48 24\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-dasharray=\"3 2\" stroke-linecap=\"round\"/><path d=\"M11 3 L16 8 L11 13\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 118, "stage": 3, "verb": "fill up", "meaning": "いっぱいにする、満席になる", "def": "to make or become completely full", "ex1": "Fill up the bottle with water.", "ja1": "ボトルに水をいっぱい入れて。", "ex2": "The seminar filled up within two days.", "ja2": "セミナーは2日で満席になった。", "note": "", "nuance": "容器を満たす動作、または予定が埋まる比喩表現。", "groups": [], "etymology": "fill（満たす）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「いっぱいにする、満席になる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"rotate(2,32,32)\"><path d=\"M32 14 Q44 30 44 38 Q44 48 32 48 Q20 48 20 38 Q20 30 32 14 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 119, "stage": 3, "verb": "work out*2", "meaning": "計算する、算出する", "def": "to calculate an amount or find a solution", "ex1": "Let me work out how much we owe.", "ja1": "いくら払うのか計算させて。", "ex2": "We worked out the total cost of ownership.", "ja2": "総保有コスト（TCO）を算出した。", "note": "Stage 2 の work out と区別", "nuance": "計算して算出する、work out（運動する）とは異なる意味。", "groups": [], "etymology": "work（働く・作用させる）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「計算する、算出する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"rotate(6,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"10\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M32 14 L32 20 M32 44 L32 50 M14 32 L20 32 M44 32 L50 32 M20 20 L24 24 M40 40 L44 44 M44 20 L40 24 M24 40 L20 44\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 120, "stage": 3, "verb": "run over", "meaning": "（車が）ひく／時間を超過する", "def": "to hit with a vehicle; to exceed a time limit", "ex1": "The car almost ran over a cat.", "ja1": "車が猫をひきそうになった。", "ex2": "The meeting ran over by twenty minutes.", "ja2": "会議は20分超過した。", "note": "", "nuance": "車が人や物をひく事故の意味と、時間超過の意味がある。", "groups": [], "etymology": "run（走る）＋over（越えて）\n→ 何かを越えて広がる・一通り目を通すイメージ\n→ そこから「（車が）ひく／時間を超過する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"rotate(14,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 2 A6 6 0 1 1 2 8\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2.2\"/><path d=\"M2 8 L0 4 M2 8 L6 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 121, "stage": 3, "verb": "tell off", "meaning": "叱る、きつく注意する", "def": "to speak angrily to someone about something they did wrong", "ex1": "My mother told me off for being late.", "ja1": "遅刻して母に叱られた。", "ex2": "The manager told him off for missing the deadline.", "ja2": "上司は納期を守らなかったことで彼を叱った。", "note": "", "nuance": "強く叱責する、感情的な非難を含む表現。", "groups": ["scold_yell"], "etymology": "tell（伝える）＋off（離れて）\n→ くっついていた物が離れる・停止や出発のイメージ\n→ そこから「叱る、きつく注意する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#1B2A41\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-14,32,32)\"><path d=\"M14 20 Q14 16 18 16 L46 16 Q50 16 50 20 L50 36 Q50 40 46 40 L26 40 L18 48 L20 40 L18 40 Q14 40 14 36 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 122, "stage": 3, "verb": "turn up", "meaning": "（音量・温度を）上げる", "def": "to increase the volume, heat, or power of something", "ex1": "Turn up the music.", "ja1": "音楽の音量を上げて。", "ex2": "Could you turn up the microphone volume?", "ja2": "マイクの音量を上げていただけますか。", "note": "元リストの turn up/down を分割。Stage 1 の turn up（現れる）と別語義", "nuance": "音量や温度を上げる動作。Stage1の「現れる」とは別語義。", "groups": ["volume"], "etymology": "turn（向きを変える）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「（音量・温度を）上げる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-15,32,32)\"><path d=\"M32 32 m-4,0 a4,4 0 1,0 8,0 a8,8 0 1,0 -16,0 a12,12 0 1,0 24,0 a16,16 0 1,0 -32,0\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 123, "stage": 3, "verb": "turn down", "meaning": "（音量・温度を）下げる", "def": "to reduce the volume, heat, or power of something", "ex1": "Turn down the TV, please.", "ja1": "テレビの音を下げてください。", "ex2": "Please turn down the volume during the conference call.", "ja2": "電話会議中は音量を下げてください。", "note": "元リストの turn up/down を分割。Stage 5 の turn down（断る）と別語義", "nuance": "音量や温度を下げる動作。Stage5の「断る」とは別語義。", "groups": ["volume"], "etymology": "turn（向きを変える）＋down（下へ）\n→ 下向き・減少や書き留めるイメージ\n→ そこから「（音量・温度を）下げる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-1,32,32)\"><path d=\"M32 32 m-4,0 a4,4 0 1,0 8,0 a8,8 0 1,0 -16,0 a12,12 0 1,0 24,0 a16,16 0 1,0 -32,0\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 16 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 124, "stage": 3, "verb": "help out", "meaning": "手伝う、助ける", "def": "to help someone, especially when they are busy or in trouble", "ex1": "Can you help out with the dishes?", "ja1": "皿洗いを手伝ってくれますか。", "ex2": "He helped out on the project during the busy season.", "ja2": "繁忙期に彼はプロジェクトを手伝ってくれた。", "note": "", "nuance": "忙しい人を助ける、実務的な援助のニュアンス。", "groups": ["help_cover"], "etymology": "help（助ける）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「手伝う、助ける」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"rotate(-7,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 125, "stage": 3, "verb": "go over", "meaning": "見直す、詳しく確認する", "def": "to review or examine something carefully", "ex1": "Let's go over the plan once more.", "ja1": "もう一度計画を見直そう。", "ex2": "Please go over the contract before signing.", "ja2": "署名の前に契約書をよく確認してください。", "note": "", "nuance": "計画や資料を見直す、再確認の行為。", "groups": ["review_check"], "etymology": "go（行く）＋over（越えて）\n→ 何かを越えて広がる・一通り目を通すイメージ\n→ そこから「見直す、詳しく確認する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#1B2A41\"/><g transform=\"rotate(8,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 2 A6 6 0 1 1 2 8\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2.2\"/><path d=\"M2 8 L0 4 M2 8 L6 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 126, "stage": 3, "verb": "look forward to", "meaning": "楽しみにする", "def": "to feel pleased about something that is going to happen", "ex1": "I'm looking forward to the trip.", "ja1": "旅行を楽しみにしている。", "ex2": "I look forward to working with you.", "ja2": "ご一緒できるのを楽しみにしております。", "note": "to は前置詞。後ろは動名詞（-ing）", "nuance": "これから起こることを楽しみに待つ、前向きな期待。", "groups": [], "etymology": "look（見る）＋to（～へ）\n→ 目的地・相手に向かうイメージ\n→ そこから「楽しみにする」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#1B2A41\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-1,32,32)\"><path d=\"M14 32 Q32 16 50 32 Q32 48 14 32 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"32\" cy=\"32\" r=\"7\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L12 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><circle cx=\"14\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/></g></svg>"}, {"no": 127, "stage": 3, "verb": "get back*2", "meaning": "取り戻す、返してもらう", "def": "to receive something again after not having it", "ex1": "I got back the book I lent him.", "ja1": "彼に貸した本を返してもらった。", "ex2": "We got back the deposit after the contract ended.", "ja2": "契約終了後に保証金を返してもらった。", "note": "Stage 3 の get back（戻る）と区別", "nuance": "戻る（Stage3の別項目）とは別に、返してもらう意味。", "groups": ["return"], "etymology": "get（得る・～になる）＋back（後ろ・元へ）\n→ 元の場所や状態に戻るイメージ\n→ そこから「取り戻す、返してもらう」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"rotate(0,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M14 4 Q4 4 4 12 M4 12 L0 9 M4 12 L8 12\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 128, "stage": 3, "verb": "get around*2", "meaning": "（問題・規則を）回避する", "def": "to find a way to deal with or avoid a problem", "ex1": "There's no way to get around the rule.", "ja1": "その規則を回避する方法はない。", "ex2": "We got around the limitation by using a workaround.", "ja2": "回避策を用いてその制約を回避した。", "note": "Stage 2 の get around（移動する）と区別", "nuance": "移動（Stage2）とは別に、規則や制約を回避する意味。", "groups": ["avoid_evade"], "etymology": "get（得る・～になる）＋around（周りに）\n→ あちこち・ぐるりと回るイメージ\n→ そこから「（問題・規則を）回避する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(1,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 2 A6 6 0 1 1 2 8\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2.2\"/><path d=\"M2 8 L0 4 M2 8 L6 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 129, "stage": 3, "verb": "go out with", "meaning": "（人と）付き合う", "def": "to have a romantic relationship with someone", "ex1": "She is going out with my brother.", "ja1": "彼女は私の兄と付き合っている。", "ex2": "Going out with a client can be a conflict of interest.", "ja2": "顧客と交際することは利益相反になりうる。", "note": "", "nuance": "恋愛関係にあることを表す、私的な関係性の表現。", "groups": ["dating_romance"], "etymology": "go（行く）＋with（一緒に）\n→ 対象と一緒に行動するイメージ\n→ そこから「（人と）付き合う」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#9A5B2E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(4,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 2 L8 14 M2 8 L14 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 130, "stage": 3, "verb": "make out of", "meaning": "（材料）を使って作る", "def": "to create something using a particular material", "ex1": "He made a boat out of paper.", "ja1": "彼は紙で船を作った。", "ex2": "We made a prototype out of spare parts.", "ja2": "余った部品で試作品を作った。", "note": "", "nuance": "手元の材料を使って何かを作る、工夫のニュアンス。", "groups": ["made_of_from"], "etymology": "make（作る）＋of（～の）\n→ 対象を分離・限定するイメージ\n→ そこから「（材料）を使って作る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(14,32,32)\"><rect x=\"18\" y=\"34\" width=\"10\" height=\"12\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><rect x=\"28\" y=\"26\" width=\"10\" height=\"20\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><rect x=\"38\" y=\"18\" width=\"10\" height=\"28\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M4 4 L12 12 M4 12 L12 4\" stroke=\"#B5392F\" stroke-width=\"1.8\" stroke-linecap=\"round\" opacity=\"0.7\"/></g></svg>"}, {"no": 131, "stage": 3, "verb": "make into", "meaning": "〜に作り変える", "def": "to change something so that it becomes something else", "ex1": "She made the old shirt into a bag.", "ja1": "彼女は古いシャツをバッグに作り変えた。", "ex2": "We made the report into a slide deck.", "ja2": "報告書をスライド資料に作り変えた。", "note": "", "nuance": "元の物を別の形に作り変える、加工のニュアンス。", "groups": ["made_of_from"], "etymology": "make（作る）＋into（中へ変化）\n→ ある状態の中に入り込む・変化を伴うイメージ\n→ そこから「〜に作り変える」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#9A5B2E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-15,32,32)\"><rect x=\"18\" y=\"34\" width=\"10\" height=\"12\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><rect x=\"28\" y=\"26\" width=\"10\" height=\"20\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><rect x=\"38\" y=\"18\" width=\"10\" height=\"28\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 132, "stage": 3, "verb": "break up*2", "meaning": "細かく分ける、分割する", "def": "to divide something into smaller parts", "ex1": "Break up the chocolate into pieces.", "ja1": "チョコレートを細かく割って。", "ex2": "Let's break up the task into smaller steps.", "ja2": "作業を小さな工程に分割しましょう。", "note": "Stage 3 の break up（別れる）と区別", "nuance": "別れる（Stage3）とは別に、物を細かく分割する意味。", "groups": ["break_into_parts"], "etymology": "break（壊す・分ける）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「細かく分ける、分割する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#8A4B8A\"/><g transform=\"rotate(-1,32,32)\"><path d=\"M16 32 L26 32 L30 22 L36 42 L40 32 L48 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linejoin=\"round\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 133, "stage": 3, "verb": "bring back", "meaning": "持ち帰る、返す／思い出させる", "def": "to return something; to cause someone to remember", "ex1": "Bring back my charger tomorrow.", "ja1": "明日、充電器を返してください。", "ex2": "He brought back several requests from the client.", "ja2": "彼は顧客から要望をいくつか持ち帰った。", "note": "", "nuance": "物を返す・持ち帰る意味と、記憶を呼び起こす意味がある。", "groups": ["return"], "etymology": "bring（持ってくる）＋back（後ろ・元へ）\n→ 元の場所や状態に戻るイメージ\n→ そこから「持ち帰る、返す／思い出させる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(4,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M14 4 Q4 4 4 12 M4 12 L0 9 M4 12 L8 12\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 134, "stage": 3, "verb": "take back", "meaning": "返品する／（発言を）撤回する", "def": "to return an item to a shop; to retract what you said", "ex1": "I took back the shirt because it didn't fit.", "ja1": "サイズが合わなかったのでシャツを返品した。", "ex2": "I take back what I said about the schedule.", "ja2": "スケジュールについて言ったことは撤回します。", "note": "Stage 5 に別語義あり", "nuance": "返品の意味と、発言を撤回する意味の両方で使う。", "groups": ["return_money"], "etymology": "take（取る）＋back（後ろ・元へ）\n→ 元の場所や状態に戻るイメージ\n→ そこから「返品する／（発言を）撤回する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"rotate(-4,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M14 4 Q4 4 4 12 M4 12 L0 9 M4 12 L8 12\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 135, "stage": 3, "verb": "pick up*2", "meaning": "（技能・言語を）自然に身につける", "def": "to learn something without making a deliberate effort", "ex1": "She picked up Spanish while living abroad.", "ja1": "彼女は海外生活の中でスペイン語を身につけた。", "ex2": "He picked up Excel skills on the job.", "ja2": "彼は実務の中でExcelのスキルを身につけた。", "note": "Stage 2 の pick up（拾う・迎えに行く）と区別", "nuance": "拾う（Stage2）とは別に、努力せず自然に技能を習得する意味。", "groups": ["pick_up_senses"], "etymology": "pick（つまむ・選ぶ）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「（技能・言語を）自然に身につける」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-10,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 136, "stage": 3, "verb": "make up", "meaning": "でっちあげる、作り話をする", "def": "to invent a story, excuse, or explanation", "ex1": "He made up an excuse for being late.", "ja1": "彼は遅刻の言い訳をでっちあげた。", "ex2": "Don't make up numbers in the report.", "ja2": "報告書の数字をでっちあげないでください。", "note": "Stage 4 / 5 に別語義あり", "nuance": "話をでっちあげる、事実でないことを作り上げる否定的な表現。", "groups": ["make_up_senses"], "etymology": "make（作る）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「でっちあげる、作り話をする」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(3,32,32)\"><rect x=\"18\" y=\"34\" width=\"10\" height=\"12\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><rect x=\"28\" y=\"26\" width=\"10\" height=\"20\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><rect x=\"38\" y=\"18\" width=\"10\" height=\"28\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 137, "stage": 3, "verb": "come by", "meaning": "立ち寄る／手に入れる", "def": "to visit briefly; to obtain something", "ex1": "Come by my place after work.", "ja1": "仕事の後、うちに寄って。", "ex2": "Good engineers are hard to come by.", "ja2": "優秀な技術者はなかなか得がたい。", "note": "", "nuance": "ふらっと立ち寄る意味と、何かを手に入れる意味がある。", "groups": ["visit_casually"], "etymology": "come（来る）＋by（そばを）\n→ すぐそばを通り過ぎるイメージ\n→ そこから「立ち寄る／手に入れる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#2E6B4F\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-10,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 12 Q8 -2 16 12\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2.2\"/></g></svg>"}, {"no": 138, "stage": 3, "verb": "put out", "meaning": "（火・明かりを）消す", "def": "to make a fire or light stop burning", "ex1": "He put out the candle.", "ja1": "彼はろうそくの火を消した。", "ex2": "The staff put out the fire before it spread.", "ja2": "社員は延焼する前に火を消し止めた。", "note": "Stage 4 に別語義あり", "nuance": "火を消す動作。put out*2（外に出す）と混同注意。", "groups": ["put_out_senses"], "etymology": "put（置く）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「（火・明かりを）消す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(2,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 139, "stage": 3, "verb": "calm down", "meaning": "落ち着く、落ち着かせる", "def": "to become or make someone become less angry or upset", "ex1": "Calm down and tell me what happened.", "ja1": "落ち着いて何があったか話して。", "ex2": "He calmed down after the client accepted the fix.", "ja2": "顧客が修正案を受け入れて彼は落ち着いた。", "note": "", "nuance": "興奮や怒りを鎮める、落ち着かせる表現。", "groups": ["calm_down"], "etymology": "calm（落ち着かせる）＋down（下へ）\n→ 下向き・減少や書き留めるイメージ\n→ そこから「落ち着く、落ち着かせる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#1B2A41\"/><g transform=\"rotate(3,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"16\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"27\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><circle cx=\"37\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><path d=\"M26 38 Q32 42 38 38\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 16 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 140, "stage": 3, "verb": "look after", "meaning": "世話をする、面倒を見る", "def": "to take care of someone or something", "ex1": "Can you look after my dog this weekend?", "ja1": "今週末、犬の世話をお願いできますか。", "ex2": "She looks after three client accounts.", "ja2": "彼女は3社の顧客を担当している。", "note": "", "nuance": "世話をする、面倒を見る責任を伴う表現。", "groups": [], "etymology": "look（見る）＋after（後を追って）\n→ 対象の後ろについていくイメージ\n→ そこから「世話をする、面倒を見る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(4,32,32)\"><path d=\"M14 32 Q32 16 50 32 Q32 48 14 32 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"32\" cy=\"32\" r=\"7\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-dasharray=\"2 2\"/><path d=\"M9 3 L15 8 L9 13\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 141, "stage": 3, "verb": "call up", "meaning": "電話をかける", "def": "to telephone someone", "ex1": "I'll call up my parents tonight.", "ja1": "今夜、両親に電話します。", "ex2": "Call up the vendor and confirm the delivery date.", "ja2": "業者に電話して納期を確認してください。", "note": "", "nuance": "電話をかける、シンプルな連絡手段。", "groups": ["call_phone"], "etymology": "call（呼ぶ）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「電話をかける」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(14,32,32)\"><path d=\"M32 16 Q22 16 22 28 L22 38 L18 44 L46 44 L42 38 L42 28 Q42 16 32 16 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M28 44 Q28 48 32 48 Q36 48 36 44\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 142, "stage": 3, "verb": "turn to", "meaning": "（人・物に）頼る", "def": "to go to someone or something for help or advice", "ex1": "She turned to her friend for advice.", "ja1": "彼女は友人に助言を求めた。", "ex2": "When issues arise, we turn to the support team.", "ja2": "問題が起きたときはサポートチームを頼ります。", "note": "", "nuance": "困ったときに人や物に頼る、助けを求める表現。", "groups": ["rely_on"], "etymology": "turn（向きを変える）＋to（～へ）\n→ 目的地・相手に向かうイメージ\n→ そこから「（人・物に）頼る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#2E6B4F\"/><g transform=\"rotate(-9,32,32)\"><path d=\"M32 32 m-4,0 a4,4 0 1,0 8,0 a8,8 0 1,0 -16,0 a12,12 0 1,0 24,0 a16,16 0 1,0 -32,0\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L12 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><circle cx=\"14\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/></g></svg>"}, {"no": 143, "stage": 3, "verb": "go by", "meaning": "（時が）過ぎる、通り過ぎる", "def": "to pass, especially of time", "ex1": "Two years went by quickly.", "ja1": "2年はあっという間に過ぎた。", "ex2": "Three weeks went by without a reply from the client.", "ja2": "顧客から返信がないまま3週間が過ぎた。", "note": "", "nuance": "時間が経過する、シンプルで自然な時の流れを表す。", "groups": [], "etymology": "go（行く）＋by（そばを）\n→ すぐそばを通り過ぎるイメージ\n→ そこから「（時が）過ぎる、通り過ぎる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-15,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 12 Q8 -2 16 12\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2.2\"/></g></svg>"}, {"no": 144, "stage": 3, "verb": "put down*2", "meaning": "けなす、こきおろす", "def": "to criticize someone and make them feel bad about themselves", "ex1": "Don't put down your classmates.", "ja1": "クラスメートをけなさないで。", "ex2": "Putting down team members lowers morale.", "ja2": "メンバーをけなすと士気が下がる。", "note": "Stage 2 の put down（置く）と区別", "nuance": "置く（Stage2）とは別に、人をけなす否定的な意味。", "groups": ["put_down_senses"], "etymology": "put（置く）＋down（下へ）\n→ 下向き・減少や書き留めるイメージ\n→ そこから「けなす、こきおろす」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-6,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 16 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 145, "stage": 3, "verb": "keep out", "meaning": "立ち入らせない、締め出す", "def": "to prevent someone or something from entering", "ex1": "Keep the cat out of the kitchen.", "ja1": "猫を台所に入れないで。", "ex2": "The sign says \"Keep out\" for the construction area.", "ja2": "工事区域には「立入禁止」と表示されている。", "note": "", "nuance": "立ち入らせない、締め出す禁止の表現。", "groups": ["keep_in_out"], "etymology": "keep（保つ）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「立ち入らせない、締め出す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-6,32,32)\"><rect x=\"16\" y=\"24\" width=\"32\" height=\"24\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M16 24 L32 14 L48 24\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 146, "stage": 3, "verb": "stay up", "meaning": "夜更かしする", "def": "to remain awake later than usual", "ex1": "I stayed up until two watching a movie.", "ja1": "映画を見て2時まで起きていた。", "ex2": "He stayed up to finish the proposal.", "ja2": "彼は提案書を仕上げるため夜更かしした。", "note": "", "nuance": "普段より遅くまで起きている、夜更かしを表す。", "groups": [], "etymology": "stay（とどまる）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「夜更かしする」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#1B2A41\"/><g transform=\"rotate(-8,32,32)\"><path d=\"M22 20 L22 44 L42 44 L42 30 M22 32 L42 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M22 44 L20 50 M42 44 L44 50\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 147, "stage": 3, "verb": "put back", "meaning": "元の場所に戻す", "def": "to return something to where it was", "ex1": "Put back the book when you're done.", "ja1": "読み終わったら本を戻してください。", "ex2": "Please put back the file after copying it.", "ja2": "コピーの後はファイルを元に戻してください。", "note": "", "nuance": "使った物を元の場所へ戻す、片づけの基本動作。", "groups": ["return"], "etymology": "put（置く）＋back（後ろ・元へ）\n→ 元の場所や状態に戻るイメージ\n→ そこから「元の場所に戻す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(12,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M14 4 Q4 4 4 12 M4 12 L0 9 M4 12 L8 12\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 148, "stage": 3, "verb": "put in", "meaning": "設置する／（時間・労力を）注ぐ", "def": "to install something; to devote time or effort", "ex1": "We put in a new air conditioner.", "ja1": "新しいエアコンを設置した。", "ex2": "She put in a lot of hours on this proposal.", "ja2": "彼女はこの提案書に多くの時間を費やした。", "note": "Stage 4 に別語義あり", "nuance": "設置する意味と、時間や労力を注ぐ意味（Stage4に別義）がある。", "groups": ["spend_time_effort"], "etymology": "put（置く）＋in（中へ）\n→ 外から中に入る・参加や到着のイメージ\n→ そこから「設置する／（時間・労力を）注ぐ」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(2,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 149, "stage": 3, "verb": "stand for", "meaning": "〜の略である、〜を表す", "def": "to be an abbreviation of something; to represent", "ex1": "What does \"ASAP\" stand for?", "ja1": "ASAPは何の略ですか。", "ex2": "\"SLA\" stands for service level agreement.", "ja2": "SLAはサービスレベル合意の略です。", "note": "Stage 7 に別語義あり", "nuance": "略語の意味を表す表現。Stage7に「容認する」の別義あり。", "groups": ["stand_for_senses"], "etymology": "stand（立つ）＋for（求めて）\n→ 目的物を求めて手を伸ばすイメージ\n→ そこから「〜の略である、〜を表す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#9A5B2E\"/><g transform=\"rotate(-3,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/><path d=\"M0 8 L11 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 150, "stage": 3, "verb": "pass out", "meaning": "気を失う", "def": "to become unconscious", "ex1": "He passed out from the heat.", "ja1": "彼は暑さで気を失った。", "ex2": "One participant passed out during the long session.", "ja2": "長時間のセッション中に参加者が1名倒れた。", "note": "Stage 7 の pass out*2（配る）と区別", "nuance": "気を失う意味。pass out*2（配る、Stage7）と混同注意。", "groups": [], "etymology": "pass（通す・渡す）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「気を失う」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#9A5B2E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-2,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 151, "stage": 3, "verb": "check out*2", "meaning": "調べる、確認してみる", "def": "to examine or investigate something", "ex1": "Check out this new café.", "ja1": "この新しいカフェをのぞいてみて。", "ex2": "Let me check out the error log first.", "ja2": "まずエラーログを確認させてください。", "note": "Stage 2 の check out（チェックアウト）と区別", "nuance": "チェックアウト（Stage2）とは別に、確認・調査する意味。", "groups": ["review_check"], "etymology": "check（確認する）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「調べる、確認してみる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#1B2A41\"/><g transform=\"rotate(1,32,32)\"><path d=\"M32 20 Q24 14 16 18 L16 44 Q24 40 32 46 Q40 40 48 44 L48 18 Q40 14 32 20 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 152, "stage": 3, "verb": "break into", "meaning": "押し入る、侵入する", "def": "to enter a place by force, usually to steal", "ex1": "Someone broke into our house.", "ja1": "誰かが家に押し入った。", "ex2": "Hackers broke into the company network.", "ja2": "ハッカーが社内ネットワークに侵入した。", "note": "", "nuance": "力ずくで侵入する、犯罪性を伴う強い表現。", "groups": ["enter_various"], "etymology": "break（壊す・分ける）＋into（中へ変化）\n→ ある状態の中に入り込む・変化を伴うイメージ\n→ そこから「押し入る、侵入する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#9A5B2E\"/><g transform=\"rotate(14,32,32)\"><path d=\"M16 32 L26 32 L30 22 L36 42 L40 32 L48 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linejoin=\"round\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 153, "stage": 4, "verb": "open up", "meaning": "開ける、開店・開設する", "def": "to open something; to start a shop or business", "ex1": "The shop opens up at nine.", "ja1": "その店は9時に開く。", "ex2": "We're opening up a new office in Osaka.", "ja2": "大阪に新しいオフィスを開設します。", "note": "", "nuance": "店や事業を開始する、新規オープンの明るいニュアンス。", "groups": ["open_up_senses"], "etymology": "open（開く）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「開ける、開店・開設する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(4,32,32)\"><rect x=\"20\" y=\"14\" width=\"24\" height=\"38\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"38\" cy=\"34\" r=\"2\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 154, "stage": 4, "verb": "come around*2", "meaning": "意識を取り戻す", "def": "to become conscious again", "ex1": "He came around a few minutes after fainting.", "ja1": "彼は気を失って数分後に意識を取り戻した。", "ex2": "The employee came around before the ambulance arrived.", "ja2": "救急車が到着する前に社員は意識を取り戻した。", "note": "Stage 3 / 5 に別語義あり", "nuance": "立ち寄る（Stage3）とは別に、意識を取り戻す医療的な文脈。", "groups": ["come_around_senses"], "etymology": "come（来る）＋around（周りに）\n→ あちこち・ぐるりと回るイメージ\n→ そこから「意識を取り戻す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-9,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 2 A6 6 0 1 1 2 8\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2.2\"/><path d=\"M2 8 L0 4 M2 8 L6 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 155, "stage": 4, "verb": "make up*2", "meaning": "仲直りする", "def": "to become friendly again after an argument", "ex1": "They argued but made up quickly.", "ja1": "二人はけんかしたがすぐ仲直りした。", "ex2": "The two teams made up after the heated discussion.", "ja2": "激しい議論の後、両チームは和解した。", "note": "Stage 3 の make up（でっちあげる）と区別", "nuance": "でっちあげる（Stage3）とは別に、仲直りするという意味。", "groups": ["make_up_senses"], "etymology": "make（作る）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「仲直りする」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(3,32,32)\"><rect x=\"18\" y=\"34\" width=\"10\" height=\"12\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><rect x=\"28\" y=\"26\" width=\"10\" height=\"20\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><rect x=\"38\" y=\"18\" width=\"10\" height=\"28\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 156, "stage": 4, "verb": "open up*2", "meaning": "心を開いて話す", "def": "to talk freely about your feelings", "ex1": "She finally opened up about her worries.", "ja1": "彼女はようやく悩みを打ち明けた。", "ex2": "The junior members opened up in the one-on-one.", "ja2": "1on1で若手メンバーが本音を話してくれた。", "note": "", "nuance": "開ける（Stage4）とは別に、心を開いて本音を話す比喩。", "groups": ["open_up_senses"], "etymology": "open（開く）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「心を開いて話す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(4,32,32)\"><rect x=\"20\" y=\"14\" width=\"24\" height=\"38\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"38\" cy=\"34\" r=\"2\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 157, "stage": 4, "verb": "hang on", "meaning": "少し待つ、持ちこたえる", "def": "to wait for a short time; to hold firmly", "ex1": "Hang on a second, I'm coming.", "ja1": "ちょっと待って、今行くよ。", "ex2": "Hang on while I check the system status.", "ja2": "システムの状態を確認しますので少々お待ちください。", "note": "", "nuance": "少し待ってという指示。hold onよりカジュアルな響き。", "groups": ["wait"], "etymology": "hang（掛ける）＋on（接触・継続）\n→ くっついたまま続く・作動し続けるイメージ\n→ そこから「少し待つ、持ちこたえる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"rotate(1,32,32)\"><circle cx=\"24\" cy=\"32\" r=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"40\" cy=\"32\" r=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 158, "stage": 4, "verb": "pick on", "meaning": "いじめる、目の敵にする", "def": "to treat someone unfairly or criticize them repeatedly", "ex1": "Stop picking on your little brother.", "ja1": "弟をいじめるのはやめなさい。", "ex2": "Don't pick on one member when the whole team missed the target.", "ja2": "チーム全体が未達なのに一人だけを責めないでください。", "note": "", "nuance": "特定の人を標的にして責める、いじめのニュアンス。", "groups": ["bully_mistreat"], "etymology": "pick（つまむ・選ぶ）＋on（接触・継続）\n→ くっついたまま続く・作動し続けるイメージ\n→ そこから「いじめる、目の敵にする」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#1B2A41\"/><g transform=\"rotate(-4,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 159, "stage": 4, "verb": "stay away", "meaning": "近寄らない", "def": "to avoid going near someone or something", "ex1": "Stay away from the broken glass.", "ja1": "割れたガラスに近寄らないで。", "ex2": "Stay away from the production server without approval.", "ja2": "承認なしに本番サーバーに触れないでください。", "note": "", "nuance": "距離を置いて近づかない、忠告的な表現。", "groups": ["avoid_stay_away"], "etymology": "stay（とどまる）＋away（遠くへ）\n→ その場から遠ざかる・消えていくイメージ\n→ そこから「近寄らない」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(10,32,32)\"><path d=\"M22 20 L22 44 L42 44 L42 30 M22 32 L42 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M22 44 L20 50 M42 44 L44 50\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-dasharray=\"3 2\" stroke-linecap=\"round\"/><path d=\"M11 3 L16 8 L11 13\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 160, "stage": 4, "verb": "keep in", "meaning": "中にとどめておく、外に出さない", "def": "to keep something or someone inside", "ex1": "Keep the cat in tonight.", "ja1": "今夜は猫を家の中に入れておいて。", "ex2": "Please keep this information in the team for now.", "ja2": "この情報は当面チーム内にとどめてください。", "note": "", "nuance": "屋内にとどめる、外に出さないようにする管理的な表現。", "groups": ["keep_in_out"], "etymology": "keep（保つ）＋in（中へ）\n→ 外から中に入る・参加や到着のイメージ\n→ そこから「中にとどめておく、外に出さない」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"rotate(7,32,32)\"><rect x=\"16\" y=\"24\" width=\"32\" height=\"24\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M16 24 L32 14 L48 24\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 161, "stage": 4, "verb": "take in*2", "meaning": "だます、欺く", "def": "to deceive someone, usually in the passive form", "ex1": "Don't be taken in by cheap offers.", "ja1": "安い勧誘にだまされないで。", "ex2": "Several clients were taken in by the fake invoice.", "ja2": "何社かの顧客が偽の請求書にだまされた。", "note": "be taken in by の形が多い。Stage 3 の take in と区別", "nuance": "理解する（Stage3）とは別に、だまされるという受動的な意味。", "groups": ["deceive"], "etymology": "take（取る）＋in（中へ）\n→ 外から中に入る・参加や到着のイメージ\n→ そこから「だます、欺く」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-10,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 162, "stage": 4, "verb": "call off", "meaning": "中止する", "def": "to cancel an event or plan", "ex1": "They called off the picnic because of rain.", "ja1": "雨のためピクニックは中止になった。", "ex2": "The client called off the meeting at short notice.", "ja2": "顧客は直前に会議を中止した。", "note": "", "nuance": "予定を中止する、キャンセルの明確な表現。", "groups": ["cancel_stop"], "etymology": "call（呼ぶ）＋off（離れて）\n→ くっついていた物が離れる・停止や出発のイメージ\n→ そこから「中止する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#1B2A41\"/><g transform=\"rotate(11,32,32)\"><path d=\"M32 16 Q22 16 22 28 L22 38 L18 44 L46 44 L42 38 L42 28 Q42 16 32 16 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M28 44 Q28 48 32 48 Q36 48 36 44\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 163, "stage": 4, "verb": "turn around", "meaning": "向きを変える／（業績を）好転させる", "def": "to face the other way; to improve a bad situation", "ex1": "Turn around and look at me.", "ja1": "こっちを向いて。", "ex2": "The new manager turned the business around in a year.", "ja2": "新しい責任者は1年で事業を立て直した。", "note": "", "nuance": "向きを変える動作と、状況を好転させる比喩の両方。", "groups": ["turn_direction"], "etymology": "turn（向きを変える）＋around（周りに）\n→ あちこち・ぐるりと回るイメージ\n→ そこから「向きを変える／（業績を）好転させる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(10,32,32)\"><path d=\"M32 32 m-4,0 a4,4 0 1,0 8,0 a8,8 0 1,0 -16,0 a12,12 0 1,0 24,0 a16,16 0 1,0 -32,0\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 2 A6 6 0 1 1 2 8\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2.2\"/><path d=\"M2 8 L0 4 M2 8 L6 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 164, "stage": 4, "verb": "get by", "meaning": "何とかやっていく", "def": "to manage to live or continue with what you have", "ex1": "We can get by on one salary.", "ja1": "収入ひとつでも何とかやっていける。", "ex2": "We got by with two engineers until the new hire joined.", "ja2": "新人が入るまでエンジニア2名で何とか回した。", "note": "", "nuance": "限られた資源で何とかやっていく、切り詰めたニュアンス。", "groups": [], "etymology": "get（得る・～になる）＋by（そばを）\n→ すぐそばを通り過ぎるイメージ\n→ そこから「何とかやっていく」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(13,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 12 Q8 -2 16 12\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2.2\"/></g></svg>"}, {"no": 165, "stage": 4, "verb": "bring in", "meaning": "導入する、（人・収益を）呼び込む", "def": "to introduce something new; to attract people or money", "ex1": "They brought in a new rule at school.", "ja1": "学校で新しい規則が導入された。", "ex2": "We brought in an external consultant.", "ja2": "外部コンサルタントを起用した。", "note": "", "nuance": "新しい人や物を導入する、外部からの呼び込み。", "groups": ["bring_in_out"], "etymology": "bring（持ってくる）＋in（中へ）\n→ 外から中に入る・参加や到着のイメージ\n→ そこから「導入する、（人・収益を）呼び込む」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"rotate(-1,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 166, "stage": 4, "verb": "put out*2", "meaning": "外に出す", "def": "to place something outside", "ex1": "Put out the garbage before eight.", "ja1": "8時までにごみを出して。", "ex2": "Please put out the signage before the seminar starts.", "ja2": "セミナー開始前に案内看板を外に出してください。", "note": "Stage 3 の put out（火を消す）と区別", "nuance": "火を消す（Stage3）とは別に、物を外に出す動作。", "groups": ["put_out_senses"], "etymology": "put（置く）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「外に出す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(2,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 167, "stage": 4, "verb": "put down*3", "meaning": "書き留める、記入する", "def": "to write something down", "ex1": "Put down your name on the list.", "ja1": "リストに名前を記入して。", "ex2": "Put down the action items as we go.", "ja2": "進めながらアクション項目を書き留めてください。", "note": "Stage 2 / 3 に別語義あり。take down とほぼ同義", "nuance": "書き留める動作。put down（置く）・けなす、とは別の第三の意味。", "groups": ["write_down"], "etymology": "put（置く）＋down（下へ）\n→ 下向き・減少や書き留めるイメージ\n→ そこから「書き留める、記入する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-6,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 16 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 168, "stage": 4, "verb": "fall down", "meaning": "転ぶ、倒れる", "def": "to fall to the ground", "ex1": "The child fell down in the playground.", "ja1": "子どもが遊び場で転んだ。", "ex2": "The whiteboard fell down during the workshop.", "ja2": "ワークショップ中にホワイトボードが倒れた。", "note": "", "nuance": "転ぶ・倒れる、不注意や事故によるニュアンス。", "groups": ["fall_down"], "etymology": "fall（落ちる）＋down（下へ）\n→ 下向き・減少や書き留めるイメージ\n→ そこから「転ぶ、倒れる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(9,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 16 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 169, "stage": 4, "verb": "point out", "meaning": "指摘する", "def": "to draw attention to a fact or a mistake", "ex1": "She pointed out my mistake.", "ja1": "彼女は私の間違いを指摘した。", "ex2": "The reviewer pointed out three issues in the design.", "ja2": "レビュー担当者は設計上の課題を3点指摘した。", "note": "", "nuance": "誤りや事実を明確に指摘する、指導的な表現。", "groups": [], "etymology": "point（指し示す）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「指摘する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#1B2A41\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-9,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"14\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"32\" cy=\"32\" r=\"7\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"32\" cy=\"32\" r=\"2\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 170, "stage": 4, "verb": "get out", "meaning": "出る、抜け出す", "def": "to leave a place or a situation", "ex1": "Get out of the car carefully.", "ja1": "気をつけて車から降りて。", "ex2": "We need to get out of this contract.", "ja2": "この契約から抜ける必要がある。", "note": "", "nuance": "困難な場所や状況から抜け出す、脱出のニュアンス。", "groups": ["exit_leave_briefly"], "etymology": "get（得る・～になる）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「出る、抜け出す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-15,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 171, "stage": 4, "verb": "hold off", "meaning": "見合わせる、先延ばしにする", "def": "to delay doing something", "ex1": "Let's hold off on buying a new car.", "ja1": "車の買い替えは見合わせよう。", "ex2": "Let's hold off on the announcement until legal approves.", "ja2": "法務の承認が出るまで発表を見合わせましょう。", "note": "Stage 7 に別語義あり", "nuance": "予定を一時的に見合わせる、判断を保留する表現。", "groups": ["postpone"], "etymology": "hold（持つ・保つ）＋off（離れて）\n→ くっついていた物が離れる・停止や出発のイメージ\n→ そこから「見合わせる、先延ばしにする」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-1,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 172, "stage": 4, "verb": "give in", "meaning": "屈する、折れる", "def": "to finally agree to something after resisting", "ex1": "He gave in and let the kids stay up.", "ja1": "彼は折れて子どもたちの夜更かしを許した。", "ex2": "We gave in to the client's request for a discount.", "ja2": "値引きの要望に折れた。", "note": "", "nuance": "抵抗をやめて相手に従う、屈服のニュアンス。", "groups": ["give_up_in"], "etymology": "give（与える）＋in（中へ）\n→ 外から中に入る・参加や到着のイメージ\n→ そこから「屈する、折れる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"rotate(-7,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 173, "stage": 4, "verb": "drop in", "meaning": "ふらっと立ち寄る", "def": "to visit someone without arranging it in advance", "ex1": "She dropped in on her way home.", "ja1": "彼女は帰り道にふらっと立ち寄った。", "ex2": "Feel free to drop in on the weekly stand-up.", "ja2": "週次の朝会には気軽に参加してください。", "note": "", "nuance": "予定せず立ち寄る、drop byと似るがより軽い響き。", "groups": ["visit_casually"], "etymology": "drop（ポトリと落ちる）＋in（中へ）\n→ 外から中に入る・参加や到着のイメージ\n→ そこから「ふらっと立ち寄る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"rotate(0,32,32)\"><path d=\"M32 14 Q44 30 44 38 Q44 48 32 48 Q20 48 20 38 Q20 30 32 14 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 174, "stage": 4, "verb": "put in*2", "meaning": "（申請などを）出す、申し込む", "def": "to formally submit a request or application", "ex1": "I put in a request for a new passport.", "ja1": "パスポートの申請を出した。", "ex2": "She put in for three days of leave.", "ja2": "彼女は3日間の休暇を申請した。", "note": "put in for の形が多い。Stage 3 の put in と区別", "nuance": "設置（Stage3）とは別に、正式に申請を提出する意味。", "groups": ["submit"], "etymology": "put（置く）＋in（中へ）\n→ 外から中に入る・参加や到着のイメージ\n→ そこから「（申請などを）出す、申し込む」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(2,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 175, "stage": 4, "verb": "push over", "meaning": "押し倒す", "def": "to push someone or something so that it falls", "ex1": "He accidentally pushed over the vase.", "ja1": "彼はうっかり花瓶を倒した。", "ex2": "Someone pushed over the stack of boxes in the warehouse.", "ja2": "倉庫で誰かが積み上げた箱を倒した。", "note": "", "nuance": "力を加えて物や人を押し倒す、物理的な動作。", "groups": [], "etymology": "push（押す）＋over（越えて）\n→ 何かを越えて広がる・一通り目を通すイメージ\n→ そこから「押し倒す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#1B2A41\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(8,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 2 A6 6 0 1 1 2 8\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2.2\"/><path d=\"M2 8 L0 4 M2 8 L6 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 176, "stage": 4, "verb": "figure out", "meaning": "理解する、解明する", "def": "to understand or solve something after thinking", "ex1": "I can't figure out this puzzle.", "ja1": "このパズルが解けない。", "ex2": "We figured out the cause of the outage.", "ja2": "障害の原因を突き止めた。", "note": "", "nuance": "考えを巡らせて答えにたどり着く、思考のプロセス。", "groups": ["understand"], "etymology": "figure（思い描く・計算する）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「理解する、解明する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"rotate(-7,32,32)\"><circle cx=\"32\" cy=\"26\" r=\"12\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M26 38 L38 38 M28 44 L36 44\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 177, "stage": 4, "verb": "cheer up", "meaning": "元気づける、元気を出す", "def": "to become happier, or to make someone happier", "ex1": "Cheer up, it's not that bad.", "ja1": "元気出して、そんなに悪くないよ。", "ex2": "The good sales results cheered up the whole team.", "ja2": "好調な売上がチーム全体を元気づけた。", "note": "", "nuance": "落ち込んだ気持ちを元気づける、励ましの表現。", "groups": ["cheer_encourage"], "etymology": "cheer（励ます）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「元気づける、元気を出す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(4,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"16\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"27\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><circle cx=\"37\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><path d=\"M26 38 Q32 42 38 38\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 178, "stage": 4, "verb": "bring along", "meaning": "一緒に連れて行く、持って行く", "def": "to take someone or something with you", "ex1": "Bring along your umbrella.", "ja1": "傘を持ってきて。", "ex2": "Please bring along a copy of the requirements.", "ja2": "要件書のコピーを持参してください。", "note": "", "nuance": "人や物を一緒に連れて行く、同行を促す表現。", "groups": ["come_along_together"], "etymology": "bring（持ってくる）＋along（沿って）\n→ 一緒に・並んで進むイメージ\n→ そこから「一緒に連れて行く、持って行く」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#2E6B4F\"/><g transform=\"rotate(13,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 5 L16 5 M0 11 L16 11\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 179, "stage": 4, "verb": "drop out", "meaning": "中退する、脱落する", "def": "to stop attending or participating before the end", "ex1": "He dropped out of college.", "ja1": "彼は大学を中退した。", "ex2": "Two vendors dropped out of the bidding.", "ja2": "2社が入札から降りた。", "note": "", "nuance": "学業や活動を途中でやめる、離脱のニュアンス。", "groups": [], "etymology": "drop（ポトリと落ちる）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「中退する、脱落する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#9A5B2E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-12,32,32)\"><path d=\"M32 14 Q44 30 44 38 Q44 48 32 48 Q20 48 20 38 Q20 30 32 14 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 180, "stage": 4, "verb": "take down", "meaning": "書き留める、記録する", "def": "to write down what someone says", "ex1": "Take down my number.", "ja1": "私の番号を控えて。", "ex2": "She took down the minutes of the meeting.", "ja2": "彼女は会議の議事を書き留めた。", "note": "", "nuance": "書き留める（Stage4の別動詞take down）、記録する行為。", "groups": ["write_down"], "etymology": "take（取る）＋down（下へ）\n→ 下向き・減少や書き留めるイメージ\n→ そこから「書き留める、記録する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"rotate(4,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 16 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 181, "stage": 4, "verb": "pay back", "meaning": "返済する、返す", "def": "to return money that you borrowed", "ex1": "I'll pay you back next week.", "ja1": "来週お返しします。", "ex2": "The investment will pay back within three years.", "ja2": "その投資は3年で回収できる。", "note": "", "nuance": "借りたお金を返済する、金銭的な義務の履行。", "groups": ["return_money"], "etymology": "pay（払う）＋back（後ろ・元へ）\n→ 元の場所や状態に戻るイメージ\n→ そこから「返済する、返す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-1,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"14\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M28 26 L36 26 M28 32 L36 32 M28 38 L36 38\" stroke=\"#C79A3D\" stroke-width=\"2\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M14 4 Q4 4 4 12 M4 12 L0 9 M4 12 L8 12\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 182, "stage": 4, "verb": "make out*2", "meaning": "（かろうじて）見分ける、判読する", "def": "to manage to see, hear, or read something with difficulty", "ex1": "I could barely make out the sign in the dark.", "ja1": "暗くて看板がかろうじて見えた。", "ex2": "I can't make out the handwriting on this form.", "ja2": "この用紙の手書き文字が判読できない。", "note": "Stage 3 の make up と混同しやすい", "nuance": "かろうじて見分ける、判読するという困難さを伴う意味。", "groups": ["distinguish"], "etymology": "make（作る）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「（かろうじて）見分ける、判読する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"rotate(12,32,32)\"><rect x=\"18\" y=\"34\" width=\"10\" height=\"12\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><rect x=\"28\" y=\"26\" width=\"10\" height=\"20\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><rect x=\"38\" y=\"18\" width=\"10\" height=\"28\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 183, "stage": 4, "verb": "bring out", "meaning": "世に出す、（性質を）引き出す", "def": "to release a product; to make a quality more noticeable", "ex1": "They brought out a new album.", "ja1": "彼らは新しいアルバムを出した。", "ex2": "We're bringing out the new version in September.", "ja2": "9月に新バージョンをリリースします。", "note": "", "nuance": "新製品などを世に送り出す、リリースのニュアンス。", "groups": ["bring_in_out"], "etymology": "bring（持ってくる）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「世に出す、（性質を）引き出す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#9A5B2E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(14,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 184, "stage": 4, "verb": "catch up*2", "meaning": "近況を語り合う、情報を共有する", "def": "to exchange news with someone you have not seen for a while", "ex1": "Let's catch up over coffee.", "ja1": "コーヒーでも飲みながら近況を話そう。", "ex2": "Let's catch up briefly before the client call.", "ja2": "顧客との電話の前に少し状況を共有しましょう。", "note": "Stage 2 の catch up（追いつく）と区別", "nuance": "近況を語り合う（Stage2のcatch upとは別）、久しぶりの再会。", "groups": ["socialize_catch_up"], "etymology": "catch（捕まえる）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「近況を語り合う、情報を共有する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#2E6B4F\"/><g transform=\"rotate(-4,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 185, "stage": 4, "verb": "take down*2", "meaning": "取り壊す、撤去する", "def": "to remove or dismantle something", "ex1": "They took down the old fence.", "ja1": "古い柵を取り壊した。", "ex2": "We took down the booth after the exhibition.", "ja2": "展示会の後、ブースを撤去した。", "note": "元リストで take down が2回出現するため別語義として整理", "nuance": "取り壊す・撤去するという物理的な解体。", "groups": ["take_down_senses"], "etymology": "take（取る）＋down（下へ）\n→ 下向き・減少や書き留めるイメージ\n→ そこから「取り壊す、撤去する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"rotate(4,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 16 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 186, "stage": 4, "verb": "bring down", "meaning": "引き下げる、失脚させる", "def": "to reduce something; to cause someone or something to fall", "ex1": "The news brought down his mood.", "ja1": "その知らせで彼は落ち込んだ。", "ex2": "We need to bring down the running costs.", "ja2": "運用コストを引き下げる必要がある。", "note": "", "nuance": "価格やコストを引き下げる、または人を失脚させる比喩。", "groups": [], "etymology": "bring（持ってくる）＋down（下へ）\n→ 下向き・減少や書き留めるイメージ\n→ そこから「引き下げる、失脚させる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(14,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 16 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 187, "stage": 4, "verb": "put out*3", "meaning": "迷惑をかける、手間をかけさせる", "def": "to cause someone extra trouble or inconvenience", "ex1": "I don't want to put you out.", "ja1": "ご迷惑をおかけしたくありません。", "ex2": "I hope the schedule change didn't put you out.", "ja2": "日程変更でご迷惑をおかけしていなければよいのですが。", "note": "Stage 3 / 4 の put out と区別", "nuance": "迷惑をかける、手間を取らせるという気遣いの表現。", "groups": ["put_out_senses"], "etymology": "put（置く）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「迷惑をかける、手間をかけさせる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(2,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 188, "stage": 4, "verb": "pull off", "meaning": "やってのける、成功させる", "def": "to succeed in doing something difficult", "ex1": "She pulled off a perfect performance.", "ja1": "彼女は完璧な演技をやってのけた。", "ex2": "The team pulled off the migration in one night.", "ja2": "チームは一晩で移行をやり遂げた。", "note": "Stage 8 に別語義あり", "nuance": "困難なことをやってのける、成功の達成感を伴う。", "groups": ["succeed"], "etymology": "pull（引く）＋off（離れて）\n→ くっついていた物が離れる・停止や出発のイメージ\n→ そこから「やってのける、成功させる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(8,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 189, "stage": 4, "verb": "pull over", "meaning": "（車を）路肩に寄せて止める", "def": "to move a vehicle to the side of the road and stop", "ex1": "The police told him to pull over.", "ja1": "警察は彼に車を停めるよう言った。", "ex2": "Pull over here; the entrance is on the left.", "ja2": "ここで停めてください、入口は左手です。", "note": "", "nuance": "車を道路脇に停止させる、運転時の具体的動作。", "groups": ["pull_over_stop_car"], "etymology": "pull（引く）＋over（越えて）\n→ 何かを越えて広がる・一通り目を通すイメージ\n→ そこから「（車を）路肩に寄せて止める」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#9A5B2E\"/><g transform=\"rotate(-1,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 2 A6 6 0 1 1 2 8\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2.2\"/><path d=\"M2 8 L0 4 M2 8 L6 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 190, "stage": 4, "verb": "tag along", "meaning": "くっついていく、同行する", "def": "to go somewhere with someone, often without being invited", "ex1": "My little sister always tags along.", "ja1": "妹はいつもついてくる。", "ex2": "Can I tag along to the client meeting to observe?", "ja2": "見学のため顧客訪問に同行してもよいですか。", "note": "", "nuance": "誘われずについていく、くっついていくカジュアルな表現。", "groups": ["come_along_together"], "etymology": "tag（タグをつける・くっついていく）＋along（沿って）\n→ 一緒に・並んで進むイメージ\n→ そこから「くっついていく、同行する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"rotate(9,32,32)\"><circle cx=\"24\" cy=\"32\" r=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"40\" cy=\"32\" r=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 5 L16 5 M0 11 L16 11\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 191, "stage": 4, "verb": "hold out", "meaning": "持ちこたえる、持続する", "def": "to continue to last or resist", "ex1": "Our supplies will hold out for a week.", "ja1": "備蓄は1週間持つ。", "ex2": "The old server held out until the migration was done.", "ja2": "移行が終わるまで旧サーバーは持ちこたえた。", "note": "", "nuance": "持ちこたえる、限界まで粘る忍耐のニュアンス。", "groups": ["hold_out_off"], "etymology": "hold（持つ・保つ）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「持ちこたえる、持続する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#1B2A41\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(7,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 192, "stage": 4, "verb": "brush up", "meaning": "復習する、磨き直す", "def": "to improve a skill that you learned before", "ex1": "I need to brush up my French.", "ja1": "フランス語を復習しないといけない。", "ex2": "I'm brushing up on my presentation skills.", "ja2": "プレゼンのスキルを磨き直しています。", "note": "brush up on の形が多い", "nuance": "以前学んだスキルを磨き直す、復習のニュアンス。", "groups": ["study_review"], "etymology": "brush（さっと払う）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「復習する、磨き直す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"rotate(-2,32,32)\"><path d=\"M40 16 L24 44\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/><path d=\"M24 44 L16 50 M24 44 L20 50 M24 44 L28 50\" stroke=\"#C79A3D\" stroke-width=\"2\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 193, "stage": 4, "verb": "pay off", "meaning": "完済する", "def": "to finish paying a debt", "ex1": "We paid off the loan last year.", "ja1": "昨年ローンを完済した。", "ex2": "The company paid off its debt ahead of schedule.", "ja2": "会社は予定より早く負債を完済した。", "note": "Stage 4 の pay off*2 と区別", "nuance": "借金を完済する、金銭的な区切りを表す。", "groups": ["pay_related"], "etymology": "pay（払う）＋off（離れて）\n→ くっついていた物が離れる・停止や出発のイメージ\n→ そこから「完済する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"rotate(6,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"14\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M28 26 L36 26 M28 32 L36 32 M28 38 L36 38\" stroke=\"#C79A3D\" stroke-width=\"2\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 194, "stage": 4, "verb": "push back", "meaning": "反発する、難色を示す", "def": "to resist or express disagreement with a plan", "ex1": "He pushed back when I suggested leaving early.", "ja1": "早く出ようと言ったら彼は反対した。", "ex2": "The client pushed back on our estimate.", "ja2": "顧客は我々の見積もりに難色を示した。", "note": "Stage 7 に別語義あり", "nuance": "反発する、抵抗を示す否定的なニュアンス。Stage7に別義あり。", "groups": ["oppose_resist"], "etymology": "push（押す）＋back（後ろ・元へ）\n→ 元の場所や状態に戻るイメージ\n→ そこから「反発する、難色を示す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-2,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M14 4 Q4 4 4 12 M4 12 L0 9 M4 12 L8 12\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 195, "stage": 4, "verb": "put on*2", "meaning": "体重が増える", "def": "to gain weight", "ex1": "I put on three kilos over the holidays.", "ja1": "休暇で3キロ太った。", "ex2": "He put on weight after moving to a desk job.", "ja2": "内勤になってから彼は太った。", "note": "Stage 1 の put on（着る）と区別", "nuance": "着る（Stage1）とは別に、体重が増えるという意味。", "groups": [], "etymology": "put（置く）＋on（接触・継続）\n→ くっついたまま続く・作動し続けるイメージ\n→ そこから「体重が増える」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"rotate(-6,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 196, "stage": 4, "verb": "chill out", "meaning": "リラックスする、落ち着く", "def": "to relax and stop being angry or nervous", "ex1": "Let's chill out at home tonight.", "ja1": "今夜は家でのんびりしよう。", "ex2": "Chill out — we still have two weeks before the deadline.", "ja2": "落ち着いて、締切まではまだ2週間ある。", "note": "かなりくだけた表現。目上には使わない", "nuance": "リラックスする、非常にカジュアルな表現で目上には不向き。", "groups": ["calm_down"], "etymology": "chill（冷やす・くつろぐ）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「リラックスする、落ち着く」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#1B2A41\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-12,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"16\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"27\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><circle cx=\"37\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><path d=\"M26 38 Q32 42 38 38\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 197, "stage": 4, "verb": "pay off*2", "meaning": "（努力が）実を結ぶ", "def": "to produce good results after effort or investment", "ex1": "All that practice paid off.", "ja1": "あれだけの練習が実を結んだ。", "ex2": "The extra testing paid off; there were no defects.", "ja2": "追加テストが功を奏し、不具合はなかった。", "note": "Stage 4 の pay off（完済する）と区別", "nuance": "完済（Stage4）とは別に、努力が実を結ぶという意味。", "groups": ["succeed"], "etymology": "pay（払う）＋off（離れて）\n→ くっついていた物が離れる・停止や出発のイメージ\n→ そこから「（努力が）実を結ぶ」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"rotate(6,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"14\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M28 26 L36 26 M28 32 L36 32 M28 38 L36 38\" stroke=\"#C79A3D\" stroke-width=\"2\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 198, "stage": 4, "verb": "make out*2 (2)", "meaning": "うまくやる、首尾よくいく", "def": "to manage or succeed in a particular situation", "ex1": "How did you make out at the interview?", "ja1": "面接はどうでしたか。", "ex2": "How did the team make out on the first day of the rollout?", "ja2": "展開初日、チームの首尾はどうでしたか。", "note": "元リストで make out*2 が2回出現するため別語義として整理", "nuance": "同じmake out*2でも「うまくやる」という別の口語表現。", "groups": ["succeed"], "etymology": "make（作る）＋out*2（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「うまくやる、首尾よくいく」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#9A5B2E\"/><g transform=\"rotate(-13,32,32)\"><rect x=\"18\" y=\"34\" width=\"10\" height=\"12\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><rect x=\"28\" y=\"26\" width=\"10\" height=\"20\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><rect x=\"38\" y=\"18\" width=\"10\" height=\"28\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 199, "stage": 4, "verb": "make up*3", "meaning": "（不足を）埋め合わせる", "def": "to compensate for something that is missing or lost", "ex1": "I'll make up the difference.", "ja1": "差額は私が埋めます。", "ex2": "We worked overtime to make up the lost days.", "ja2": "遅れた日数を取り戻すため残業した。", "note": "Stage 3 / 4 / 5 に別語義あり", "nuance": "でっちあげる・仲直りとは別に、不足分を埋め合わせる意味。", "groups": ["make_up_senses"], "etymology": "make（作る）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「（不足を）埋め合わせる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(3,32,32)\"><rect x=\"18\" y=\"34\" width=\"10\" height=\"12\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><rect x=\"28\" y=\"26\" width=\"10\" height=\"20\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><rect x=\"38\" y=\"18\" width=\"10\" height=\"28\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 200, "stage": 4, "verb": "take up", "meaning": "始める／（時間・場所を）とる", "def": "to start a new activity; to occupy time or space", "ex1": "She took up yoga last year.", "ja1": "彼女は昨年ヨガを始めた。", "ex2": "This task takes up most of my morning.", "ja2": "この作業で午前中がほとんど埋まる。", "note": "元リスト表記は take-up。Stage 5 に take up*2 あり", "nuance": "新しい活動を始める、または時間・場所を占有する意味。", "groups": ["undertake_continue_work"], "etymology": "take（取る）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「始める／（時間・場所を）とる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#2E6B4F\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(6,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 201, "stage": 4, "verb": "take out*2", "meaning": "（保険・ローンを）契約する", "def": "to arrange to get insurance or a loan", "ex1": "They took out a mortgage on the house.", "ja1": "彼らは住宅ローンを組んだ。", "ex2": "The company took out insurance against project delays.", "ja2": "会社はプロジェクト遅延に備えて保険を掛けた。", "note": "Stage 3 の take out（取り出す）と区別", "nuance": "取り出す（Stage3）とは別に、保険やローンを契約する意味。", "groups": ["take_out_senses"], "etymology": "take（取る）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「（保険・ローンを）契約する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#2E6B4F\"/><g transform=\"rotate(14,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 202, "stage": 4, "verb": "go into", "meaning": "詳しく述べる／（分野に）進む", "def": "to explain in detail; to enter a field of work", "ex1": "I won't go into the details now.", "ja1": "今は詳細には触れません。", "ex2": "She went into consulting after graduation.", "ja2": "彼女は卒業後コンサルティング業界に進んだ。", "note": "", "nuance": "詳細を説明する意味と、ある分野に進むという進路の意味。", "groups": ["elaborate_dig"], "etymology": "go（行く）＋into（中へ変化）\n→ ある状態の中に入り込む・変化を伴うイメージ\n→ そこから「詳しく述べる／（分野に）進む」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#8A4B8A\"/><g transform=\"rotate(-3,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 203, "stage": 5, "verb": "blow away", "meaning": "感動させる、圧倒する", "def": "to impress someone very much", "ex1": "The view blew me away.", "ja1": "その景色に圧倒された。", "ex2": "The demo blew away the client.", "ja2": "デモは顧客を圧倒した。", "note": "", "nuance": "感動や驚きで圧倒する、強いインパクトを与える表現。", "groups": [], "etymology": "blow（吹く）＋away（遠くへ）\n→ その場から遠ざかる・消えていくイメージ\n→ そこから「感動させる、圧倒する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#1B2A41\"/><g transform=\"rotate(13,32,32)\"><path d=\"M14 32 Q20 22 26 32 Q32 42 38 32 Q44 22 50 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-dasharray=\"3 2\" stroke-linecap=\"round\"/><path d=\"M11 3 L16 8 L11 13\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 204, "stage": 5, "verb": "come along*2", "meaning": "（機会が）巡ってくる、現れる", "def": "to appear or become available", "ex1": "A chance like this doesn't come along often.", "ja1": "こんな機会はめったに来ない。", "ex2": "If a better offer comes along, we'll consider it.", "ja2": "より良い提案が出てくれば検討します。", "note": "Stage 2 の come along と区別", "nuance": "一緒に来る（Stage2）とは別に、機会が巡ってくるという意味。", "groups": ["opportunity_arises"], "etymology": "come（来る）＋along（沿って）\n→ 一緒に・並んで進むイメージ\n→ そこから「（機会が）巡ってくる、現れる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"rotate(2,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 5 L16 5 M0 11 L16 11\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 205, "stage": 5, "verb": "kick out", "meaning": "追い出す、除名する", "def": "to force someone to leave a place or group", "ex1": "He was kicked out of the club.", "ja1": "彼はクラブを追い出された。", "ex2": "The vendor was kicked out of the project for poor quality.", "ja2": "品質不良でその業者はプロジェクトから外された。", "note": "", "nuance": "組織や場所から強制的に追い出す、排除のニュアンス。", "groups": [], "etymology": "kick（蹴る）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「追い出す、除名する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#1B2A41\"/><g transform=\"rotate(-14,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 206, "stage": 5, "verb": "take back*2", "meaning": "元の場所へ戻す／思い出させる", "def": "to return someone or something to a place; to remind of the past", "ex1": "Take me back to the station.", "ja1": "駅まで戻してください。", "ex2": "This photo takes me back to my first project.", "ja2": "この写真を見ると最初のプロジェクトを思い出す。", "note": "Stage 3 の take back（返品・撤回）と区別", "nuance": "返品・撤回（Stage3）とは別に、元の場所へ戻す・思い出させる意味。", "groups": ["return"], "etymology": "take（取る）＋back（後ろ・元へ）\n→ 元の場所や状態に戻るイメージ\n→ そこから「元の場所へ戻す／思い出させる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"rotate(-4,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M14 4 Q4 4 4 12 M4 12 L0 9 M4 12 L8 12\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 207, "stage": 5, "verb": "back off", "meaning": "引き下がる、手を引く", "def": "to stop pressing someone or interfering", "ex1": "Back off and give her some space.", "ja1": "引き下がって彼女をそっとしておいて。", "ex2": "The client backed off from the additional request.", "ja2": "顧客は追加要望を取り下げた。", "note": "", "nuance": "圧力をかけるのをやめて引き下がる、譲歩の表現。", "groups": ["give_up_in"], "etymology": "back（後ろへ）＋off（離れて）\n→ くっついていた物が離れる・停止や出発のイメージ\n→ そこから「引き下がる、手を引く」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-14,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 208, "stage": 5, "verb": "make up*4", "meaning": "構成する、占める", "def": "to form or compose a whole", "ex1": "Women make up half of the class.", "ja1": "女性がクラスの半分を占める。", "ex2": "Licence fees make up 60 percent of the cost.", "ja2": "ライセンス費用がコストの6割を占める。", "note": "Stage 3 / 4 に別語義あり", "nuance": "構成する・占めるという、全体に対する割合を表す用法。", "groups": ["make_up_senses"], "etymology": "make（作る）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「構成する、占める」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(3,32,32)\"><rect x=\"18\" y=\"34\" width=\"10\" height=\"12\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><rect x=\"28\" y=\"26\" width=\"10\" height=\"20\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><rect x=\"38\" y=\"18\" width=\"10\" height=\"28\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 209, "stage": 5, "verb": "bring up*2", "meaning": "育てる、養育する", "def": "to raise a child", "ex1": "She was brought up in Osaka.", "ja1": "彼女は大阪で育った。", "ex2": "He was brought up to value punctuality.", "ja2": "彼は時間厳守を重んじるよう育てられた。", "note": "Stage 3 の bring up（話題を出す）と区別", "nuance": "話題を出す（Stage3）とは別に、子どもを育てるという意味。", "groups": ["bring_up_senses"], "etymology": "bring（持ってくる）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「育てる、養育する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#1B2A41\"/><g transform=\"rotate(3,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 210, "stage": 5, "verb": "take down*3", "meaning": "やり込める、打ち負かす", "def": "to defeat someone or destroy their argument", "ex1": "The champion was taken down in the final.", "ja1": "王者は決勝で敗れた。", "ex2": "The report took down the manager's argument point by point.", "ja2": "その報告は上司の主張を一つずつ論破した。", "note": "Stage 4 の take down / take down*2 と区別", "nuance": "書き留める・撤去とは別に、相手を打ち負かすという意味。", "groups": ["take_down_senses"], "etymology": "take（取る）＋down（下へ）\n→ 下向き・減少や書き留めるイメージ\n→ そこから「やり込める、打ち負かす」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"rotate(4,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 16 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 211, "stage": 5, "verb": "break down", "meaning": "故障する、（人が）取り乱す", "def": "to stop working; to lose emotional control", "ex1": "My car broke down on the highway.", "ja1": "高速道路で車が故障した。", "ex2": "The system broke down during peak hours.", "ja2": "ピーク時にシステムが停止した。", "note": "Stage 5 の break down*2 と区別", "nuance": "機械が故障する意味と、感情的に取り乱す意味の両方。", "groups": ["break_malfunction"], "etymology": "break（壊す・分ける）＋down（下へ）\n→ 下向き・減少や書き留めるイメージ\n→ そこから「故障する、（人が）取り乱す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"rotate(-7,32,32)\"><path d=\"M16 32 L26 32 L30 22 L36 42 L40 32 L48 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linejoin=\"round\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 16 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 212, "stage": 5, "verb": "dress up", "meaning": "着飾る、正装する", "def": "to wear formal or special clothes", "ex1": "She dressed up for the wedding.", "ja1": "彼女は結婚式のために着飾った。", "ex2": "You don't need to dress up for the casual meeting.", "ja2": "カジュアルな打ち合わせなので正装は不要です。", "note": "", "nuance": "特別な場に向けて着飾る、フォーマルな準備を表す。", "groups": ["clothing_wear"], "etymology": "dress（着せる）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「着飾る、正装する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#2E6B4F\"/><g transform=\"rotate(14,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"16\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"27\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><circle cx=\"37\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><path d=\"M26 38 Q32 42 38 38\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 213, "stage": 5, "verb": "get in*2", "meaning": "（組織・学校に）入る、合格する", "def": "to be accepted into a school or organization", "ex1": "He got in to his first-choice university.", "ja1": "彼は第一志望の大学に合格した。", "ex2": "It's hard to get in to that company without a referral.", "ja2": "紹介なしにあの会社に入るのは難しい。", "note": "Stage 1 の get in（乗り込む）と区別", "nuance": "乗り込む（Stage1）とは別に、組織や学校に合格し入る意味。", "groups": ["enter_various"], "etymology": "get（得る・～になる）＋in（中へ）\n→ 外から中に入る・参加や到着のイメージ\n→ そこから「（組織・学校に）入る、合格する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"rotate(5,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 214, "stage": 5, "verb": "keep on", "meaning": "〜し続ける", "def": "to continue doing something", "ex1": "He kept on talking.", "ja1": "彼は話し続けた。", "ex2": "Keep on testing until the issue is reproduced.", "ja2": "事象が再現するまでテストを続けてください。", "note": "後ろは動名詞（-ing）", "nuance": "同じ行動を続ける、持続のニュアンス。後ろは-ing形。", "groups": ["undertake_continue_work"], "etymology": "keep（保つ）＋on（接触・継続）\n→ くっついたまま続く・作動し続けるイメージ\n→ そこから「〜し続ける」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(7,32,32)\"><rect x=\"16\" y=\"24\" width=\"32\" height=\"24\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M16 24 L32 14 L48 24\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 215, "stage": 5, "verb": "take away", "meaning": "持ち去る、取り上げる", "def": "to remove something or someone from a place", "ex1": "Take away the empty plates.", "ja1": "空いた皿を下げてください。", "ex2": "The new rule took away our flexibility.", "ja2": "新しい規則で柔軟性が失われた。", "note": "", "nuance": "物を取り上げる意味と、柔軟性などを奪う比喩の意味。", "groups": [], "etymology": "take（取る）＋away（遠くへ）\n→ その場から遠ざかる・消えていくイメージ\n→ そこから「持ち去る、取り上げる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#9A5B2E\"/><g transform=\"rotate(-2,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-dasharray=\"3 2\" stroke-linecap=\"round\"/><path d=\"M11 3 L16 8 L11 13\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 216, "stage": 5, "verb": "fill in", "meaning": "記入する", "def": "to write information in the spaces on a form", "ex1": "Fill in this form, please.", "ja1": "この用紙に記入してください。", "ex2": "Please fill in the required fields in the request sheet.", "ja2": "依頼書の必須項目を記入してください。", "note": "Stage 7 に fill in*2、Stage 5 に fill in for あり", "nuance": "記入する動作。fill in for（代理）、fill in*2（伝える）と区別。", "groups": ["fill_form"], "etymology": "fill（満たす）＋in（中へ）\n→ 外から中に入る・参加や到着のイメージ\n→ そこから「記入する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#9A5B2E\"/><g transform=\"rotate(12,32,32)\"><path d=\"M32 14 Q44 30 44 38 Q44 48 32 48 Q20 48 20 38 Q20 30 32 14 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 217, "stage": 5, "verb": "take apart", "meaning": "分解する", "def": "to separate something into its parts", "ex1": "He took apart the old clock.", "ja1": "彼は古い時計を分解した。", "ex2": "We took apart the process to find the bottleneck.", "ja2": "ボトルネックを見つけるため工程を分解した。", "note": "", "nuance": "物を分解して構造を理解する、分析的なニュアンス。", "groups": ["break_into_parts"], "etymology": "take（取る）＋apart（ばらばらに）\n→ 一つだった物が分かれていくイメージ\n→ そこから「分解する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#9A5B2E\"/><g transform=\"rotate(6,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 2 L0 8 L8 14 M8 2 L16 8 L8 14\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 218, "stage": 5, "verb": "hold in", "meaning": "（感情を）抑える", "def": "to keep an emotion from being shown", "ex1": "She held in her anger.", "ja1": "彼女は怒りを抑えた。", "ex2": "He held in his frustration during the negotiation.", "ja2": "交渉中、彼は苛立ちを抑えた。", "note": "Stage 5 の hold in*2 と区別", "nuance": "感情を表に出さず抑える、我慢のニュアンス。", "groups": ["hold_in_senses"], "etymology": "hold（持つ・保つ）＋in（中へ）\n→ 外から中に入る・参加や到着のイメージ\n→ そこから「（感情を）抑える」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#1B2A41\"/><g transform=\"rotate(5,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 219, "stage": 5, "verb": "keep off", "meaning": "近づかない、（話題を）避ける", "def": "to stay away from something; to avoid a topic", "ex1": "Keep off the grass.", "ja1": "芝生に入らないでください。", "ex2": "Let's keep off the pricing topic until legal reviews it.", "ja2": "法務が確認するまで価格の話題は避けましょう。", "note": "", "nuance": "対象に近づかせない、または話題を避ける表現。", "groups": ["avoid_stay_away"], "etymology": "keep（保つ）＋off（離れて）\n→ くっついていた物が離れる・停止や出発のイメージ\n→ そこから「近づかない、（話題を）避ける」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#1B2A41\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(0,32,32)\"><rect x=\"16\" y=\"24\" width=\"32\" height=\"24\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M16 24 L32 14 L48 24\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 220, "stage": 5, "verb": "cover up", "meaning": "隠蔽する、覆い隠す", "def": "to hide a mistake or wrongdoing", "ex1": "He tried to cover up the mistake.", "ja1": "彼はミスを隠そうとした。", "ex2": "Covering up a defect makes the problem worse.", "ja2": "不具合を隠蔽すると問題は悪化する。", "note": "", "nuance": "不都合な事実やミスを隠す、否定的なニュアンス。", "groups": [], "etymology": "cover（覆う）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「隠蔽する、覆い隠す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"rotate(5,32,32)\"><rect x=\"16\" y=\"24\" width=\"32\" height=\"24\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M16 24 L32 14 L48 24\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 221, "stage": 5, "verb": "turn down", "meaning": "断る、却下する", "def": "to refuse an offer, request, or application", "ex1": "She turned down the invitation.", "ja1": "彼女は招待を断った。", "ex2": "They turned down our request for an extension.", "ja2": "先方は納期延長の依頼を断った。", "note": "Stage 3 の turn down（音量を下げる）と区別", "nuance": "音量調整（Stage3）とは別に、申し出や依頼を断る意味。", "groups": [], "etymology": "turn（向きを変える）＋down（下へ）\n→ 下向き・減少や書き留めるイメージ\n→ そこから「断る、却下する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-1,32,32)\"><path d=\"M32 32 m-4,0 a4,4 0 1,0 8,0 a8,8 0 1,0 -16,0 a12,12 0 1,0 24,0 a16,16 0 1,0 -32,0\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 16 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 222, "stage": 5, "verb": "catch on", "meaning": "人気が出る、広まる", "def": "to become popular or fashionable", "ex1": "The new game caught on quickly.", "ja1": "その新作ゲームはすぐ人気が出た。", "ex2": "The service caught on among small businesses.", "ja2": "そのサービスは中小企業に広まった。", "note": "Stage 7 に別語義あり", "nuance": "人気が出て広まる、流行のニュアンス。", "groups": ["gain_popularity"], "etymology": "catch（捕まえる）＋on（接触・継続）\n→ くっついたまま続く・作動し続けるイメージ\n→ そこから「人気が出る、広まる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-4,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 223, "stage": 5, "verb": "come around*3", "meaning": "（時期が）巡ってくる", "def": "to happen again as part of a regular cycle", "ex1": "My birthday comes around too fast.", "ja1": "誕生日が来るのが早すぎる。", "ex2": "Budget season comes around every October.", "ja2": "予算の時期は毎年10月に巡ってくる。", "note": "元リスト表記は come-around*3", "nuance": "巡ってくる（Stage5）とは別に、行事が周期的に訪れる意味。", "groups": ["opportunity_arises"], "etymology": "come（来る）＋around（周りに）\n→ あちこち・ぐるりと回るイメージ\n→ そこから「（時期が）巡ってくる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-9,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 2 A6 6 0 1 1 2 8\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2.2\"/><path d=\"M2 8 L0 4 M2 8 L6 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 224, "stage": 5, "verb": "put together", "meaning": "組み立てる、まとめ上げる", "def": "to assemble or create something from separate parts", "ex1": "We put together the furniture ourselves.", "ja1": "家具を自分たちで組み立てた。", "ex2": "She put together the proposal in two days.", "ja2": "彼女は2日で提案書をまとめた。", "note": "", "nuance": "部品や情報を組み合わせて完成させる、構築のニュアンス。", "groups": ["organize"], "etymology": "put（置く）＋together（一つに）\n→ バラバラだった物が一つにまとまるイメージ\n→ そこから「組み立てる、まとめ上げる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#1B2A41\"/><g transform=\"rotate(-6,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 2 L8 8 L0 14 M16 2 L8 8 L16 14\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 225, "stage": 5, "verb": "hold in*2", "meaning": "（熱・水などを）閉じ込める", "def": "to keep something inside and prevent it from escaping", "ex1": "This jacket holds in the heat.", "ja1": "この上着は熱を逃がさない。", "ex2": "The case holds in the heat, so ventilation is needed.", "ja2": "筐体は熱がこもるので換気が必要だ。", "note": "Stage 5 の hold in（感情を抑える）と区別", "nuance": "感情を抑える（Stage5）とは別に、熱や水分を内部に保つ意味。", "groups": ["hold_in_senses"], "etymology": "hold（持つ・保つ）＋in（中へ）\n→ 外から中に入る・参加や到着のイメージ\n→ そこから「（熱・水などを）閉じ込める」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#1B2A41\"/><g transform=\"rotate(5,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 226, "stage": 5, "verb": "break down*2", "meaning": "分解する、内訳を示す", "def": "to divide something into smaller parts for analysis", "ex1": "Let's break down the recipe into steps.", "ja1": "レシピを手順に分解しよう。", "ex2": "Please break down the cost by category.", "ja2": "コストを費目ごとに分けて示してください。", "note": "Stage 5 の break down（故障する）と区別", "nuance": "故障（Stage5）とは別に、要素ごとに分解して分析する意味。", "groups": ["break_into_parts"], "etymology": "break（壊す・分ける）＋down（下へ）\n→ 下向き・減少や書き留めるイメージ\n→ そこから「分解する、内訳を示す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"rotate(-7,32,32)\"><path d=\"M16 32 L26 32 L30 22 L36 42 L40 32 L48 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linejoin=\"round\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 16 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 227, "stage": 5, "verb": "slack off", "meaning": "手を抜く、怠ける", "def": "to work less hard than you should", "ex1": "Don't slack off before the exam.", "ja1": "試験前に手を抜かないで。", "ex2": "Quality drops when we slack off on reviews.", "ja2": "レビューの手を抜くと品質が落ちる。", "note": "", "nuance": "本来やるべきことを怠る、サボりのニュアンス。", "groups": ["slack_off_group"], "etymology": "slack（たるむ・怠ける）＋off（離れて）\n→ くっついていた物が離れる・停止や出発のイメージ\n→ そこから「手を抜く、怠ける」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#2E6B4F\"/><g transform=\"rotate(13,32,32)\"><path d=\"M14 32 Q20 22 26 32 Q32 42 38 32 Q44 22 50 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 228, "stage": 5, "verb": "cover for", "meaning": "代理を務める、かばう", "def": "to do someone's work while they are away; to protect someone", "ex1": "Can you cover for me on Friday?", "ja1": "金曜、代わってもらえますか。", "ex2": "I'll cover for her while she's on leave.", "ja2": "休暇中は私が彼女の代わりを務めます。", "note": "", "nuance": "誰かの仕事を一時的に代行する、または守るという意味。", "groups": ["help_cover"], "etymology": "cover（覆う）＋for（求めて）\n→ 目的物を求めて手を伸ばすイメージ\n→ そこから「代理を務める、かばう」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#8A4B8A\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-12,32,32)\"><rect x=\"16\" y=\"24\" width=\"32\" height=\"24\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M16 24 L32 14 L48 24\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/><path d=\"M0 8 L11 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 229, "stage": 5, "verb": "kick off", "meaning": "開始する", "def": "to start an event, match, or project", "ex1": "The match kicks off at seven.", "ja1": "試合は7時に始まる。", "ex2": "We kick off the project next Monday.", "ja2": "来週月曜にプロジェクトを開始します。", "note": "", "nuance": "イベントや活動を開始する、スタートの合図。", "groups": [], "etymology": "kick（蹴る）＋off（離れて）\n→ くっついていた物が離れる・停止や出発のイメージ\n→ そこから「開始する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"rotate(12,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 230, "stage": 5, "verb": "hold up", "meaning": "遅らせる／（強盗が）襲う", "def": "to delay someone or something; to rob using force", "ex1": "Traffic held us up for an hour.", "ja1": "渋滞で1時間遅れた。", "ex2": "The approval process held up the release.", "ja2": "承認プロセスがリリースを遅らせた。", "note": "", "nuance": "予定を遅らせる意味と、強盗が襲う意味の両方。", "groups": [], "etymology": "hold（持つ・保つ）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「遅らせる／（強盗が）襲う」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"rotate(7,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 231, "stage": 5, "verb": "come across", "meaning": "偶然見つける、出くわす", "def": "to find or meet something by chance", "ex1": "I came across an old letter.", "ja1": "古い手紙を偶然見つけた。", "ex2": "I came across a useful case study on their site.", "ja2": "先方のサイトで役立つ事例を偶然見つけた。", "note": "Stage 6 の come across as と区別", "nuance": "偶然に何かを見つける、予期せぬ発見。come across asと区別。", "groups": ["encounter"], "etymology": "come（来る）＋across（横切って）\n→ ある空間や境界を横切って向こう側に届くイメージ\n→ そこから「偶然見つける、出くわす」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"rotate(6,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M2 2 L14 14\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><path d=\"M2 14 L14 2\" stroke=\"#B5392F\" stroke-width=\"1.4\" opacity=\"0.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 232, "stage": 5, "verb": "put up with", "meaning": "我慢する、耐える", "def": "to tolerate something unpleasant", "ex1": "I can't put up with this noise.", "ja1": "この騒音には我慢できない。", "ex2": "We put up with the slow system for months.", "ja2": "我々は何か月も遅いシステムに耐えた。", "note": "Stage 1 / 2 の put up と区別", "nuance": "不快なことを我慢して耐える、忍耐を要する表現。", "groups": ["endure"], "etymology": "put（置く）＋with（一緒に）\n→ 対象と一緒に行動するイメージ\n→ そこから「我慢する、耐える」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#8A4B8A\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-10,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 2 L8 14 M2 8 L14 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 233, "stage": 5, "verb": "look into", "meaning": "調査する、検討する", "def": "to investigate a matter", "ex1": "I'll look into the problem.", "ja1": "その問題を調べます。", "ex2": "We're looking into the cause of the delay.", "ja2": "遅延の原因を調査しています。", "note": "", "nuance": "問題を詳しく調査する、原因究明のニュアンス。", "groups": ["review_check"], "etymology": "look（見る）＋into（中へ変化）\n→ ある状態の中に入り込む・変化を伴うイメージ\n→ そこから「調査する、検討する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#8A4B8A\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-9,32,32)\"><path d=\"M14 32 Q32 16 50 32 Q32 48 14 32 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"32\" cy=\"32\" r=\"7\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 234, "stage": 5, "verb": "use up", "meaning": "使い切る", "def": "to consume all of something", "ex1": "We used up all the paper.", "ja1": "紙を全部使い切った。", "ex2": "The team used up its budget by August.", "ja2": "チームは8月までに予算を使い切った。", "note": "", "nuance": "資源や時間を使い切る、消費し尽くす表現。", "groups": ["use_up"], "etymology": "use（使う）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「使い切る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#2E6B4F\"/><g transform=\"rotate(-15,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"10\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M32 14 L32 20 M32 44 L32 50 M14 32 L20 32 M44 32 L50 32 M20 20 L24 24 M40 40 L44 44 M44 20 L40 24 M24 40 L20 44\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 235, "stage": 5, "verb": "get over", "meaning": "立ち直る、克服する", "def": "to recover from an illness, shock, or difficulty", "ex1": "It took a month to get over the flu.", "ja1": "インフルエンザから回復するのに1か月かかった。", "ex2": "It took time to get over the failed release.", "ja2": "失敗したリリースから立ち直るのに時間がかかった。", "note": "", "nuance": "病気やショックから立ち直る、回復のニュアンス。", "groups": ["move_on_over"], "etymology": "get（得る・～になる）＋over（越えて）\n→ 何かを越えて広がる・一通り目を通すイメージ\n→ そこから「立ち直る、克服する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#2E6B4F\"/><g transform=\"rotate(4,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 2 A6 6 0 1 1 2 8\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2.2\"/><path d=\"M2 8 L0 4 M2 8 L6 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 236, "stage": 5, "verb": "sit on", "meaning": "（対応を）先延ばしにする、握りつぶす", "def": "to delay dealing with something", "ex1": "Don't sit on my email.", "ja1": "私のメールを放置しないで。", "ex2": "Management sat on the report for weeks.", "ja2": "経営陣は報告書を何週間も放置した。", "note": "", "nuance": "対応を先延ばしにして放置する、やや消極的な表現。", "groups": [], "etymology": "sit（座る）＋on（接触・継続）\n→ くっついたまま続く・作動し続けるイメージ\n→ そこから「（対応を）先延ばしにする、握りつぶす」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"rotate(1,32,32)\"><path d=\"M22 20 L22 44 L42 44 L42 30 M22 32 L42 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M22 44 L20 50 M42 44 L44 50\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 237, "stage": 5, "verb": "cheer on", "meaning": "声援を送る、応援する", "def": "to encourage someone by shouting support", "ex1": "We cheered on our team.", "ja1": "私たちはチームに声援を送った。", "ex2": "The whole office cheered on the presenters.", "ja2": "オフィス全員が発表者を応援した。", "note": "", "nuance": "声援を送って応援する、励ましの表現。", "groups": ["cheer_encourage"], "etymology": "cheer（励ます）＋on（接触・継続）\n→ くっついたまま続く・作動し続けるイメージ\n→ そこから「声援を送る、応援する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#2E6B4F\"/><g transform=\"rotate(-6,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"16\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"27\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><circle cx=\"37\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><path d=\"M26 38 Q32 42 38 38\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 238, "stage": 5, "verb": "take up*2", "meaning": "（提案を）受け入れる／（問題を）取り上げる", "def": "to accept an offer; to raise a matter for discussion", "ex1": "I'll take you up on your offer.", "ja1": "お言葉に甘えます。", "ex2": "We'll take up this issue at the steering committee.", "ja2": "この件は運営委員会で取り上げます。", "note": "Stage 4 の take up と区別", "nuance": "始める（Stage4）とは別に、申し出を受け入れる意味。", "groups": ["accept_take_up"], "etymology": "take（取る）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「（提案を）受け入れる／（問題を）取り上げる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#2E6B4F\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(6,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 239, "stage": 5, "verb": "pull away", "meaning": "離れていく、引き離す", "def": "to move away; to move ahead of others", "ex1": "The bus pulled away from the stop.", "ja1": "バスは停留所を離れていった。", "ex2": "The leading vendor pulled away from the competition.", "ja2": "首位のベンダーは競合を引き離した。", "note": "", "nuance": "その場から離れていく、または他より先に進む意味。", "groups": ["pull_out_away"], "etymology": "pull（引く）＋away（遠くへ）\n→ その場から遠ざかる・消えていくイメージ\n→ そこから「離れていく、引き離す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#9A5B2E\"/><g transform=\"rotate(-7,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-dasharray=\"3 2\" stroke-linecap=\"round\"/><path d=\"M11 3 L16 8 L11 13\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 240, "stage": 5, "verb": "own up", "meaning": "白状する、非を認める", "def": "to admit that you did something wrong", "ex1": "He owned up to breaking the window.", "ja1": "彼は窓を割ったことを認めた。", "ex2": "She owned up to the error in the estimate.", "ja2": "彼女は見積もりの誤りを認めた。", "note": "own up to の形で使う", "nuance": "自分の非を認める、素直な告白のニュアンス。own up toの形。", "groups": [], "etymology": "own（認める・所有する）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「白状する、非を認める」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#2E6B4F\"/><g transform=\"rotate(-9,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 241, "stage": 5, "verb": "fit in", "meaning": "なじむ、溶け込む", "def": "to be accepted as part of a group", "ex1": "The new student fit in quickly.", "ja1": "転校生はすぐになじんだ。", "ex2": "The new member fit in with the team right away.", "ja2": "新メンバーはすぐチームになじんだ。", "note": "Stage 7 に別語義あり", "nuance": "集団に溶け込む意味と、予定に組み込む意味（Stage7）がある。", "groups": ["adapt_fit_in"], "etymology": "fit（合う）＋in（中へ）\n→ 外から中に入る・参加や到着のイメージ\n→ そこから「なじむ、溶け込む」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#8A4B8A\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(3,32,32)\"><circle cx=\"24\" cy=\"32\" r=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"40\" cy=\"32\" r=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 242, "stage": 5, "verb": "stay over", "meaning": "泊まる、外泊する", "def": "to spend the night at someone else's place", "ex1": "You can stay over if it gets late.", "ja1": "遅くなったら泊まっていいですよ。", "ex2": "I stayed over near the site before the early cutover.", "ja2": "早朝の切替に備えて現場近くに前泊した。", "note": "", "nuance": "他人の家に一晩泊まる、宿泊のカジュアルな表現。", "groups": [], "etymology": "stay（とどまる）＋over（越えて）\n→ 何かを越えて広がる・一通り目を通すイメージ\n→ そこから「泊まる、外泊する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-10,32,32)\"><path d=\"M22 20 L22 44 L42 44 L42 30 M22 32 L42 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M22 44 L20 50 M42 44 L44 50\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 2 A6 6 0 1 1 2 8\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2.2\"/><path d=\"M2 8 L0 4 M2 8 L6 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 243, "stage": 5, "verb": "step out", "meaning": "少し席を外す", "def": "to leave a room or building for a short time", "ex1": "She stepped out to take a call.", "ja1": "彼女は電話のため席を外した。", "ex2": "He stepped out of the meeting for five minutes.", "ja2": "彼は5分ほど会議を中座した。", "note": "", "nuance": "一時的に席を外す、短時間の中座を表す。", "groups": ["exit_leave_briefly"], "etymology": "step（一歩踏み出す）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「少し席を外す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"rotate(0,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 244, "stage": 5, "verb": "head off", "meaning": "未然に防ぐ、先回りして止める", "def": "to prevent something from happening", "ex1": "We headed off an argument.", "ja1": "口論を未然に防いだ。", "ex2": "Early testing headed off a major defect.", "ja2": "早期のテストで重大な不具合を未然に防いだ。", "note": "", "nuance": "問題が起きる前に対処する、予防的なニュアンス。", "groups": [], "etymology": "head（向かう）＋off（離れて）\n→ くっついていた物が離れる・停止や出発のイメージ\n→ そこから「未然に防ぐ、先回りして止める」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"rotate(-7,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 245, "stage": 5, "verb": "fill in for", "meaning": "代理を務める", "def": "to do someone's job temporarily while they are away", "ex1": "Can you fill in for me tomorrow?", "ja1": "明日、代わってもらえますか。", "ex2": "I'll fill in for the PM while he's on leave.", "ja2": "PMの休暇中は私が代理を務めます。", "note": "Stage 5 の fill in（記入する）と区別", "nuance": "記入する（Stage5）とは別に、誰かの代理を務める意味。", "groups": ["help_cover"], "etymology": "fill（満たす）＋for（求めて）\n→ 目的物を求めて手を伸ばすイメージ\n→ そこから「代理を務める」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(6,32,32)\"><path d=\"M32 14 Q44 30 44 38 Q44 48 32 48 Q20 48 20 38 Q20 30 32 14 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/><path d=\"M0 8 L11 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 246, "stage": 5, "verb": "mix up", "meaning": "混同する、取り違える", "def": "to confuse one thing with another", "ex1": "I mixed up the two names.", "ja1": "2つの名前を取り違えた。", "ex2": "We mixed up the file versions and sent the old one.", "ja2": "ファイルの版を取り違えて古いものを送ってしまった。", "note": "", "nuance": "物事を混同する、取り違えのミスを表す。", "groups": [], "etymology": "mix（混ぜる）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「混同する、取り違える」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"rotate(2,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"12\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-dasharray=\"4 3\"/><circle cx=\"32\" cy=\"20\" r=\"3\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 247, "stage": 5, "verb": "pick up*3", "meaning": "回復する、勢いを増す", "def": "to improve or increase", "ex1": "Business picks up in December.", "ja1": "12月は商売が上向く。", "ex2": "Sales picked up after the campaign.", "ja2": "キャンペーンの後、売上が回復した。", "note": "Stage 2 / 3 に別語義あり", "nuance": "拾う・迎え・電話とは別に、状況が上向く・回復する意味。", "groups": ["pick_up_senses"], "etymology": "pick（つまむ・選ぶ）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「回復する、勢いを増す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-10,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 248, "stage": 5, "verb": "tell apart", "meaning": "見分ける、区別する", "def": "to distinguish between two similar things", "ex1": "I can't tell the twins apart.", "ja1": "その双子を見分けられない。", "ex2": "It's hard to tell the two plans apart.", "ja2": "2つのプランを見分けるのは難しい。", "note": "tell A and B apart の語順に注意", "nuance": "似ているものを見分ける、識別の難しさを含む表現。", "groups": ["distinguish"], "etymology": "tell（伝える）＋apart（ばらばらに）\n→ 一つだった物が分かれていくイメージ\n→ そこから「見分ける、区別する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#9A5B2E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-12,32,32)\"><path d=\"M14 20 Q14 16 18 16 L46 16 Q50 16 50 20 L50 36 Q50 40 46 40 L26 40 L18 48 L20 40 L18 40 Q14 40 14 36 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 2 L0 8 L8 14 M8 2 L16 8 L8 14\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 249, "stage": 5, "verb": "clear up", "meaning": "（天気が）晴れる／（誤解を）解く", "def": "to become fine; to resolve confusion or a problem", "ex1": "The weather cleared up in the afternoon.", "ja1": "午後には晴れた。", "ex2": "Let's clear up the misunderstanding about the scope.", "ja2": "スコープに関する誤解を解きましょう。", "note": "", "nuance": "天候が晴れる意味と、誤解が解けるという比喩の意味。", "groups": [], "etymology": "clear（片づける・澄ませる）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「（天気が）晴れる／（誤解を）解く」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#1B2A41\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-15,32,32)\"><path d=\"M40 16 L24 44\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/><path d=\"M24 44 L16 50 M24 44 L20 50 M24 44 L28 50\" stroke=\"#C79A3D\" stroke-width=\"2\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 250, "stage": 5, "verb": "dive in", "meaning": "勢いよく取りかかる", "def": "to start doing something eagerly, often without preparing", "ex1": "Dive in, the food is ready.", "ja1": "さあ食べて、料理ができたよ。", "ex2": "Let's not dive in before we agree on the requirements.", "ja2": "要件が固まる前に着手するのはやめましょう。", "note": "", "nuance": "準備不足でも勢いよく始める、積極性のニュアンス。", "groups": ["dive_jump_in"], "etymology": "dive（飛び込む）＋in（中へ）\n→ 外から中に入る・参加や到着のイメージ\n→ そこから「勢いよく取りかかる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"rotate(8,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 251, "stage": 5, "verb": "cut off", "meaning": "遮断する、停止する", "def": "to stop a supply or disconnect something", "ex1": "The power was cut off during the storm.", "ja1": "嵐で電力が遮断された。", "ex2": "Their access was cut off after the contract ended.", "ja2": "契約終了後、アクセス権が停止された。", "note": "Stage 6 / 7 に別語義あり", "nuance": "供給を遮断する意味。Stage6・7に会話を遮る等の別義あり。", "groups": ["cut_off_senses"], "etymology": "cut（切る）＋off（離れて）\n→ くっついていた物が離れる・停止や出発のイメージ\n→ そこから「遮断する、停止する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"rotate(13,32,32)\"><circle cx=\"20\" cy=\"20\" r=\"4\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"20\" cy=\"44\" r=\"4\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M23 22 L48 44 M23 42 L48 20\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 252, "stage": 5, "verb": "miss out", "meaning": "（機会を）逃す", "def": "to lose a chance to do or have something", "ex1": "Don't miss out on the sale.", "ja1": "セールを逃さないで。", "ex2": "We missed out on the deal by one day.", "ja2": "1日の差で商談を逃した。", "note": "miss out on の形が多い", "nuance": "得られたはずの機会を逃す、後悔を伴う表現。", "groups": [], "etymology": "miss（逃す）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「（機会を）逃す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(7,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"14\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"32\" cy=\"32\" r=\"7\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"32\" cy=\"32\" r=\"2\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 253, "stage": 6, "verb": "sort out", "meaning": "整理する、解決する", "def": "to organize something; to resolve a problem", "ex1": "I need to sort out my closet.", "ja1": "クローゼットを整理しないといけない。", "ex2": "Let's sort out the billing issue first.", "ja2": "まず請求の問題を片づけましょう。", "note": "", "nuance": "混乱した状況を整理して解決する、問題解決のニュアンス。", "groups": ["organize"], "etymology": "sort（分類する）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「整理する、解決する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(13,32,32)\"><rect x=\"18\" y=\"38\" width=\"28\" height=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><rect x=\"20\" y=\"28\" width=\"24\" height=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><rect x=\"22\" y=\"18\" width=\"20\" height=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 254, "stage": 6, "verb": "break out", "meaning": "（火事・争いが）突然起こる", "def": "to start suddenly, usually of something bad", "ex1": "A fire broke out in the kitchen.", "ja1": "台所で火事が起きた。", "ex2": "A dispute broke out over the scope of work.", "ja2": "作業範囲をめぐって争いが起きた。", "note": "", "nuance": "火事や争いなどが突発的に発生する、緊急性を伴う表現。", "groups": [], "etymology": "break（壊す・分ける）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「（火事・争いが）突然起こる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"rotate(-2,32,32)\"><path d=\"M16 32 L26 32 L30 22 L36 42 L40 32 L48 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linejoin=\"round\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 255, "stage": 6, "verb": "look through", "meaning": "ざっと目を通す", "def": "to read or examine something quickly", "ex1": "I looked through the catalogue.", "ja1": "カタログにざっと目を通した。", "ex2": "Please look through the draft before the meeting.", "ja2": "会議の前に草案に目を通してください。", "note": "", "nuance": "資料などにざっと目を通す、詳細より概要把握を重視。", "groups": ["skim_review"], "etymology": "look（見る）＋through（通り抜けて）\n→ 最初から最後まで通り抜けるイメージ\n→ そこから「ざっと目を通す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-7,32,32)\"><path d=\"M14 32 Q32 16 50 32 Q32 48 14 32 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"32\" cy=\"32\" r=\"7\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-dasharray=\"3 2\"/><path d=\"M0 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 256, "stage": 6, "verb": "give off", "meaning": "（においや光・熱を）発する", "def": "to produce and send out a smell, light, or heat", "ex1": "The flowers give off a sweet smell.", "ja1": "その花は甘い香りを放つ。", "ex2": "The device gives off a lot of heat under load.", "ja2": "その機器は負荷時に多くの熱を発する。", "note": "", "nuance": "におい・光・熱などを自然に発する、物理的な放出。", "groups": [], "etymology": "give（与える）＋off（離れて）\n→ くっついていた物が離れる・停止や出発のイメージ\n→ そこから「（においや光・熱を）発する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#1B2A41\"/><g transform=\"rotate(8,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 257, "stage": 6, "verb": "pick through", "meaning": "丹念に選り分ける、調べる", "def": "to search carefully through a large number of things", "ex1": "She picked through the box of old photos.", "ja1": "彼女は古い写真の箱を丹念に見ていった。", "ex2": "We picked through the logs to find the error.", "ja2": "エラーを見つけるためログを丹念に調べた。", "note": "", "nuance": "大量の物を一つ一つ丹念に調べる、根気を要する作業。", "groups": [], "etymology": "pick（つまむ・選ぶ）＋through（通り抜けて）\n→ 最初から最後まで通り抜けるイメージ\n→ そこから「丹念に選り分ける、調べる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#8A4B8A\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(9,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-dasharray=\"3 2\"/><path d=\"M0 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 258, "stage": 6, "verb": "wear out", "meaning": "すり減る／疲れ果てさせる", "def": "to become unusable through use; to exhaust someone", "ex1": "My shoes wore out after a year.", "ja1": "靴が1年で履きつぶれた。", "ex2": "The long negotiation wore out the team.", "ja2": "長い交渉でチームは疲れ果てた。", "note": "", "nuance": "使用によりすり減る意味と、人を疲れさせる意味の両方。", "groups": ["break_malfunction"], "etymology": "wear（身につける・すり減らす）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「すり減る／疲れ果てさせる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#1B2A41\"/><g transform=\"rotate(-10,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"16\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"27\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><circle cx=\"37\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><path d=\"M26 38 Q32 42 38 38\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 259, "stage": 6, "verb": "fill out", "meaning": "（書類に）記入する", "def": "to complete a form by writing information in it", "ex1": "Fill out the application form.", "ja1": "申込書に記入してください。", "ex2": "Please fill out the survey after the training.", "ja2": "研修後にアンケートに記入してください。", "note": "fill in とほぼ同義。米では fill out が一般的", "nuance": "書類の空欄を記入する、fill inとほぼ同義でやや米語的。", "groups": ["fill_form"], "etymology": "fill（満たす）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「（書類に）記入する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"rotate(-12,32,32)\"><path d=\"M32 14 Q44 30 44 38 Q44 48 32 48 Q20 48 20 38 Q20 30 32 14 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 260, "stage": 6, "verb": "break off", "meaning": "中断する、打ち切る", "def": "to stop suddenly; to end a relationship or talks", "ex1": "He broke off in the middle of the sentence.", "ja1": "彼は文の途中で言葉を切った。", "ex2": "The two companies broke off negotiations.", "ja2": "2社は交渉を打ち切った。", "note": "", "nuance": "話や交渉を途中で打ち切る、中断のニュアンス。", "groups": ["cancel_stop"], "etymology": "break（壊す・分ける）＋off（離れて）\n→ くっついていた物が離れる・停止や出発のイメージ\n→ そこから「中断する、打ち切る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#9A5B2E\"/><g transform=\"rotate(4,32,32)\"><path d=\"M16 32 L26 32 L30 22 L36 42 L40 32 L48 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linejoin=\"round\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 261, "stage": 6, "verb": "pass off", "meaning": "（偽って）通す、〜として通用させる", "def": "to falsely present something as something else", "ex1": "He passed off the copy as an original.", "ja1": "彼は複製を本物と偽った。", "ex2": "Don't pass off an estimate as a firm quotation.", "ja2": "概算を確定見積もりとして通さないでください。", "note": "pass A off as B の形", "nuance": "偽物を本物として通用させる、欺瞞的な表現。", "groups": ["pretend_pass_off"], "etymology": "pass（通す・渡す）＋off（離れて）\n→ くっついていた物が離れる・停止や出発のイメージ\n→ そこから「（偽って）通す、〜として通用させる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-6,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 262, "stage": 6, "verb": "make out*3", "meaning": "〜であるかのように言う、主張する", "def": "to claim or suggest that something is true", "ex1": "He made out that he knew nothing.", "ja1": "彼は何も知らないかのように言った。", "ex2": "The vendor made out that the delay was our fault.", "ja2": "その業者は遅延が我々のせいだと主張した。", "note": "Stage 4 の make out*2 と区別", "nuance": "見分ける・うまくやるとは別に、事実でないことを主張する意味。", "groups": ["pretend_pass_off"], "etymology": "make（作る）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「〜であるかのように言う、主張する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"rotate(12,32,32)\"><rect x=\"18\" y=\"34\" width=\"10\" height=\"12\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><rect x=\"28\" y=\"26\" width=\"10\" height=\"20\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><rect x=\"38\" y=\"18\" width=\"10\" height=\"28\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 263, "stage": 6, "verb": "come on to", "meaning": "言い寄る", "def": "to show sexual interest in someone", "ex1": "He came on to her at the party.", "ja1": "彼はパーティーで彼女に言い寄った。", "ex2": "Coming on to a colleague can be harassment.", "ja2": "同僚に言い寄る行為はハラスメントになりうる。", "note": "", "nuance": "性的な意味合いで言い寄る、注意を要する表現。", "groups": ["dating_romance"], "etymology": "come（来る）＋to（～へ）\n→ 目的地・相手に向かうイメージ\n→ そこから「言い寄る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#8A4B8A\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(14,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L12 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><circle cx=\"14\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/></g></svg>"}, {"no": 264, "stage": 6, "verb": "come off", "meaning": "取れる、外れる／うまくいく", "def": "to become detached; to succeed as planned", "ex1": "The button came off my coat.", "ja1": "コートのボタンが取れた。", "ex2": "The event came off better than expected.", "ja2": "イベントは予想以上にうまくいった。", "note": "", "nuance": "取れる意味と、うまくいく意味の両方を持つ。", "groups": ["succeed"], "etymology": "come（来る）＋off（離れて）\n→ くっついていた物が離れる・停止や出発のイメージ\n→ そこから「取れる、外れる／うまくいく」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"rotate(-14,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 265, "stage": 6, "verb": "throw in", "meaning": "おまけに付ける", "def": "to add something extra without charging for it", "ex1": "They threw in a free case with the phone.", "ja1": "スマホに無料でケースを付けてくれた。", "ex2": "We threw in three months of support at no charge.", "ja2": "3か月分のサポートを無償で付けた。", "note": "", "nuance": "おまけとして無料で付け加える、サービス精神を表す。", "groups": [], "etymology": "throw（投げる）＋in（中へ）\n→ 外から中に入る・参加や到着のイメージ\n→ そこから「おまけに付ける」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#1B2A41\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(0,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 266, "stage": 6, "verb": "deal with", "meaning": "対処する、扱う", "def": "to take action about a problem or person", "ex1": "I'll deal with it tomorrow.", "ja1": "明日それに対処します。", "ex2": "She deals with customer complaints.", "ja2": "彼女は顧客からの苦情に対応している。", "note": "", "nuance": "問題や人に対処する、ビジネスで頻出の中立的表現。", "groups": [], "etymology": "deal（扱う）＋with（一緒に）\n→ 対象と一緒に行動するイメージ\n→ そこから「対処する、扱う」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#9A5B2E\"/><g transform=\"rotate(12,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 2 L8 14 M2 8 L14 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 267, "stage": 6, "verb": "come down with", "meaning": "（病気に）かかる", "def": "to become ill with a particular illness", "ex1": "I came down with a cold.", "ja1": "風邪をひいた。", "ex2": "Two members came down with the flu before the release.", "ja2": "リリース前にメンバー2名がインフルエンザにかかった。", "note": "", "nuance": "病気にかかる、体調不良の発症を表す。", "groups": [], "etymology": "come（来る）＋with（一緒に）\n→ 対象と一緒に行動するイメージ\n→ そこから「（病気に）かかる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"rotate(3,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 2 L8 14 M2 8 L14 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 268, "stage": 6, "verb": "hop on", "meaning": "ひょいと乗る、（会議に）参加する", "def": "to get on something quickly; to join a call", "ex1": "Hop on my bike.", "ja1": "私の自転車に乗って。", "ex2": "Can you hop on the call for five minutes?", "ja2": "5分ほど電話会議に入ってもらえますか。", "note": "オンライン会議に「入る」意味でもよく使う", "nuance": "自転車などにひょいと乗る、または通話に加わる意味。", "groups": ["board_vehicle"], "etymology": "hop（ぴょんと跳ぶ）＋on（接触・継続）\n→ くっついたまま続く・作動し続けるイメージ\n→ そこから「ひょいと乗る、（会議に）参加する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#2E6B4F\"/><g transform=\"rotate(0,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 269, "stage": 6, "verb": "drop off", "meaning": "送り届ける／（数量が）減る", "def": "to deliver someone or something; to decrease", "ex1": "I'll drop you off at the station.", "ja1": "駅まで送ります。", "ex2": "Inquiries dropped off after the campaign ended.", "ja2": "キャンペーン終了後に問い合わせが減った。", "note": "", "nuance": "人を車で送り届ける意味と、数量が減少する意味がある。", "groups": [], "etymology": "drop（ポトリと落ちる）＋off（離れて）\n→ くっついていた物が離れる・停止や出発のイメージ\n→ そこから「送り届ける／（数量が）減る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-12,32,32)\"><path d=\"M32 14 Q44 30 44 38 Q44 48 32 48 Q20 48 20 38 Q20 30 32 14 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 270, "stage": 6, "verb": "go along with", "meaning": "同意する、（方針に）従う", "def": "to agree with a plan, idea, or person", "ex1": "I'll go along with your idea.", "ja1": "あなたの案に賛成します。", "ex2": "We went along with the client's schedule.", "ja2": "我々は顧客のスケジュールに合わせた。", "note": "", "nuance": "他人の計画や意見に同調する、協調的な表現。", "groups": ["comply_defy"], "etymology": "go（行く）＋with（一緒に）\n→ 対象と一緒に行動するイメージ\n→ そこから「同意する、（方針に）従う」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#1B2A41\"/><g transform=\"rotate(8,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 2 L8 14 M2 8 L14 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 271, "stage": 6, "verb": "go against", "meaning": "反する、逆らう", "def": "to oppose or conflict with something", "ex1": "It goes against my principles.", "ja1": "それは私の信条に反する。", "ex2": "This approach goes against our security policy.", "ja2": "この方法は当社のセキュリティ方針に反する。", "note": "", "nuance": "自分の方針や規則に反する、対立のニュアンス。", "groups": ["comply_defy"], "etymology": "go（行く）＋against（逆らって）\n→ 向かい合って押し返す・反対するイメージ\n→ そこから「反する、逆らう」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#8A4B8A\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(4,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L10 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><path d=\"M13 2 L13 14\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 272, "stage": 6, "verb": "get out of", "meaning": "逃れる、免れる", "def": "to avoid a duty or an obligation", "ex1": "He got out of doing the dishes.", "ja1": "彼は皿洗いを免れた。", "ex2": "We can't get out of the contract without a penalty.", "ja2": "違約金なしに契約から抜けることはできない。", "note": "", "nuance": "義務や責任を回避する、逃れるという行為。", "groups": ["avoid_evade"], "etymology": "get（得る・～になる）＋of（～の）\n→ 対象を分離・限定するイメージ\n→ そこから「逃れる、免れる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#2E6B4F\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-7,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M4 4 L12 12 M4 12 L12 4\" stroke=\"#B5392F\" stroke-width=\"1.8\" stroke-linecap=\"round\" opacity=\"0.7\"/></g></svg>"}, {"no": 273, "stage": 6, "verb": "get at", "meaning": "言おうとする、ほのめかす", "def": "to try to express or suggest something", "ex1": "What are you getting at?", "ja1": "何が言いたいのですか。", "ex2": "I see what you're getting at about the risk.", "ja2": "リスクについておっしゃりたいことは分かります。", "note": "", "nuance": "遠回しに言おうとしていることを表す、意図の推測。", "groups": [], "etymology": "get（得る・～になる）＋at（～めがけて）\n→ ピンポイントで対象を狙うイメージ\n→ そこから「言おうとする、ほのめかす」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#9A5B2E\"/><g transform=\"rotate(-15,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 274, "stage": 6, "verb": "step back", "meaning": "一歩引いて考える", "def": "to pause and look at a situation from a distance", "ex1": "Let's step back and think.", "ja1": "一歩引いて考えよう。", "ex2": "Let's step back and revisit the original goal.", "ja2": "一度立ち返って当初の目的を見直しましょう。", "note": "", "nuance": "一歩下がって状況を客観視する、冷静な視点。", "groups": ["reflect_step_back"], "etymology": "step（一歩踏み出す）＋back（後ろ・元へ）\n→ 元の場所や状態に戻るイメージ\n→ そこから「一歩引いて考える」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"rotate(-11,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M14 4 Q4 4 4 12 M4 12 L0 9 M4 12 L8 12\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 275, "stage": 6, "verb": "play along", "meaning": "話を合わせる", "def": "to pretend to agree in order to avoid trouble", "ex1": "Just play along for now.", "ja1": "今は話を合わせておいて。", "ex2": "I played along until we had the full picture.", "ja2": "全体像がつかめるまで話を合わせておいた。", "note": "", "nuance": "本心では違っても話を合わせる、その場しのぎの同調。", "groups": ["pretend_pass_off"], "etymology": "play（遊ぶ・演じる）＋along（沿って）\n→ 一緒に・並んで進むイメージ\n→ そこから「話を合わせる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(3,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"16\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"27\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><circle cx=\"37\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><path d=\"M26 38 Q32 42 38 38\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 5 L16 5 M0 11 L16 11\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 276, "stage": 6, "verb": "take back to", "meaning": "（元の場所へ）返しに行く、連れ戻す", "def": "to return someone or something to a place", "ex1": "Take the DVD back to the store.", "ja1": "DVDを店に返しに行って。", "ex2": "Please take these documents back to the client.", "ja2": "この書類を顧客に返却してきてください。", "note": "", "nuance": "元の場所へ返しに連れて行く、または戻す動作。", "groups": ["return"], "etymology": "take（取る）＋to（～へ）\n→ 目的地・相手に向かうイメージ\n→ そこから「（元の場所へ）返しに行く、連れ戻す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#2E6B4F\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(2,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L12 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><circle cx=\"14\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/></g></svg>"}, {"no": 277, "stage": 6, "verb": "bump into", "meaning": "偶然出会う", "def": "to meet someone by chance", "ex1": "I bumped into my teacher at the mall.", "ja1": "モールで先生に偶然会った。", "ex2": "I bumped into our old client at the conference.", "ja2": "カンファレンスで昔の顧客に偶然会った。", "note": "run into とほぼ同義", "nuance": "人に偶然出くわす、run intoとほぼ同義。", "groups": ["encounter"], "etymology": "bump（ぶつかる）＋into（中へ変化）\n→ ある状態の中に入り込む・変化を伴うイメージ\n→ そこから「偶然出会う」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#8A4B8A\"/><g transform=\"rotate(-1,32,32)\"><path d=\"M16 32 L26 32 L30 22 L36 42 L40 32 L48 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linejoin=\"round\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 278, "stage": 6, "verb": "count on", "meaning": "頼りにする、当てにする", "def": "to rely on someone or something", "ex1": "You can count on me.", "ja1": "私に任せてください。", "ex2": "We're counting on the vendor to deliver by Friday.", "ja2": "金曜までの納品を業者に期待しています。", "note": "", "nuance": "人や物を頼りにする、信頼して依存する表現。", "groups": ["rely_on"], "etymology": "count（数える）＋on（接触・継続）\n→ くっついたまま続く・作動し続けるイメージ\n→ そこから「頼りにする、当てにする」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#1B2A41\"/><g transform=\"rotate(0,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"14\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M28 26 L36 26 M28 32 L36 32 M28 38 L36 38\" stroke=\"#C79A3D\" stroke-width=\"2\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 279, "stage": 6, "verb": "hear from", "meaning": "〜から連絡をもらう", "def": "to receive news or a message from someone", "ex1": "I haven't heard from her lately.", "ja1": "最近彼女から連絡がない。", "ex2": "We haven't heard from the client since Tuesday.", "ja2": "火曜以降、顧客から連絡がありません。", "note": "", "nuance": "誰かから連絡や便りをもらう、待ち望むニュアンスも。", "groups": ["contact_related"], "etymology": "hear（聞く）＋from（～から）\n→ ある地点から離れるイメージ\n→ そこから「〜から連絡をもらう」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"rotate(11,32,32)\"><path d=\"M32 16 Q22 16 22 28 L22 38 L18 44 L46 44 L42 38 L42 28 Q42 16 32 16 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M28 44 Q28 48 32 48 Q36 48 36 44\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"2\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/><path d=\"M4 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 280, "stage": 6, "verb": "throw up", "meaning": "吐く", "def": "to vomit", "ex1": "He threw up after the ride.", "ja1": "彼は乗り物に乗った後に吐いた。", "ex2": "One participant threw up and left the training early.", "ja2": "参加者1名が体調を崩し研修を早退した。", "note": "", "nuance": "嘔吐する、体調に関する直接的な表現。", "groups": [], "etymology": "throw（投げる）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「吐く」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(2,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 281, "stage": 6, "verb": "get back at", "meaning": "仕返しをする", "def": "to take revenge on someone", "ex1": "She wanted to get back at him.", "ja1": "彼女は彼に仕返ししたかった。", "ex2": "Getting back at a colleague never helps the team.", "ja2": "同僚に仕返ししてもチームのためにならない。", "note": "", "nuance": "仕返しをする、報復的で否定的なニュアンス。", "groups": ["revenge_group"], "etymology": "get（得る・～になる）＋at（～めがけて）\n→ ピンポイントで対象を狙うイメージ\n→ そこから「仕返しをする」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#1B2A41\"/><g transform=\"rotate(14,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 282, "stage": 6, "verb": "start off", "meaning": "まず〜から始める", "def": "to begin something in a particular way", "ex1": "Let's start off with a warm-up.", "ja1": "まず準備運動から始めよう。", "ex2": "Let's start off with a review of last week's actions.", "ja2": "先週の宿題の確認から始めましょう。", "note": "", "nuance": "特定の方法や内容で物事を始める、開始の切り口。", "groups": ["begin"], "etymology": "start（始める）＋off（離れて）\n→ くっついていた物が離れる・停止や出発のイメージ\n→ そこから「まず〜から始める」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#9A5B2E\"/><g transform=\"rotate(-2,32,32)\"><circle cx=\"32\" cy=\"26\" r=\"12\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M26 38 L38 38 M28 44 L36 44\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 283, "stage": 6, "verb": "check in with", "meaning": "（人に）状況を確認する、連絡を取る", "def": "to contact someone to see how things are going", "ex1": "Check in with your mother when you arrive.", "ja1": "着いたらお母さんに連絡して。", "ex2": "I'll check in with the team before the deadline.", "ja2": "締切前にチームの状況を確認します。", "note": "", "nuance": "相手の状況を確認する、気遣いを伴う連絡。", "groups": ["contact_related"], "etymology": "check（確認する）＋with（一緒に）\n→ 対象と一緒に行動するイメージ\n→ そこから「（人に）状況を確認する、連絡を取る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-15,32,32)\"><path d=\"M32 20 Q24 14 16 18 L16 44 Q24 40 32 46 Q40 40 48 44 L48 18 Q40 14 32 20 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 2 L8 14 M2 8 L14 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 284, "stage": 6, "verb": "fall apart", "meaning": "ばらばらになる、崩壊する", "def": "to break into pieces; to fail completely", "ex1": "The old book fell apart.", "ja1": "古い本がばらばらになった。", "ex2": "The plan fell apart when the budget was cut.", "ja2": "予算が削られて計画は崩れた。", "note": "", "nuance": "計画や関係が崩壊する、失敗のニュアンス。", "groups": ["break_up_apart"], "etymology": "fall（落ちる）＋apart（ばらばらに）\n→ 一つだった物が分かれていくイメージ\n→ そこから「ばらばらになる、崩壊する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#9A5B2E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-1,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 2 L0 8 L8 14 M8 2 L16 8 L8 14\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 285, "stage": 6, "verb": "pull up", "meaning": "（車が）止まる、止める", "def": "to stop a vehicle", "ex1": "A taxi pulled up in front of the house.", "ja1": "タクシーが家の前に止まった。", "ex2": "The shuttle pulled up at the main entrance.", "ja2": "送迎車が正面玄関に止まった。", "note": "Stage 7 / 8 に別語義あり", "nuance": "車が停止する意味。Stage7・8に別の比喩的意味あり。", "groups": ["pull_over_stop_car"], "etymology": "pull（引く）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「（車が）止まる、止める」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#9A5B2E\"/><g transform=\"rotate(0,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 286, "stage": 6, "verb": "pick up*4", "meaning": "（電話に）出る", "def": "to answer the telephone", "ex1": "Nobody picked up.", "ja1": "誰も電話に出なかった。", "ex2": "Please pick up if the client calls.", "ja2": "顧客から電話があったら出てください。", "note": "Stage 2 / 3 / 5 に別語義あり", "nuance": "電話に出る、pick upの新たな用法。", "groups": ["pick_up_senses"], "etymology": "pick（つまむ・選ぶ）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「（電話に）出る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-10,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 287, "stage": 6, "verb": "follow through", "meaning": "最後までやり遂げる", "def": "to complete something you started or promised", "ex1": "He never follows through on his plans.", "ja1": "彼は計画を最後までやり遂げない。", "ex2": "We need to follow through on the action items.", "ja2": "アクション項目を最後までやり切る必要がある。", "note": "", "nuance": "始めたことを最後までやり遂げる、責任感のある表現。", "groups": ["accomplish_through"], "etymology": "follow（従う）＋through（通り抜けて）\n→ 最初から最後まで通り抜けるイメージ\n→ そこから「最後までやり遂げる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-3,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-dasharray=\"3 2\"/><path d=\"M0 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 288, "stage": 6, "verb": "settle in", "meaning": "（新しい環境に）慣れる", "def": "to become comfortable in a new place or job", "ex1": "It took a month to settle in.", "ja1": "慣れるのに1か月かかった。", "ex2": "The new hire is settling in well.", "ja2": "新入社員はうまく職場になじんでいる。", "note": "", "nuance": "新しい環境に慣れて落ち着く、適応のプロセス。", "groups": ["adapt_fit_in"], "etymology": "settle（落ち着かせる）＋in（中へ）\n→ 外から中に入る・参加や到着のイメージ\n→ そこから「（新しい環境に）慣れる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#8A4B8A\"/><g transform=\"rotate(-5,32,32)\"><path d=\"M22 20 L22 44 L42 44 L42 30 M22 32 L42 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M22 44 L20 50 M42 44 L44 50\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 289, "stage": 6, "verb": "take out on", "meaning": "八つ当たりする", "def": "to direct your anger at someone who is not responsible", "ex1": "Don't take it out on me.", "ja1": "私に八つ当たりしないで。", "ex2": "Don't take the client's pressure out on your team.", "ja2": "顧客からの圧力をチームに八つ当たりしないでください。", "note": "take it out on someone の形", "nuance": "無関係な人に怒りをぶつける、八つ当たりの否定的表現。", "groups": ["revenge_group"], "etymology": "take（取る）＋on（接触・継続）\n→ くっついたまま続く・作動し続けるイメージ\n→ そこから「八つ当たりする」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#9A5B2E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(6,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 290, "stage": 6, "verb": "sign off", "meaning": "承認する／（作業を）終える", "def": "to give final approval; to finish for the day", "ex1": "I'm signing off for the night.", "ja1": "今夜はこれで終わりにします。", "ex2": "The client signed off on the design document.", "ja2": "顧客が設計書を承認した。", "note": "承認の意味では sign off on", "nuance": "承認する意味と、その日の作業を終える意味がある。", "groups": [], "etymology": "sign（署名する）＋off（離れて）\n→ くっついていた物が離れる・停止や出発のイメージ\n→ そこから「承認する／（作業を）終える」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(12,32,32)\"><path d=\"M20 44 L38 26 L44 32 L26 50 L18 50 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linejoin=\"round\"/><path d=\"M38 26 L42 22\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 291, "stage": 6, "verb": "talk over", "meaning": "じっくり話し合う", "def": "to discuss something thoroughly", "ex1": "Let's talk it over at dinner.", "ja1": "夕食のときにじっくり話そう。", "ex2": "Let's talk over the options before deciding.", "ja2": "決める前に選択肢をじっくり話し合いましょう。", "note": "", "nuance": "時間をかけてじっくり話し合う、熟考を伴う対話。", "groups": ["discuss_thoroughly"], "etymology": "talk（話す）＋over（越えて）\n→ 何かを越えて広がる・一通り目を通すイメージ\n→ そこから「じっくり話し合う」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#8A4B8A\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-10,32,32)\"><path d=\"M14 20 Q14 16 18 16 L46 16 Q50 16 50 20 L50 36 Q50 40 46 40 L26 40 L18 48 L20 40 L18 40 Q14 40 14 36 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 2 A6 6 0 1 1 2 8\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2.2\"/><path d=\"M2 8 L0 4 M2 8 L6 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 292, "stage": 6, "verb": "catch out", "meaning": "見破る、ぼろを出させる", "def": "to discover that someone is lying or mistaken", "ex1": "He was caught out lying.", "ja1": "彼は嘘を見破られた。", "ex2": "The audit caught out several errors in the records.", "ja2": "監査で記録の誤りがいくつか露見した。", "note": "", "nuance": "嘘や誤りを見破る、真実を暴くニュアンス。", "groups": [], "etymology": "catch（捕まえる）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「見破る、ぼろを出させる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#8A4B8A\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-4,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 293, "stage": 6, "verb": "eat up", "meaning": "平らげる／（時間・資源を）食う", "def": "to eat all of something; to consume a lot of resources", "ex1": "Eat up your vegetables.", "ja1": "野菜を全部食べなさい。", "ex2": "Meetings eat up half of my week.", "ja2": "会議が週の半分を食いつぶしている。", "note": "", "nuance": "食べ尽くす意味と、時間や資源を消費する比喩の意味。", "groups": ["spend_time_effort"], "etymology": "eat（食べる）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「平らげる／（時間・資源を）食う」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#9A5B2E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-14,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"16\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"27\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><circle cx=\"37\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><path d=\"M26 38 Q32 42 38 38\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 294, "stage": 6, "verb": "call out", "meaning": "大声で呼ぶ／公然と批判する", "def": "to shout to get attention; to criticize someone publicly", "ex1": "She called out my name.", "ja1": "彼女は私の名前を大声で呼んだ。", "ex2": "He called out the vendor for missing the deadline.", "ja2": "彼は納期を守らなかった業者を公然と批判した。", "note": "Stage 7 に別語義あり", "nuance": "大声で呼ぶ意味と、公然と批判する意味の両方。", "groups": ["speak_loudly"], "etymology": "call（呼ぶ）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「大声で呼ぶ／公然と批判する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"rotate(7,32,32)\"><path d=\"M32 16 Q22 16 22 28 L22 38 L18 44 L46 44 L42 38 L42 28 Q42 16 32 16 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M28 44 Q28 48 32 48 Q36 48 36 44\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 295, "stage": 6, "verb": "check out*3", "meaning": "確認が取れる、裏が取れる", "def": "to be found to be correct or true after checking", "ex1": "His story checks out.", "ja1": "彼の話は裏が取れている。", "ex2": "The figures check out against the invoice.", "ja2": "数値は請求書と一致している。", "note": "Stage 2 / 3 に別語義あり", "nuance": "事実が確認できる、裏付けが取れるという意味。", "groups": ["confirm_check"], "etymology": "check（確認する）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「確認が取れる、裏が取れる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#1B2A41\"/><g transform=\"rotate(1,32,32)\"><path d=\"M32 20 Q24 14 16 18 L16 44 Q24 40 32 46 Q40 40 48 44 L48 18 Q40 14 32 20 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 296, "stage": 6, "verb": "talk down", "meaning": "見下した話し方をする", "def": "to speak to someone as if they were less intelligent", "ex1": "Don't talk down to your students.", "ja1": "生徒を見下した話し方をしないで。", "ex2": "He tends to talk down to junior members.", "ja2": "彼は若手を見下した話し方をしがちだ。", "note": "talk down to someone の形", "nuance": "相手を見下すような話し方をする、否定的な態度。", "groups": [], "etymology": "talk（話す）＋down（下へ）\n→ 下向き・減少や書き留めるイメージ\n→ そこから「見下した話し方をする」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(6,32,32)\"><path d=\"M14 20 Q14 16 18 16 L46 16 Q50 16 50 20 L50 36 Q50 40 46 40 L26 40 L18 48 L20 40 L18 40 Q14 40 14 36 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 16 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 297, "stage": 6, "verb": "hit up", "meaning": "連絡を取る、頼む", "def": "to contact someone, often to ask for something", "ex1": "Hit me up when you're free.", "ja1": "暇なとき連絡して。", "ex2": "Hit up the support team if the error repeats.", "ja2": "エラーが再発したらサポートチームに連絡してください。", "note": "くだけた表現。社外にはやや不向き", "nuance": "気軽に連絡を取る、カジュアルな表現。", "groups": ["call_phone"], "etymology": "hit（打つ）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「連絡を取る、頼む」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#8A4B8A\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(9,32,32)\"><path d=\"M16 32 L26 32 L30 22 L36 42 L40 32 L48 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linejoin=\"round\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 298, "stage": 6, "verb": "get behind*2", "meaning": "支持する、後押しする", "def": "to support a person, plan, or campaign", "ex1": "The whole town got behind the campaign.", "ja1": "町全体がその運動を支持した。", "ex2": "Management got behind the new initiative.", "ja2": "経営陣は新しい取り組みを後押しした。", "note": "Stage 1 の get behind（遅れる）と区別", "nuance": "遅れる（Stage1）とは別に、人や計画を支持する意味。", "groups": ["cheer_encourage"], "etymology": "get（得る・～になる）＋behind（後ろに）\n→ 後方に取り残されるイメージ\n→ そこから「支持する、後押しする」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-2,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M3 3 L3 13 M6 3 L6 13\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 299, "stage": 6, "verb": "take off*2", "meaning": "離陸する／（売上などが）急伸する", "def": "to leave the ground; to grow very quickly", "ex1": "The plane took off on time.", "ja1": "飛行機は定刻に離陸した。", "ex2": "Sales took off after the product launch.", "ja2": "製品発売後、売上が急伸した。", "note": "Stage 1 の take off（脱ぐ）と区別", "nuance": "脱ぐ（Stage1）とは別に、離陸する・急成長する意味。", "groups": ["gain_popularity"], "etymology": "take（取る）＋off（離れて）\n→ くっついていた物が離れる・停止や出発のイメージ\n→ そこから「離陸する／（売上などが）急伸する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"rotate(0,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 300, "stage": 6, "verb": "come across as", "meaning": "〜という印象を与える", "def": "to give a particular impression to others", "ex1": "He comes across as shy.", "ja1": "彼は内気な印象を与える。", "ex2": "The email came across as too aggressive.", "ja2": "そのメールは強すぎる印象を与えた。", "note": "Stage 5 の come across（偶然見つける）と区別", "nuance": "他人にどんな印象を与えるかを表す表現。", "groups": ["impression"], "etymology": "come（来る）＋across（横切って）\n→ ある空間や境界を横切って向こう側に届くイメージ\n→ そこから「〜という印象を与える」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-2,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M2 2 L14 14\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><path d=\"M2 14 L14 2\" stroke=\"#B5392F\" stroke-width=\"1.4\" opacity=\"0.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 301, "stage": 6, "verb": "turn in*2", "meaning": "（犯人を）引き渡す、通報する", "def": "to hand someone over to the authorities", "ex1": "He turned himself in to the police.", "ja1": "彼は警察に自首した。", "ex2": "The company turned in the employee for fraud.", "ja2": "会社は不正を行った社員を通報した。", "note": "Stage 2 の turn in（提出する）と区別", "nuance": "提出（Stage2）とは別に、犯人を当局に引き渡す意味。", "groups": ["hand_over"], "etymology": "turn（向きを変える）＋in（中へ）\n→ 外から中に入る・参加や到着のイメージ\n→ そこから「（犯人を）引き渡す、通報する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#1B2A41\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-11,32,32)\"><path d=\"M32 32 m-4,0 a4,4 0 1,0 8,0 a8,8 0 1,0 -16,0 a12,12 0 1,0 24,0 a16,16 0 1,0 -32,0\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 302, "stage": 6, "verb": "mess up", "meaning": "台無しにする、しくじる", "def": "to spoil something or make a serious mistake", "ex1": "I messed up the recipe.", "ja1": "レシピを台無しにした。", "ex2": "I messed up the version number in the release note.", "ja2": "リリースノートの版番号を間違えた。", "note": "", "nuance": "物事を台無しにする、しくじりのニュアンス。", "groups": ["mess_disrupt"], "etymology": "mess（ごちゃごちゃにする）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「台無しにする、しくじる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#1B2A41\"/><g transform=\"rotate(-3,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"12\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-dasharray=\"4 3\"/><circle cx=\"32\" cy=\"20\" r=\"3\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 303, "stage": 7, "verb": "feel out", "meaning": "探りを入れる", "def": "to try to discover someone's opinion indirectly", "ex1": "I'll feel her out about the plan.", "ja1": "計画について彼女に探りを入れてみる。", "ex2": "Let's feel out the client on budget before proposing.", "ja2": "提案の前に顧客の予算感に探りを入れましょう。", "note": "", "nuance": "遠回しに相手の意向を探る、慎重なニュアンス。", "groups": ["probe_sniff"], "etymology": "feel（感じる）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「探りを入れる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#2E6B4F\"/><g transform=\"rotate(-2,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 304, "stage": 7, "verb": "relate to", "meaning": "共感する、理解できる", "def": "to understand and identify with someone or something", "ex1": "I can relate to how you feel.", "ja1": "あなたの気持ちは分かります。", "ex2": "Customers relate to case studies more than specifications.", "ja2": "顧客は仕様よりも事例に共感する。", "note": "", "nuance": "経験や感情に共感する、理解を示す表現。", "groups": [], "etymology": "relate（関連づける）＋to（～へ）\n→ 目的地・相手に向かうイメージ\n→ そこから「共感する、理解できる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(6,32,32)\"><circle cx=\"24\" cy=\"32\" r=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"40\" cy=\"32\" r=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L12 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><circle cx=\"14\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/></g></svg>"}, {"no": 305, "stage": 7, "verb": "bum out", "meaning": "がっかりさせる", "def": "to make someone feel sad or disappointed", "ex1": "The news really bummed me out.", "ja1": "その知らせには本当にがっかりした。", "ex2": "The postponement bummed out the whole team.", "ja2": "延期にチーム全体ががっかりした。", "note": "くだけた表現", "nuance": "がっかりさせる、落胆させるカジュアルな表現。", "groups": [], "etymology": "bum（物乞いする）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「がっかりさせる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#8A4B8A\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(2,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 306, "stage": 7, "verb": "push back*2", "meaning": "（予定を）後ろ倒しにする", "def": "to move something to a later time", "ex1": "Let's push back dinner by an hour.", "ja1": "夕食を1時間後ろ倒しにしよう。", "ex2": "We pushed back the release to next month.", "ja2": "リリースを翌月に延期した。", "note": "Stage 4 の push back（反発する）と区別", "nuance": "反発する（Stage4）とは別に、予定を後ろ倒しにする意味。", "groups": ["postpone"], "etymology": "push（押す）＋back（後ろ・元へ）\n→ 元の場所や状態に戻るイメージ\n→ そこから「（予定を）後ろ倒しにする」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-2,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M14 4 Q4 4 4 12 M4 12 L0 9 M4 12 L8 12\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 307, "stage": 7, "verb": "jump in", "meaning": "途中から加わる、口を挟む", "def": "to join a conversation or activity suddenly", "ex1": "Feel free to jump in.", "ja1": "いつでも口を挟んでください。", "ex2": "Jump in if I miss anything in the explanation.", "ja2": "説明に漏れがあれば口を挟んでください。", "note": "", "nuance": "会話や活動に急に加わる、積極的な参加。", "groups": ["dive_jump_in"], "etymology": "jump（跳ぶ）＋in（中へ）\n→ 外から中に入る・参加や到着のイメージ\n→ そこから「途中から加わる、口を挟む」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"rotate(-15,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 308, "stage": 7, "verb": "butt in", "meaning": "話に割り込む", "def": "to interrupt rudely", "ex1": "Don't butt in when I'm talking.", "ja1": "話しているときに割り込まないで。", "ex2": "He butted in while the client was explaining.", "ja2": "顧客の説明中に彼が割り込んだ。", "note": "jump in より否定的な語感", "nuance": "無礼に話に割り込む、jump inより否定的な響き。", "groups": ["interrupt"], "etymology": "butt（頭突きする）＋in（中へ）\n→ 外から中に入る・参加や到着のイメージ\n→ そこから「話に割り込む」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#8A4B8A\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(12,32,32)\"><path d=\"M16 32 L26 32 L30 22 L36 42 L40 32 L48 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linejoin=\"round\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 309, "stage": 7, "verb": "call out*2", "meaning": "呼び出す、招集する", "def": "to summon someone, especially to deal with a problem", "ex1": "They called out a plumber at midnight.", "ja1": "深夜に配管工を呼んだ。", "ex2": "We called out the on-call engineer for the incident.", "ja2": "障害対応でオンコール担当を呼び出した。", "note": "Stage 6 の call out と区別", "nuance": "呼ぶ（Stage6）とは別に、緊急時に人を呼び出す意味。", "groups": ["speak_loudly"], "etymology": "call（呼ぶ）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「呼び出す、招集する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"rotate(7,32,32)\"><path d=\"M32 16 Q22 16 22 28 L22 38 L18 44 L46 44 L42 38 L42 28 Q42 16 32 16 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M28 44 Q28 48 32 48 Q36 48 36 44\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 310, "stage": 7, "verb": "freak out", "meaning": "パニックになる、取り乱す", "def": "to become very anxious, upset, or afraid", "ex1": "She freaked out when she lost her passport.", "ja1": "パスポートをなくして彼女は取り乱した。", "ex2": "Don't freak out; we have a rollback plan.", "ja2": "慌てないでください、切り戻し手順があります。", "note": "", "nuance": "強い不安やパニックに陥る、感情の高まりを表す。", "groups": [], "etymology": "freak（ひどく興奮する）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「パニックになる、取り乱す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"rotate(-10,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"16\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"27\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><circle cx=\"37\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><path d=\"M26 38 Q32 42 38 38\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 311, "stage": 7, "verb": "fall for", "meaning": "恋に落ちる／だまされる", "def": "to fall in love with someone; to be deceived by a trick", "ex1": "He fell for her immediately.", "ja1": "彼はすぐ彼女に恋をした。", "ex2": "Several staff fell for the phishing email.", "ja2": "何人かの社員がフィッシングメールにだまされた。", "note": "", "nuance": "恋に落ちる意味と、だまされる意味の両方。", "groups": ["deceive"], "etymology": "fall（落ちる）＋for（求めて）\n→ 目的物を求めて手を伸ばすイメージ\n→ そこから「恋に落ちる／だまされる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#2E6B4F\"/><g transform=\"rotate(0,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/><path d=\"M0 8 L11 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 312, "stage": 7, "verb": "let out", "meaning": "外に出す／（情報を）漏らす", "def": "to allow someone or something to leave; to reveal", "ex1": "Let the dog out.", "ja1": "犬を外に出して。", "ex2": "Don't let out the details before the announcement.", "ja2": "発表の前に詳細を漏らさないでください。", "note": "", "nuance": "人や物を外に出す意味と、秘密を漏らす意味がある。", "groups": ["reveal_secret"], "etymology": "let（～させる）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「外に出す／（情報を）漏らす」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"rotate(1,32,32)\"><rect x=\"20\" y=\"14\" width=\"24\" height=\"38\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"38\" cy=\"34\" r=\"2\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 313, "stage": 7, "verb": "eat out", "meaning": "外食する", "def": "to eat at a restaurant instead of at home", "ex1": "We eat out on Fridays.", "ja1": "金曜は外食する。", "ex2": "The team ate out together after the workshop.", "ja2": "ワークショップの後、チームで外食した。", "note": "", "nuance": "外食する、家庭料理ではなく外で食べる選択。", "groups": ["dining_location"], "etymology": "eat（食べる）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「外食する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(0,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"16\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"27\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><circle cx=\"37\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><path d=\"M26 38 Q32 42 38 38\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 314, "stage": 7, "verb": "eat in", "meaning": "家で食べる、店内で食べる", "def": "to eat at home rather than at a restaurant", "ex1": "Let's eat in tonight.", "ja1": "今夜は家で食べよう。", "ex2": "We ate in at the office to keep working.", "ja2": "作業を続けるため社内で食事を済ませた。", "note": "", "nuance": "家で食事をする、eat outの対義語。", "groups": ["dining_location"], "etymology": "eat（食べる）＋in（中へ）\n→ 外から中に入る・参加や到着のイメージ\n→ そこから「家で食べる、店内で食べる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-12,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"16\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"27\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><circle cx=\"37\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><path d=\"M26 38 Q32 42 38 38\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 315, "stage": 7, "verb": "ease into", "meaning": "徐々に慣らす、ゆっくり始める", "def": "to start something gradually and gently", "ex1": "Ease into the new routine.", "ja1": "新しい習慣に徐々に慣れていって。", "ex2": "We eased into the new process over two weeks.", "ja2": "2週間かけて新しい手順へ徐々に移行した。", "note": "", "nuance": "段階を踏んで徐々に慣らしていく、丁寧な導入。", "groups": ["gradual_pace"], "etymology": "ease（和らげる）＋into（中へ変化）\n→ ある状態の中に入り込む・変化を伴うイメージ\n→ そこから「徐々に慣らす、ゆっくり始める」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(8,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"16\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"27\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><circle cx=\"37\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><path d=\"M26 38 Q32 42 38 38\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 316, "stage": 7, "verb": "pull out", "meaning": "引き抜く／撤退する", "def": "to remove something; to withdraw from an agreement", "ex1": "The dentist pulled out my tooth.", "ja1": "歯医者が歯を抜いた。", "ex2": "The partner pulled out of the joint project.", "ja2": "パートナー企業が共同事業から撤退した。", "note": "", "nuance": "物を引き抜く意味と、契約や関係から撤退する意味。", "groups": ["pull_out_away"], "etymology": "pull（引く）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「引き抜く／撤退する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#9A5B2E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(10,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 317, "stage": 7, "verb": "pull into", "meaning": "（車が）〜に入って止まる", "def": "to drive into a place and stop", "ex1": "We pulled into the parking lot.", "ja1": "駐車場に入った。", "ex2": "The truck pulled into the loading bay.", "ja2": "トラックが搬入口に入ってきた。", "note": "", "nuance": "車が場所に入って停止する、具体的な運転動作。", "groups": ["vehicle_actions"], "etymology": "pull（引く）＋into（中へ変化）\n→ ある状態の中に入り込む・変化を伴うイメージ\n→ そこから「（車が）〜に入って止まる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#2E6B4F\"/><g transform=\"rotate(-6,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 318, "stage": 7, "verb": "cut off*2", "meaning": "話を遮る", "def": "to interrupt someone who is speaking", "ex1": "Don't cut me off.", "ja1": "話を遮らないで。", "ex2": "He cut off the client mid-sentence.", "ja2": "彼は顧客の話を途中で遮った。", "note": "Stage 5 / 7 に別語義あり", "nuance": "話を遮る（Stage7）、cut off*3（関係を断つ）と区別。", "groups": ["cut_off_senses"], "etymology": "cut（切る）＋off（離れて）\n→ くっついていた物が離れる・停止や出発のイメージ\n→ そこから「話を遮る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"rotate(13,32,32)\"><circle cx=\"20\" cy=\"20\" r=\"4\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"20\" cy=\"44\" r=\"4\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M23 22 L48 44 M23 42 L48 20\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 319, "stage": 7, "verb": "push through", "meaning": "押し通す、成立させる", "def": "to succeed in getting something accepted or approved", "ex1": "She pushed through the reform.", "ja1": "彼女は改革を押し通した。", "ex2": "We pushed through the budget approval before quarter end.", "ja2": "四半期末までに予算承認を通した。", "note": "", "nuance": "抵抗を押し切って物事を成立させる、強い推進力。", "groups": ["accomplish_through"], "etymology": "push（押す）＋through（通り抜けて）\n→ 最初から最後まで通り抜けるイメージ\n→ そこから「押し通す、成立させる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#1B2A41\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-8,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-dasharray=\"3 2\"/><path d=\"M0 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 320, "stage": 7, "verb": "end up", "meaning": "結局〜になる", "def": "to finally be in a particular state or place", "ex1": "We ended up walking home.", "ja1": "結局歩いて帰った。", "ex2": "We ended up choosing the cheaper vendor.", "ja2": "結局、安いほうの業者を選んだ。", "note": "後ろは -ing または with / in", "nuance": "結果的にある状態に至る、成り行きのニュアンス。", "groups": ["turn_out_end_up"], "etymology": "end（終わる）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「結局〜になる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-14,32,32)\"><rect x=\"20\" y=\"14\" width=\"24\" height=\"38\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"38\" cy=\"34\" r=\"2\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 321, "stage": 7, "verb": "pull up*2", "meaning": "（データ・画面を）呼び出す", "def": "to retrieve and display information", "ex1": "Let me pull up the map.", "ja1": "地図を出しますね。", "ex2": "Can you pull up last month's report?", "ja2": "先月のレポートを出してもらえますか。", "note": "Stage 6 の pull up（車を止める）と区別", "nuance": "データや画面を呼び出す、pull up（Stage6の車の意味）とは別。", "groups": ["pull_up_senses"], "etymology": "pull（引く）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「（データ・画面を）呼び出す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#9A5B2E\"/><g transform=\"rotate(0,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 322, "stage": 7, "verb": "spice up", "meaning": "変化や面白みを加える", "def": "to make something more interesting or exciting", "ex1": "Spice up the soup with pepper.", "ja1": "スープにこしょうで風味を足して。", "ex2": "Let's spice up the presentation with a live demo.", "ja2": "実演を入れてプレゼンに変化をつけましょう。", "note": "", "nuance": "変化や刺激を加えて面白くする、活性化のニュアンス。", "groups": [], "etymology": "spice（香辛料を加える）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「変化や面白みを加える」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-3,32,32)\"><path d=\"M32 14 Q44 30 44 38 Q44 48 32 48 Q20 48 20 38 Q20 30 32 14 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 323, "stage": 7, "verb": "start out", "meaning": "（最初は）〜として始まる", "def": "to begin your life or career in a particular way", "ex1": "He started out as a waiter.", "ja1": "彼はウェイターとして働き始めた。", "ex2": "The company started out as a small studio.", "ja2": "その会社は小さなスタジオとして始まった。", "note": "", "nuance": "キャリアや人生の出発点を語る、経歴の語り出し。", "groups": ["begin"], "etymology": "start（始める）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「（最初は）〜として始まる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"rotate(14,32,32)\"><circle cx=\"32\" cy=\"26\" r=\"12\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M26 38 L38 38 M28 44 L36 44\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 324, "stage": 7, "verb": "stick up for", "meaning": "かばう、擁護する", "def": "to defend or support someone", "ex1": "He stuck up for his friend.", "ja1": "彼は友人をかばった。", "ex2": "She stuck up for her team in the review.", "ja2": "彼女はレビューでチームを擁護した。", "note": "", "nuance": "誰かを擁護して味方につく、支持のニュアンス。", "groups": [], "etymology": "stick（突き刺す・くっつく）＋for（求めて）\n→ 目的物を求めて手を伸ばすイメージ\n→ そこから「かばう、擁護する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#8A4B8A\"/><g transform=\"rotate(8,32,32)\"><circle cx=\"24\" cy=\"32\" r=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"40\" cy=\"32\" r=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/><path d=\"M0 8 L11 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 325, "stage": 7, "verb": "settle for", "meaning": "妥協して受け入れる", "def": "to accept something less than what you wanted", "ex1": "We settled for a smaller room.", "ja1": "妥協して小さい部屋にした。", "ex2": "We settled for a partial delivery this month.", "ja2": "今月は一部納品で妥協した。", "note": "", "nuance": "本来望んでいたものより低いレベルで妥協する。", "groups": ["give_up_in"], "etymology": "settle（落ち着かせる）＋for（求めて）\n→ 目的物を求めて手を伸ばすイメージ\n→ そこから「妥協して受け入れる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#8A4B8A\"/><g transform=\"rotate(11,32,32)\"><path d=\"M22 20 L22 44 L42 44 L42 30 M22 32 L42 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M22 44 L20 50 M42 44 L44 50\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/><path d=\"M0 8 L11 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 326, "stage": 7, "verb": "talk back", "meaning": "口答えする", "def": "to reply rudely to someone in authority", "ex1": "Don't talk back to your parents.", "ja1": "親に口答えしないで。", "ex2": "Talking back to a client rarely ends well.", "ja2": "顧客に口答えしてよい結果になることはまずない。", "note": "", "nuance": "目上に対して反抗的な口答えをする、否定的な行為。", "groups": [], "etymology": "talk（話す）＋back（後ろ・元へ）\n→ 元の場所や状態に戻るイメージ\n→ そこから「口答えする」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(12,32,32)\"><path d=\"M14 20 Q14 16 18 16 L46 16 Q50 16 50 20 L50 36 Q50 40 46 40 L26 40 L18 48 L20 40 L18 40 Q14 40 14 36 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M14 4 Q4 4 4 12 M4 12 L0 9 M4 12 L8 12\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 327, "stage": 7, "verb": "go down*2", "meaning": "（システムが）停止する、（記録に）残る", "def": "to stop working; to be recorded in history", "ex1": "The internet went down last night.", "ja1": "昨夜インターネットが落ちた。", "ex2": "The server went down for two hours.", "ja2": "サーバーが2時間停止した。", "note": "Stage 1 の go down（下がる）と区別", "nuance": "下がる（Stage1）とは別に、システムが停止する意味。", "groups": ["go_down_senses"], "etymology": "go（行く）＋down（下へ）\n→ 下向き・減少や書き留めるイメージ\n→ そこから「（システムが）停止する、（記録に）残る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"rotate(-14,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 16 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 328, "stage": 7, "verb": "let off", "meaning": "大目に見る、放免する", "def": "to not punish someone, or to punish them lightly", "ex1": "The teacher let him off with a warning.", "ja1": "先生は警告だけで彼を許した。", "ex2": "He was let off with a verbal warning.", "ja2": "彼は口頭注意だけで済んだ。", "note": "", "nuance": "本来の罰を軽くする、大目に見るという寛大さ。", "groups": [], "etymology": "let（～させる）＋off（離れて）\n→ くっついていた物が離れる・停止や出発のイメージ\n→ そこから「大目に見る、放免する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#2E6B4F\"/><g transform=\"rotate(5,32,32)\"><rect x=\"20\" y=\"14\" width=\"24\" height=\"38\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"38\" cy=\"34\" r=\"2\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 329, "stage": 7, "verb": "line up", "meaning": "並ぶ／手配する、そろえる", "def": "to form a line; to arrange or organize something", "ex1": "People lined up outside the store.", "ja1": "人々が店の外に並んだ。", "ex2": "We lined up three candidates for the interview.", "ja2": "面接候補を3名手配した。", "note": "", "nuance": "整列する意味と、物事を手配する意味の両方。", "groups": [], "etymology": "line（並べる）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「並ぶ／手配する、そろえる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"rotate(2,32,32)\"><path d=\"M32 16 L32 44 M20 44 L44 44\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/><path d=\"M18 22 L32 16 L46 22\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\"/><circle cx=\"18\" cy=\"26\" r=\"6\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\"/><circle cx=\"46\" cy=\"26\" r=\"6\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 330, "stage": 7, "verb": "cut off*3", "meaning": "（関係・支援を）断つ", "def": "to end a relationship or stop providing something", "ex1": "His family cut him off.", "ja1": "家族は彼と縁を切った。", "ex2": "The supplier cut us off after the payment dispute.", "ja2": "支払いのもつれの後、仕入先は取引を停止した。", "note": "Stage 5 / 7 に別語義あり", "nuance": "遮断・遮るとは別に、関係や支援を断つという強い意味。", "groups": ["cut_off_senses"], "etymology": "cut（切る）＋off（離れて）\n→ くっついていた物が離れる・停止や出発のイメージ\n→ そこから「（関係・支援を）断つ」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"rotate(13,32,32)\"><circle cx=\"20\" cy=\"20\" r=\"4\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"20\" cy=\"44\" r=\"4\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M23 22 L48 44 M23 42 L48 20\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 331, "stage": 7, "verb": "drag into", "meaning": "巻き込む", "def": "to involve someone in a situation against their will", "ex1": "Don't drag me into your argument.", "ja1": "私を口論に巻き込まないで。", "ex2": "Don't drag other teams into this issue.", "ja2": "この問題に他チームを巻き込まないでください。", "note": "", "nuance": "望まない状況に人を巻き込む、否定的なニュアンス。", "groups": [], "etymology": "drag（引きずる）＋into（中へ変化）\n→ ある状態の中に入り込む・変化を伴うイメージ\n→ そこから「巻き込む」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"rotate(13,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 332, "stage": 7, "verb": "hold off*2", "meaning": "食い止める、寄せつけない", "def": "to prevent someone from approaching or succeeding", "ex1": "They held off the attackers.", "ja1": "彼らは攻撃者を食い止めた。", "ex2": "We held off competitors by improving support.", "ja2": "サポートを強化して競合を食い止めた。", "note": "Stage 4 の hold off（見合わせる）と区別", "nuance": "見合わせる（Stage4）とは別に、相手を寄せつけず食い止める意味。", "groups": ["hold_out_off"], "etymology": "hold（持つ・保つ）＋off（離れて）\n→ くっついていた物が離れる・停止や出発のイメージ\n→ そこから「食い止める、寄せつけない」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-1,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 333, "stage": 7, "verb": "play out", "meaning": "展開する、結末を迎える", "def": "to develop or end in a particular way", "ex1": "Let's see how it plays out.", "ja1": "どうなるか様子を見よう。", "ex2": "Let's see how the negotiation plays out.", "ja2": "交渉がどう展開するか見守りましょう。", "note": "", "nuance": "物事がどのように展開するかを見守る表現。", "groups": [], "etymology": "play（遊ぶ・演じる）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「展開する、結末を迎える」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(1,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"16\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"27\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><circle cx=\"37\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><path d=\"M26 38 Q32 42 38 38\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 334, "stage": 7, "verb": "take over", "meaning": "引き継ぐ、支配する", "def": "to take control or responsibility for something", "ex1": "She took over as captain.", "ja1": "彼女がキャプテンを引き継いだ。", "ex2": "I'll take over the project from April.", "ja2": "4月からプロジェクトを引き継ぎます。", "note": "", "nuance": "責任や役割を引き継ぐ、権限の移譲を表す。", "groups": [], "etymology": "take（取る）＋over（越えて）\n→ 何かを越えて広がる・一通り目を通すイメージ\n→ そこから「引き継ぐ、支配する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#9A5B2E\"/><g transform=\"rotate(-2,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 2 A6 6 0 1 1 2 8\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2.2\"/><path d=\"M2 8 L0 4 M2 8 L6 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 335, "stage": 7, "verb": "fit in*2", "meaning": "（予定に）入れる、都合をつける", "def": "to find time for someone or something", "ex1": "Can you fit in a haircut today?", "ja1": "今日、散髪の時間を作れますか。", "ex2": "Can you fit in a 15-minute call today?", "ja2": "今日15分の打ち合わせを入れられますか。", "note": "Stage 5 の fit in（なじむ）と区別", "nuance": "溶け込む（Stage5）とは別に、予定に組み込む意味。", "groups": ["schedule_fit"], "etymology": "fit（合う）＋in（中へ）\n→ 外から中に入る・参加や到着のイメージ\n→ そこから「（予定に）入れる、都合をつける」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#8A4B8A\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(3,32,32)\"><circle cx=\"24\" cy=\"32\" r=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"40\" cy=\"32\" r=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 336, "stage": 7, "verb": "stick to", "meaning": "守り続ける、固執する", "def": "to continue with something and not change it", "ex1": "Stick to the plan.", "ja1": "計画を守って。", "ex2": "Let's stick to the agreed scope.", "ja2": "合意したスコープを守りましょう。", "note": "", "nuance": "決めた方針を守り続ける、一貫性を保つ表現。", "groups": ["stick_persist"], "etymology": "stick（突き刺す・くっつく）＋to（～へ）\n→ 目的地・相手に向かうイメージ\n→ そこから「守り続ける、固執する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#2E6B4F\"/><g transform=\"rotate(9,32,32)\"><circle cx=\"24\" cy=\"32\" r=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"40\" cy=\"32\" r=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L12 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><circle cx=\"14\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/></g></svg>"}, {"no": 337, "stage": 7, "verb": "play up", "meaning": "強調する、大げさに言う", "def": "to emphasize something to make it seem more important", "ex1": "He played up his experience.", "ja1": "彼は自分の経験を強調した。", "ex2": "The proposal plays up our support capability.", "ja2": "提案書は当社のサポート力を前面に出している。", "note": "", "nuance": "実際より誇張して強調する、やや誇示的な表現。", "groups": [], "etymology": "play（遊ぶ・演じる）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「強調する、大げさに言う」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"rotate(-11,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"16\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"27\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><circle cx=\"37\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><path d=\"M26 38 Q32 42 38 38\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 338, "stage": 7, "verb": "check off", "meaning": "チェックを入れる、消し込む", "def": "to mark items on a list as completed", "ex1": "Check off each item as you pack.", "ja1": "荷造りしながら項目にチェックを入れて。", "ex2": "Let's check off the completed test cases.", "ja2": "完了したテストケースを消し込みましょう。", "note": "", "nuance": "リストの項目にチェックを入れる、確認作業。", "groups": [], "etymology": "check（確認する）＋off（離れて）\n→ くっついていた物が離れる・停止や出発のイメージ\n→ そこから「チェックを入れる、消し込む」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"rotate(-1,32,32)\"><path d=\"M32 20 Q24 14 16 18 L16 44 Q24 40 32 46 Q40 40 48 44 L48 18 Q40 14 32 20 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 339, "stage": 7, "verb": "fill in*2", "meaning": "（不在の間の情報を）伝える", "def": "to give someone the information they missed", "ex1": "Fill me in on what happened.", "ja1": "何があったか教えて。", "ex2": "Can you fill me in on yesterday's meeting?", "ja2": "昨日の会議の内容を教えてもらえますか。", "note": "fill someone in on の語順。Stage 5 の fill in（記入する）と区別", "nuance": "記入（Stage2・5）とは別に、不在中の情報を伝える意味。", "groups": ["contact_related"], "etymology": "fill（満たす）＋in（中へ）\n→ 外から中に入る・参加や到着のイメージ\n→ そこから「（不在の間の情報を）伝える」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#9A5B2E\"/><g transform=\"rotate(12,32,32)\"><path d=\"M32 14 Q44 30 44 38 Q44 48 32 48 Q20 48 20 38 Q20 30 32 14 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 340, "stage": 7, "verb": "let on", "meaning": "秘密を漏らす、そぶりを見せる", "def": "to reveal a secret or show that you know something", "ex1": "Don't let on that we know.", "ja1": "私たちが知っていると悟らせないで。", "ex2": "Don't let on that the deal is still unsigned.", "ja2": "契約がまだ未締結だと漏らさないでください。", "note": "", "nuance": "秘密を漏らす、または知っている素振りを見せる表現。", "groups": ["reveal_secret"], "etymology": "let（～させる）＋on（接触・継続）\n→ くっついたまま続く・作動し続けるイメージ\n→ そこから「秘密を漏らす、そぶりを見せる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-12,32,32)\"><rect x=\"20\" y=\"14\" width=\"24\" height=\"38\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"38\" cy=\"34\" r=\"2\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 341, "stage": 7, "verb": "sit back", "meaning": "ゆったり座る／静観する", "def": "to relax; to take no action when you could", "ex1": "Sit back and enjoy the show.", "ja1": "ゆったり座ってショーを楽しんで。", "ex2": "We can't just sit back while the schedule slips.", "ja2": "予定が遅れていくのを静観はできない。", "note": "", "nuance": "行動を起こさず静観する、消極的な姿勢を表す。", "groups": ["reflect_step_back"], "etymology": "sit（座る）＋back（後ろ・元へ）\n→ 元の場所や状態に戻るイメージ\n→ そこから「ゆったり座る／静観する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-5,32,32)\"><path d=\"M22 20 L22 44 L42 44 L42 30 M22 32 L42 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M22 44 L20 50 M42 44 L44 50\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M14 4 Q4 4 4 12 M4 12 L0 9 M4 12 L8 12\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 342, "stage": 7, "verb": "scoot over", "meaning": "席を詰めて寄る", "def": "to move sideways to make space for someone", "ex1": "Scoot over, please.", "ja1": "少し詰めてください。", "ex2": "Could everyone scoot over so the client can sit?", "ja2": "顧客が座れるよう皆さん詰めてもらえますか。", "note": "くだけた表現", "nuance": "席を詰めて空間を作る、カジュアルな指示。", "groups": [], "etymology": "scoot（素早く移動する）＋over（越えて）\n→ 何かを越えて広がる・一通り目を通すイメージ\n→ そこから「席を詰めて寄る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"rotate(4,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 2 A6 6 0 1 1 2 8\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2.2\"/><path d=\"M2 8 L0 4 M2 8 L6 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 343, "stage": 7, "verb": "take away from", "meaning": "価値を損なう", "def": "to reduce the value or good effect of something", "ex1": "The noise took away from the performance.", "ja1": "騒音が演奏の魅力を損なった。", "ex2": "The typos took away from an otherwise strong proposal.", "ja2": "誤字が、それ以外は優れた提案の価値を損ねた。", "note": "Stage 5 の take away（取り上げる）と区別", "nuance": "何かの価値や魅力を損なう、マイナスの影響。", "groups": [], "etymology": "take（取る）＋from（～から）\n→ ある地点から離れるイメージ\n→ そこから「価値を損なう」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#9A5B2E\"/><g transform=\"rotate(-11,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"2\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/><path d=\"M4 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 344, "stage": 7, "verb": "get across", "meaning": "（考えを）伝える、理解させる", "def": "to communicate an idea so that others understand", "ex1": "I couldn't get my point across.", "ja1": "言いたいことが伝わらなかった。", "ex2": "The slides got the message across clearly.", "ja2": "スライドは意図を明確に伝えた。", "note": "", "nuance": "自分の考えを相手に理解させる、伝達の成功を表す。", "groups": ["convey_info"], "etymology": "get（得る・～になる）＋across（横切って）\n→ ある空間や境界を横切って向こう側に届くイメージ\n→ そこから「（考えを）伝える、理解させる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"rotate(0,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M2 2 L14 14\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><path d=\"M2 14 L14 2\" stroke=\"#B5392F\" stroke-width=\"1.4\" opacity=\"0.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 345, "stage": 7, "verb": "stand for*2", "meaning": "容認する、我慢する", "def": "to tolerate behavior you disapprove of", "ex1": "I won't stand for rudeness.", "ja1": "無礼は容認しません。", "ex2": "We won't stand for repeated delays.", "ja2": "度重なる遅延は容認できません。", "note": "否定文で使うのが普通。Stage 3 の stand for（略である）と区別", "nuance": "略語（Stage3）とは別に、容認する・我慢するという意味。", "groups": ["stand_for_senses"], "etymology": "stand（立つ）＋for（求めて）\n→ 目的物を求めて手を伸ばすイメージ\n→ そこから「容認する、我慢する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#9A5B2E\"/><g transform=\"rotate(-3,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/><path d=\"M0 8 L11 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 346, "stage": 7, "verb": "hand over", "meaning": "引き渡す、引き継ぐ", "def": "to give something or responsibility to someone else", "ex1": "Hand over the keys.", "ja1": "鍵を渡してください。", "ex2": "I'll hand over the account to my successor.", "ja2": "担当顧客を後任に引き継ぎます。", "note": "", "nuance": "物や権限を相手に引き渡す、譲渡の動作。", "groups": ["hand_over"], "etymology": "hand（手渡す）＋over（越えて）\n→ 何かを越えて広がる・一通り目を通すイメージ\n→ そこから「引き渡す、引き継ぐ」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#8A4B8A\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(3,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 2 A6 6 0 1 1 2 8\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2.2\"/><path d=\"M2 8 L0 4 M2 8 L6 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 347, "stage": 7, "verb": "pass out*2", "meaning": "配る", "def": "to give something to each person in a group", "ex1": "Pass out the flyers at the gate.", "ja1": "門でチラシを配って。", "ex2": "Please pass out the agenda before we start.", "ja2": "始める前に議事次第を配ってください。", "note": "Stage 3 の pass out（気を失う）と区別", "nuance": "気絶（Stage3）とは別に、配るという意味。", "groups": ["distribute"], "etymology": "pass（通す・渡す）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「配る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#9A5B2E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-2,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 348, "stage": 7, "verb": "stick around", "meaning": "その場に残る、居残る", "def": "to stay in a place for a while longer", "ex1": "Stick around, the show isn't over.", "ja1": "まだ終わっていないから残って。", "ex2": "Could you stick around after the meeting?", "ja2": "会議の後、少し残ってもらえますか。", "note": "", "nuance": "その場に残る、離れずに待つよう促す表現。", "groups": ["stick_persist"], "etymology": "stick（突き刺す・くっつく）＋around（周りに）\n→ あちこち・ぐるりと回るイメージ\n→ そこから「その場に残る、居残る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"rotate(7,32,32)\"><circle cx=\"24\" cy=\"32\" r=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"40\" cy=\"32\" r=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 2 A6 6 0 1 1 2 8\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2.2\"/><path d=\"M2 8 L0 4 M2 8 L6 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 349, "stage": 7, "verb": "work on", "meaning": "取り組む、改善する", "def": "to spend time producing or improving something", "ex1": "I'm working on my pronunciation.", "ja1": "発音を練習しています。", "ex2": "She's working on the requirements document.", "ja2": "彼女は要件定義書に取り組んでいる。", "note": "", "nuance": "継続的に取り組んで改善する、進行中の努力。", "groups": ["undertake_continue_work"], "etymology": "work（働く・作用させる）＋on（接触・継続）\n→ くっついたまま続く・作動し続けるイメージ\n→ そこから「取り組む、改善する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"rotate(5,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"10\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M32 14 L32 20 M32 44 L32 50 M14 32 L20 32 M44 32 L50 32 M20 20 L24 24 M40 40 L44 44 M44 20 L40 24 M24 40 L20 44\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 350, "stage": 7, "verb": "come down to", "meaning": "結局〜次第である", "def": "to be a matter of one decisive factor", "ex1": "It comes down to money.", "ja1": "結局はお金の問題だ。", "ex2": "It comes down to whether we can meet the deadline.", "ja2": "結局は納期を守れるかどうかだ。", "note": "", "nuance": "結局は特定の要因次第である、結論を導く表現。", "groups": ["turn_out_end_up"], "etymology": "come（来る）＋to（～へ）\n→ 目的地・相手に向かうイメージ\n→ そこから「結局〜次第である」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(4,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L12 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><circle cx=\"14\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/></g></svg>"}, {"no": 351, "stage": 7, "verb": "settle down", "meaning": "落ち着く／身を固める", "def": "to become calm; to start living a stable life", "ex1": "Settle down, everyone.", "ja1": "みんな、落ち着いて。", "ex2": "Things settled down after the release.", "ja2": "リリース後、状況は落ち着いた。", "note": "", "nuance": "気持ちが落ち着く意味と、生活が安定する意味の両方。", "groups": ["calm_down"], "etymology": "settle（落ち着かせる）＋down（下へ）\n→ 下向き・減少や書き留めるイメージ\n→ そこから「落ち着く／身を固める」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-9,32,32)\"><path d=\"M22 20 L22 44 L42 44 L42 30 M22 32 L42 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M22 44 L20 50 M42 44 L44 50\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 16 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 352, "stage": 7, "verb": "catch on*2", "meaning": "理解する、飲み込む", "def": "to begin to understand something", "ex1": "It took me a while to catch on.", "ja1": "理解するのに少し時間がかかった。", "ex2": "He caught on to the new process quickly.", "ja2": "彼は新しい手順をすぐに飲み込んだ。", "note": "Stage 5 の catch on（流行する）と区別", "nuance": "流行する（Stage5）とは別に、物事を理解し始める意味。", "groups": ["understand"], "etymology": "catch（捕まえる）＋on（接触・継続）\n→ くっついたまま続く・作動し続けるイメージ\n→ そこから「理解する、飲み込む」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-4,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 353, "stage": 8, "verb": "hash out", "meaning": "議論して詰める", "def": "to discuss something in detail until you reach agreement", "ex1": "We hashed out the details over dinner.", "ja1": "夕食を取りながら細部を詰めた。", "ex2": "Let's hash out the responsibilities before signing.", "ja2": "締結の前に責任分担を詰めましょう。", "note": "", "nuance": "議論を重ねて詳細を詰める、労力を要する調整過程。", "groups": ["discuss_thoroughly"], "etymology": "hash（こまごまと処理する）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「議論して詰める」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"rotate(-11,32,32)\"><path d=\"M32 20 Q24 14 16 18 L16 44 Q24 40 32 46 Q40 40 48 44 L48 18 Q40 14 32 20 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 354, "stage": 8, "verb": "read up on", "meaning": "（事前に）読み込む、調べる", "def": "to study a subject by reading about it", "ex1": "I read up on Portugal before the trip.", "ja1": "旅行の前にポルトガルについて読み込んだ。", "ex2": "I read up on their industry before the meeting.", "ja2": "会議の前に先方の業界について読み込んだ。", "note": "", "nuance": "事前に情報を集めて予習する、準備のニュアンス。", "groups": ["study_review"], "etymology": "read（読む）＋on（接触・継続）\n→ くっついたまま続く・作動し続けるイメージ\n→ そこから「（事前に）読み込む、調べる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(2,32,32)\"><path d=\"M32 20 Q24 14 16 18 L16 44 Q24 40 32 46 Q40 40 48 44 L48 18 Q40 14 32 20 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 355, "stage": 8, "verb": "dig into", "meaning": "深く掘り下げる", "def": "to examine or investigate something thoroughly", "ex1": "Let's dig into the data.", "ja1": "データを掘り下げよう。", "ex2": "We dug into the logs to find the root cause.", "ja2": "根本原因を探るためログを掘り下げた。", "note": "", "nuance": "問題やテーマを深く掘り下げる、探求的な姿勢。", "groups": ["elaborate_dig"], "etymology": "dig（掘る）＋into（中へ変化）\n→ ある状態の中に入り込む・変化を伴うイメージ\n→ そこから「深く掘り下げる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#9A5B2E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(11,32,32)\"><path d=\"M40 16 Q46 16 46 22 Q46 26 42 28 L24 46 Q22 48 20 46 Q18 44 20 42 L38 24 Q40 20 40 16 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linejoin=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 356, "stage": 8, "verb": "take up on", "meaning": "（申し出を）受ける", "def": "to accept an offer that someone has made", "ex1": "I'll take you up on that drink.", "ja1": "その一杯、お言葉に甘えます。", "ex2": "I'd like to take you up on your offer of a trial.", "ja2": "試用のご提案をお受けしたいです。", "note": "take someone up on something の語順", "nuance": "相手の申し出を受け入れる、take upの発展形。", "groups": ["accept_take_up"], "etymology": "take（取る）＋on（接触・継続）\n→ くっついたまま続く・作動し続けるイメージ\n→ そこから「（申し出を）受ける」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#8A4B8A\"/><g transform=\"rotate(5,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 357, "stage": 8, "verb": "sit through", "meaning": "最後まで座って耐える", "def": "to stay until the end of something long or dull", "ex1": "I sat through the whole movie.", "ja1": "映画を最後まで座って見た。", "ex2": "We sat through a three-hour vendor presentation.", "ja2": "3時間の業者説明を最後まで聞いた。", "note": "", "nuance": "退屈でも最後まで座って耐える、忍耐を伴う表現。", "groups": ["endure"], "etymology": "sit（座る）＋through（通り抜けて）\n→ 最初から最後まで通り抜けるイメージ\n→ そこから「最後まで座って耐える」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"rotate(4,32,32)\"><path d=\"M22 20 L22 44 L42 44 L42 30 M22 32 L42 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M22 44 L20 50 M42 44 L44 50\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-dasharray=\"3 2\"/><path d=\"M0 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 358, "stage": 8, "verb": "whip out", "meaning": "さっと取り出す", "def": "to take something out quickly", "ex1": "He whipped out his phone.", "ja1": "彼はさっとスマホを取り出した。", "ex2": "She whipped out a printed copy of the contract.", "ja2": "彼女は契約書の印刷版をさっと取り出した。", "note": "", "nuance": "物をさっと素早く取り出す、機敏な動作。", "groups": [], "etymology": "whip（ムチ打つ・さっと動かす）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「さっと取り出す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#9A5B2E\"/><g transform=\"rotate(-9,32,32)\"><path d=\"M14 32 Q20 22 26 32 Q32 42 38 32 Q44 22 50 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 359, "stage": 8, "verb": "rough up", "meaning": "手荒に扱う、暴行する", "def": "to attack someone physically", "ex1": "He was roughed up outside the bar.", "ja1": "彼はバーの外で暴行された。", "ex2": "Roughing up a colleague is grounds for dismissal.", "ja2": "同僚への暴行は解雇事由になる。", "note": "", "nuance": "手荒く扱う、暴力的なニュアンスを含む表現。", "groups": ["bully_mistreat"], "etymology": "rough（手荒に扱う・大まかにする）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「手荒に扱う、暴行する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(9,32,32)\"><path d=\"M32 16 L32 44 M20 44 L44 44\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/><path d=\"M18 22 L32 16 L46 22\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\"/><circle cx=\"18\" cy=\"26\" r=\"6\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\"/><circle cx=\"46\" cy=\"26\" r=\"6\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 360, "stage": 8, "verb": "get on with", "meaning": "（仕事を）進める", "def": "to continue doing something, especially work", "ex1": "Let's get on with it.", "ja1": "さっさと進めよう。", "ex2": "Let's get on with the agenda; we're behind.", "ja2": "遅れているので議事を進めましょう。", "note": "", "nuance": "中断していた作業を再開して進める、督促的な響き。", "groups": ["undertake_continue_work"], "etymology": "get（得る・～になる）＋with（一緒に）\n→ 対象と一緒に行動するイメージ\n→ そこから「（仕事を）進める」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#1B2A41\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-5,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 2 L8 14 M2 8 L14 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 361, "stage": 8, "verb": "stay out", "meaning": "外にいて帰らない", "def": "to remain away from home, especially at night", "ex1": "He stayed out until midnight.", "ja1": "彼は深夜まで帰らなかった。", "ex2": "The team stayed out late celebrating the contract.", "ja2": "チームは契約成立を祝って遅くまで外にいた。", "note": "", "nuance": "夜遅くまで家に帰らない、外出を続ける状態。", "groups": ["home_or_out"], "etymology": "stay（とどまる）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「外にいて帰らない」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#9A5B2E\"/><g transform=\"rotate(-15,32,32)\"><path d=\"M22 20 L22 44 L42 44 L42 30 M22 32 L42 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M22 44 L20 50 M42 44 L44 50\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 362, "stage": 8, "verb": "branch out", "meaning": "手を広げる、新分野に進出する", "def": "to start doing something new or different", "ex1": "She branched out into painting.", "ja1": "彼女は絵画にも手を広げた。", "ex2": "The company branched out into cloud services.", "ja2": "同社はクラウドサービスに進出した。", "note": "", "nuance": "既存の事業から新分野へ進出する、拡大のニュアンス。", "groups": [], "etymology": "branch（枝分かれする）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「手を広げる、新分野に進出する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"rotate(-7,32,32)\"><path d=\"M32 48 L32 28\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/><path d=\"M32 28 Q22 28 20 18 Q30 18 32 28 Q34 18 44 18 Q42 28 32 28\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 363, "stage": 8, "verb": "sneak out", "meaning": "こっそり抜け出す", "def": "to leave a place quietly without being noticed", "ex1": "He sneaked out of the house.", "ja1": "彼は家をこっそり抜け出した。", "ex2": "She sneaked out of the session to take a call.", "ja2": "彼女は電話のためセッションをそっと抜けた。", "note": "", "nuance": "こっそり気づかれずに抜け出す、静かな離脱。", "groups": ["sneak_out"], "etymology": "sneak（こっそり動く）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「こっそり抜け出す」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#8A4B8A\"/><g transform=\"rotate(6,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 364, "stage": 8, "verb": "chip away at", "meaning": "少しずつ削る、地道に取り組む", "def": "to gradually reduce or work at something", "ex1": "She chipped away at her debt.", "ja1": "彼女は借金を少しずつ減らした。", "ex2": "We're chipping away at the backlog.", "ja2": "未処理案件を少しずつ片づけている。", "note": "", "nuance": "少しずつ地道に問題を減らしていく、根気強い取り組み。", "groups": ["gradual_reduce"], "etymology": "chip（欠く）＋at（～めがけて）\n→ ピンポイントで対象を狙うイメージ\n→ そこから「少しずつ削る、地道に取り組む」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#9A5B2E\"/><g transform=\"rotate(0,32,32)\"><path d=\"M16 32 L26 32 L30 22 L36 42 L40 32 L48 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linejoin=\"round\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 365, "stage": 8, "verb": "hook up", "meaning": "接続する、つなぐ", "def": "to connect one piece of equipment to another", "ex1": "Hook up the printer to the laptop.", "ja1": "プリンターをノートPCにつないで。", "ex2": "Can you hook up the laptop to the projector?", "ja2": "ノートPCをプロジェクターにつないでもらえますか。", "note": "", "nuance": "機器を接続する意味と、人と落ち合う意味の両方。", "groups": ["hook_up_senses"], "etymology": "hook（鉤で引っかける）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「接続する、つなぐ」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#1B2A41\"/><g transform=\"rotate(11,32,32)\"><circle cx=\"24\" cy=\"32\" r=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"40\" cy=\"32\" r=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 366, "stage": 8, "verb": "hook up with", "meaning": "（人と）落ち合う、組む", "def": "to meet or start working with someone", "ex1": "I'll hook up with you at the venue.", "ja1": "会場で落ち合いましょう。", "ex2": "We hooked up with a local partner for the rollout.", "ja2": "展開のため現地パートナーと組んだ。", "note": "文脈により性的な意味になるため、職場では使い方に注意", "nuance": "hook upのバリエーションで、人や組織と提携する意味も。", "groups": ["hook_up_senses"], "etymology": "hook（鉤で引っかける）＋with（一緒に）\n→ 対象と一緒に行動するイメージ\n→ そこから「（人と）落ち合う、組む」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(7,32,32)\"><circle cx=\"24\" cy=\"32\" r=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"40\" cy=\"32\" r=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 2 L8 14 M2 8 L14 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 367, "stage": 8, "verb": "stack up", "meaning": "匹敵する、比較して見劣りしない", "def": "to compare with something else", "ex1": "How does it stack up against the old model?", "ja1": "旧モデルと比べてどうですか。", "ex2": "Let's see how our pricing stacks up against competitors.", "ja2": "当社の価格が競合と比べてどうか見てみましょう。", "note": "stack up against の形が多い", "nuance": "他と比較してどう評価されるか、比較のニュアンス。", "groups": [], "etymology": "stack（積み重ねる）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「匹敵する、比較して見劣りしない」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#8A4B8A\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-12,32,32)\"><rect x=\"18\" y=\"38\" width=\"28\" height=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><rect x=\"20\" y=\"28\" width=\"24\" height=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><rect x=\"22\" y=\"18\" width=\"20\" height=\"8\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 368, "stage": 8, "verb": "go off on", "meaning": "怒鳴りつける", "def": "to suddenly start speaking angrily to someone", "ex1": "He went off on me for being late.", "ja1": "遅刻したことで彼に怒鳴られた。", "ex2": "The client went off on the vendor about the outage.", "ja2": "顧客は障害の件で業者を怒鳴りつけた。", "note": "Stage 2 の go off（鳴る）と区別", "nuance": "誰かに対して怒りを爆発させる、強い叱責。", "groups": ["scold_yell"], "etymology": "go（行く）＋on（接触・継続）\n→ くっついたまま続く・作動し続けるイメージ\n→ そこから「怒鳴りつける」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"rotate(9,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 369, "stage": 8, "verb": "pack up", "meaning": "荷物をまとめる、片づける", "def": "to put things away or into containers when finishing", "ex1": "Let's pack up and go.", "ja1": "荷物をまとめて行こう。", "ex2": "We packed up the booth at six.", "ja2": "6時にブースを片づけた。", "note": "", "nuance": "荷物をまとめて片づける、作業の終了を表す。", "groups": ["tidy_up"], "etymology": "pack（荷造りする）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「荷物をまとめる、片づける」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#2E6B4F\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-9,32,32)\"><rect x=\"16\" y=\"24\" width=\"32\" height=\"24\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M16 24 L32 14 L48 24\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 370, "stage": 8, "verb": "suck up to", "meaning": "ごまをする、へつらう", "def": "to try to please someone in authority insincerely", "ex1": "He's always sucking up to the boss.", "ja1": "彼はいつも上司にごまをすっている。", "ex2": "Sucking up to management won't fix the schedule.", "ja2": "上層部にごまをすっても日程は直らない。", "note": "", "nuance": "上司などに媚びへつらう、否定的なニュアンス。", "groups": [], "etymology": "suck（吸う）＋to（～へ）\n→ 目的地・相手に向かうイメージ\n→ そこから「ごまをする、へつらう」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"rotate(-3,32,32)\"><path d=\"M32 14 Q44 30 44 38 Q44 48 32 48 Q20 48 20 38 Q20 30 32 14 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L12 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><circle cx=\"14\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/></g></svg>"}, {"no": 371, "stage": 8, "verb": "get back together", "meaning": "よりを戻す、再び組む", "def": "to start a relationship or partnership again", "ex1": "They got back together after a year.", "ja1": "二人は1年後によりを戻した。", "ex2": "The two firms got back together on a new joint venture.", "ja2": "両社は新しい合弁事業で再び手を組んだ。", "note": "", "nuance": "別れた relationship や提携を再び結ぶ、復縁・再提携。", "groups": ["dating_romance"], "etymology": "get（得る・～になる）＋together（一つに）\n→ バラバラだった物が一つにまとまるイメージ\n→ そこから「よりを戻す、再び組む」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"rotate(-14,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 2 L8 8 L0 14 M16 2 L8 8 L16 14\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 372, "stage": 8, "verb": "narrow down", "meaning": "絞り込む", "def": "to reduce the number of possibilities or options", "ex1": "We narrowed down the list to three.", "ja1": "候補を3つに絞った。", "ex2": "We narrowed down the cause to a network setting.", "ja2": "原因をネットワーク設定に絞り込んだ。", "note": "", "nuance": "選択肢を絞り込む、候補を減らす意思決定の過程。", "groups": ["gradual_reduce"], "etymology": "narrow（狭める）＋down（下へ）\n→ 下向き・減少や書き留めるイメージ\n→ そこから「絞り込む」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-1,32,32)\"><path d=\"M32 16 L32 44 M20 44 L44 44\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/><path d=\"M18 22 L32 16 L46 22\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\"/><circle cx=\"18\" cy=\"26\" r=\"6\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\"/><circle cx=\"46\" cy=\"26\" r=\"6\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 16 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 373, "stage": 8, "verb": "wrap up", "meaning": "まとめる、終える", "def": "to finish or conclude something", "ex1": "Let's wrap up and go home.", "ja1": "そろそろ終わって帰ろう。", "ex2": "Let's wrap up the meeting in five minutes.", "ja2": "あと5分で会議を締めましょう。", "note": "", "nuance": "作業や会議をまとめて終える、締めくくりの表現。", "groups": ["organize"], "etymology": "wrap（包む）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「まとめる、終える」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"rotate(6,32,32)\"><rect x=\"18\" y=\"26\" width=\"28\" height=\"22\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M32 26 L32 48 M18 34 L46 34\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 374, "stage": 8, "verb": "squeeze in", "meaning": "無理に詰め込む、都合をつける", "def": "to fit something into a limited space or schedule", "ex1": "Can you squeeze in one more person?", "ja1": "もう一人詰められますか。", "ex2": "Can we squeeze in a review before Friday?", "ja2": "金曜より前にレビューを入れられますか。", "note": "", "nuance": "忙しいスケジュールに無理やり予定を入れる。", "groups": ["schedule_fit"], "etymology": "squeeze（絞る）＋in（中へ）\n→ 外から中に入る・参加や到着のイメージ\n→ そこから「無理に詰め込む、都合をつける」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-5,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 375, "stage": 8, "verb": "sink in", "meaning": "実感が湧く、腑に落ちる", "def": "to be fully understood or felt after some time", "ex1": "The news took a while to sink in.", "ja1": "その知らせを実感するのに時間がかかった。", "ex2": "It took a day for the scale of the incident to sink in.", "ja2": "障害の規模を実感するのに1日かかった。", "note": "", "nuance": "情報や実感が時間をかけて理解に至る、じわじわ感。", "groups": [], "etymology": "sink（沈む）＋in（中へ）\n→ 外から中に入る・参加や到着のイメージ\n→ そこから「実感が湧く、腑に落ちる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"rotate(12,32,32)\"><path d=\"M32 14 Q44 30 44 38 Q44 48 32 48 Q20 48 20 38 Q20 30 32 14 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 376, "stage": 8, "verb": "crack up", "meaning": "大笑いする", "def": "to laugh a lot, or to make someone laugh a lot", "ex1": "We all cracked up at his joke.", "ja1": "彼の冗談に皆で大笑いした。", "ex2": "The team cracked up at the typo on the slide.", "ja2": "スライドの誤字にチームは大笑いした。", "note": "", "nuance": "抑えられないほど大笑いする、爆笑のニュアンス。", "groups": [], "etymology": "crack（ひびを入れる）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「大笑いする」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#8A4B8A\"/><g transform=\"rotate(-7,32,32)\"><path d=\"M16 32 L26 32 L30 22 L36 42 L40 32 L48 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linejoin=\"round\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 377, "stage": 8, "verb": "play into", "meaning": "（相手の）思うつぼになる", "def": "to unintentionally help someone else's plan", "ex1": "That plays into his hands.", "ja1": "それは彼の思うつぼだ。", "ex2": "Rushing the estimate plays into the client's strategy.", "ja2": "見積もりを急ぐのは顧客の思うつぼだ。", "note": "play into someone's hands の形が多い", "nuance": "意図せず相手の思惑どおりになってしまう、不利な状況。", "groups": [], "etymology": "play（遊ぶ・演じる）＋into（中へ変化）\n→ ある状態の中に入り込む・変化を伴うイメージ\n→ そこから「（相手の）思うつぼになる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"rotate(0,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"16\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"27\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><circle cx=\"37\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><path d=\"M26 38 Q32 42 38 38\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 378, "stage": 8, "verb": "pull off*2", "meaning": "（道路脇に）車を寄せて止める", "def": "to drive off a road and stop", "ex1": "We pulled off the highway for a break.", "ja1": "休憩のため高速を降りて停めた。", "ex2": "The driver pulled off the road to check the address.", "ja2": "運転手は住所を確認するため道路脇に車を寄せた。", "note": "Stage 4 の pull off（やってのける）と区別", "nuance": "やってのける（Stage4）とは別に、車を道路脇に寄せる意味。", "groups": ["pull_over_stop_car"], "etymology": "pull（引く）＋off（離れて）\n→ くっついていた物が離れる・停止や出発のイメージ\n→ そこから「（道路脇に）車を寄せて止める」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(8,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 379, "stage": 8, "verb": "bank on", "meaning": "当てにする、頼りにする", "def": "to rely on something happening", "ex1": "Don't bank on good weather.", "ja1": "好天を当てにしないで。", "ex2": "Don't bank on the client approving it this week.", "ja2": "顧客が今週承認すると当てにしないでください。", "note": "", "nuance": "何かが起こることを当てにする、期待や依存の表現。", "groups": ["rely_on"], "etymology": "bank（頼る）＋on（接触・継続）\n→ くっついたまま続く・作動し続けるイメージ\n→ そこから「当てにする、頼りにする」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"rotate(-9,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"14\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M28 26 L36 26 M28 32 L36 32 M28 38 L36 38\" stroke=\"#C79A3D\" stroke-width=\"2\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 380, "stage": 8, "verb": "rule out", "meaning": "除外する、可能性を否定する", "def": "to eliminate something as a possibility", "ex1": "We can't rule out the flu.", "ja1": "インフルエンザの可能性は否定できない。", "ex2": "We ruled out a hardware failure.", "ja2": "ハードウェア障害の可能性は除外した。", "note": "", "nuance": "可能性を除外する、選択肢から外す判断。", "groups": [], "etymology": "rule（線を引く・支配する）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「除外する、可能性を否定する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#3E6E8E\"/><g transform=\"rotate(0,32,32)\"><path d=\"M32 16 L32 44 M20 44 L44 44\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/><path d=\"M18 22 L32 16 L46 22\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\"/><circle cx=\"18\" cy=\"26\" r=\"6\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\"/><circle cx=\"46\" cy=\"26\" r=\"6\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 381, "stage": 8, "verb": "come off as", "meaning": "〜という印象を与える（言動・態度から）", "def": "to appear to have a particular quality", "ex1": "He came off as arrogant.", "ja1": "彼は傲慢な印象を与えた。", "ex2": "The reply came off as dismissive.", "ja2": "その返信はそっけない印象を与えた。", "note": "Stage 6 の come across as とほぼ同義", "nuance": "他者にどう見えるかを表す、come across asと類似。", "groups": ["impression"], "etymology": "come（来る）＋off（離れて）\n→ くっついていた物が離れる・停止や出発のイメージ\n→ そこから「〜という印象を与える（言動・態度から）」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#1B2A41\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(10,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 382, "stage": 8, "verb": "throw together", "meaning": "急ごしらえで作る", "def": "to make something quickly without much care", "ex1": "I threw together a salad.", "ja1": "さっとサラダを作った。", "ex2": "He threw together a deck the night before.", "ja2": "彼は前夜に急ごしらえで資料を作った。", "note": "", "nuance": "急ごしらえで作る、丁寧さより速さ優先のニュアンス。", "groups": [], "etymology": "throw（投げる）＋together（一つに）\n→ バラバラだった物が一つにまとまるイメージ\n→ そこから「急ごしらえで作る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"rotate(2,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 2 L8 8 L0 14 M16 2 L8 8 L16 14\" stroke=\"#B5392F\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 383, "stage": 8, "verb": "buzz in", "meaning": "（解錠して）中に入れる", "def": "to let someone into a building by pressing a buzzer", "ex1": "Buzz me in, please.", "ja1": "中に入れてください。", "ex2": "Reception will buzz you in at the second door.", "ja2": "受付が2つ目の扉で解錠します。", "note": "", "nuance": "解錠ボタンで人を中に入れる、セキュリティ関連の表現。", "groups": ["enter_various"], "etymology": "buzz（ブンブン鳴る）＋in（中へ）\n→ 外から中に入る・参加や到着のイメージ\n→ そこから「（解錠して）中に入れる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-14,32,32)\"><path d=\"M32 16 Q22 16 22 28 L22 38 L18 44 L46 44 L42 38 L42 28 Q42 16 32 16 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M28 44 Q28 48 32 48 Q36 48 36 44\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 384, "stage": 8, "verb": "space out", "meaning": "ぼんやりする、上の空になる", "def": "to stop paying attention and think about nothing", "ex1": "I spaced out during the lecture.", "ja1": "講義中にぼんやりしていた。", "ex2": "I spaced out during the long status report.", "ja2": "長い進捗報告の間、上の空だった。", "note": "くだけた表現", "nuance": "注意力が散漫になる、ぼんやりするカジュアルな表現。", "groups": [], "etymology": "space（間隔をあける）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「ぼんやりする、上の空になる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#8A4B8A\"/><g transform=\"rotate(-6,32,32)\"><path d=\"M32 16 L32 44 M20 44 L44 44\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/><path d=\"M18 22 L32 16 L46 22\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\"/><circle cx=\"18\" cy=\"26\" r=\"6\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\"/><circle cx=\"46\" cy=\"26\" r=\"6\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 385, "stage": 8, "verb": "throw off", "meaning": "調子を狂わせる、混乱させる", "def": "to confuse someone or disrupt something", "ex1": "The noise threw me off.", "ja1": "騒音で調子が狂った。", "ex2": "The last-minute change threw off the whole schedule.", "ja2": "直前の変更で全体の日程が狂った。", "note": "", "nuance": "リズムや調子を狂わせる、混乱させる表現。", "groups": ["mess_disrupt"], "etymology": "throw（投げる）＋off（離れて）\n→ くっついていた物が離れる・停止や出発のイメージ\n→ そこから「調子を狂わせる、混乱させる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#1B2A41\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(11,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 4 L6 10 M10 6 L16 12\" stroke=\"#B5392F\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 386, "stage": 8, "verb": "chip in", "meaning": "出し合う／口を挟む", "def": "to contribute money; to add a comment", "ex1": "We all chipped in for the gift.", "ja1": "皆でお金を出し合って贈り物を買った。", "ex2": "Feel free to chip in with your ideas.", "ja2": "気軽に意見を出してください。", "note": "", "nuance": "少額のお金を出し合う意味と、会話に口を挟む意味。", "groups": ["interrupt"], "etymology": "chip（欠く）＋in（中へ）\n→ 外から中に入る・参加や到着のイメージ\n→ そこから「出し合う／口を挟む」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"rotate(-5,32,32)\"><path d=\"M16 32 L26 32 L30 22 L36 42 L40 32 L48 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linejoin=\"round\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"6\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M16 0 L10 6 M16 16 L10 10\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 387, "stage": 8, "verb": "get to*3", "meaning": "悩ませる、こたえる", "def": "to annoy or upset someone over time", "ex1": "Don't let it get to you.", "ja1": "気にしないで。", "ex2": "The constant changes are getting to the team.", "ja2": "度重なる変更がチームにこたえている。", "note": "Stage 1 / 2 に別語義あり", "nuance": "悩ませる・こたえるという、精神的負荷を表す新用法。", "groups": ["get_to_senses"], "etymology": "get（得る・～になる）＋to（～へ）\n→ 目的地・相手に向かうイメージ\n→ そこから「悩ませる、こたえる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-1,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L12 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><circle cx=\"14\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/></g></svg>"}, {"no": 388, "stage": 8, "verb": "stumble on", "meaning": "偶然見つける", "def": "to find something by chance", "ex1": "I stumbled on a great bookstore.", "ja1": "すてきな本屋を偶然見つけた。", "ex2": "I stumbled on the bug while testing something else.", "ja2": "別のテスト中に偶然その不具合を見つけた。", "note": "", "nuance": "偶然に何かを見つける、意図せぬ発見。", "groups": ["encounter"], "etymology": "stumble（つまずく）＋on（接触・継続）\n→ くっついたまま続く・作動し続けるイメージ\n→ そこから「偶然見つける」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"rotate(-5,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 389, "stage": 8, "verb": "wind down", "meaning": "徐々に終わる、くつろぐ", "def": "to relax; to gradually reduce activity", "ex1": "I wind down with a book.", "ja1": "本を読んでくつろぐ。", "ex2": "The project is winding down this quarter.", "ja2": "プロジェクトは今四半期で徐々に終息する。", "note": "", "nuance": "活動が徐々に収束する、または心身をリラックスさせる。", "groups": ["gradual_pace"], "etymology": "wind（巻く）＋down（下へ）\n→ 下向き・減少や書き留めるイメージ\n→ そこから「徐々に終わる、くつろぐ」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#2E6B4F\"/><g transform=\"rotate(-10,32,32)\"><path d=\"M32 32 m-4,0 a4,4 0 1,0 8,0 a8,8 0 1,0 -16,0 a12,12 0 1,0 24,0 a16,16 0 1,0 -32,0\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 16 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 390, "stage": 8, "verb": "gross out", "meaning": "気持ち悪がらせる", "def": "to make someone feel disgusted", "ex1": "The smell grossed me out.", "ja1": "そのにおいで気分が悪くなった。", "ex2": "The photo in the slide grossed out the audience.", "ja2": "スライドの写真に聴衆は不快感を示した。", "note": "くだけた表現", "nuance": "不快感や嫌悪感を抱かせる、カジュアルな表現。", "groups": ["disturb_creep_out"], "etymology": "gross（（口語で）気持ち悪い・下品な）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「気持ち悪がらせる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#8A4B8A\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-4,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"16\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"27\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><circle cx=\"37\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><path d=\"M26 38 Q32 42 38 38\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 391, "stage": 8, "verb": "ask out", "meaning": "デートに誘う", "def": "to invite someone to go on a date", "ex1": "He asked her out.", "ja1": "彼は彼女をデートに誘った。", "ex2": "Asking out a subordinate can create a conflict of interest.", "ja2": "部下をデートに誘うのは利益相反になりうる。", "note": "", "nuance": "デートに誘う、恋愛的な文脈での表現。", "groups": ["dating_romance"], "etymology": "ask（尋ねる）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「デートに誘う」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#8A4B8A\"/><g transform=\"rotate(-6,32,32)\"><path d=\"M14 20 Q14 16 18 16 L46 16 Q50 16 50 20 L50 36 Q50 40 46 40 L26 40 L18 48 L20 40 L18 40 Q14 40 14 36 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 392, "stage": 8, "verb": "talk around", "meaning": "遠回しに話す、核心を避ける", "def": "to avoid discussing the main point", "ex1": "He talked around the issue.", "ja1": "彼は問題の核心を避けて話した。", "ex2": "Stop talking around the delay and give us a date.", "ja2": "遅延の話を避けずに日付を出してください。", "note": "", "nuance": "話の核心を避けて遠回しに話す、はぐらかしのニュアンス。", "groups": [], "etymology": "talk（話す）＋around（周りに）\n→ あちこち・ぐるりと回るイメージ\n→ そこから「遠回しに話す、核心を避ける」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"rotate(-7,32,32)\"><path d=\"M14 20 Q14 16 18 16 L46 16 Q50 16 50 20 L50 36 Q50 40 46 40 L26 40 L18 48 L20 40 L18 40 Q14 40 14 36 Z\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M8 2 A6 6 0 1 1 2 8\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2.2\"/><path d=\"M2 8 L0 4 M2 8 L6 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 393, "stage": 8, "verb": "sell out", "meaning": "売り切れる／信念を売る", "def": "to be completely sold; to betray your principles", "ex1": "The tickets sold out in minutes.", "ja1": "チケットは数分で売り切れた。", "ex2": "The venue sold out before we could register.", "ja2": "申し込む前に会場が満席になった。", "note": "", "nuance": "商品が売り切れる意味と、信念を裏切る意味の両方。", "groups": [], "etymology": "sell（売る）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「売り切れる／信念を売る」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-11,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"14\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M28 26 L36 26 M28 32 L36 32 M28 38 L36 38\" stroke=\"#C79A3D\" stroke-width=\"2\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 394, "stage": 8, "verb": "block out", "meaning": "遮る／（時間を）確保する", "def": "to prevent light or noise; to reserve time", "ex1": "Curtains block out the light.", "ja1": "カーテンが光を遮る。", "ex2": "I blocked out two hours for the review.", "ja2": "レビューのため2時間を確保した。", "note": "", "nuance": "光や音を遮る意味と、時間を確保する意味がある。", "groups": [], "etymology": "block（塞ぐ）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「遮る／（時間を）確保する」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#2E6B4F\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-2,32,32)\"><rect x=\"16\" y=\"24\" width=\"32\" height=\"24\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M16 24 L32 14 L48 24\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 395, "stage": 8, "verb": "weird out", "meaning": "気味悪がらせる、戸惑わせる", "def": "to make someone feel uncomfortable or strange", "ex1": "That message weirded me out.", "ja1": "そのメッセージは気味が悪かった。", "ex2": "The unexpected call weirded out the client.", "ja2": "予期しない電話に顧客は戸惑った。", "note": "くだけた表現", "nuance": "気味悪がらせる、戸惑わせるカジュアルな表現。", "groups": ["disturb_creep_out"], "etymology": "weird（（口語で）奇妙な・気味の悪い）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「気味悪がらせる、戸惑わせる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"rotate(-10,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"16\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"27\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><circle cx=\"37\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><path d=\"M26 38 Q32 42 38 38\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 396, "stage": 8, "verb": "sniff out", "meaning": "嗅ぎつける、探り当てる", "def": "to discover something that is hidden", "ex1": "The dog sniffed out the package.", "ja1": "犬が荷物を嗅ぎ当てた。", "ex2": "The auditor sniffed out the discrepancy.", "ja2": "監査人は不一致を嗅ぎつけた。", "note": "", "nuance": "隠された情報や問題を嗅ぎつけて見つけ出す。", "groups": ["probe_sniff"], "etymology": "sniff（嗅ぐ）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「嗅ぎつける、探り当てる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(1,32,32)\"><circle cx=\"32\" cy=\"32\" r=\"16\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"27\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><circle cx=\"37\" cy=\"29\" r=\"2\" fill=\"#C79A3D\"/><path d=\"M26 38 Q32 42 38 38\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 397, "stage": 8, "verb": "egg on", "meaning": "けしかける、あおる", "def": "to encourage someone to do something unwise", "ex1": "His friends egged him on.", "ja1": "友人たちが彼をけしかけた。", "ex2": "Don't egg on a heated discussion in the meeting.", "ja2": "会議で白熱した議論をあおらないでください。", "note": "", "nuance": "けしかけて無謀な行動を後押しする、扇動的な表現。", "groups": [], "etymology": "egg（（onで）けしかける）＋on（接触・継続）\n→ くっついたまま続く・作動し続けるイメージ\n→ そこから「けしかける、あおる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#B5392F\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(13,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 398, "stage": 8, "verb": "cut back on", "meaning": "減らす、切り詰める", "def": "to reduce the amount of something", "ex1": "I'm cutting back on sugar.", "ja1": "砂糖を控えている。", "ex2": "We cut back on travel expenses this year.", "ja2": "今年は出張費を切り詰めた。", "note": "", "nuance": "使用量や支出を減らす、節約のニュアンス。", "groups": ["gradual_reduce"], "etymology": "cut（切る）＋on（接触・継続）\n→ くっついたまま続く・作動し続けるイメージ\n→ そこから「減らす、切り詰める」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(6,32,32)\"><circle cx=\"20\" cy=\"20\" r=\"4\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><circle cx=\"20\" cy=\"44\" r=\"4\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/><path d=\"M23 22 L48 44 M23 42 L48 20\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"4\" fill=\"#B5392F\"/><path d=\"M0 8 L4 8\" stroke=\"#B5392F\" stroke-width=\"2\"/></g></svg>"}, {"no": 399, "stage": 8, "verb": "pull up*3", "meaning": "（成績・数値を）引き上げる", "def": "to improve something to a higher level", "ex1": "He pulled up his grades.", "ja1": "彼は成績を引き上げた。", "ex2": "The new campaign pulled up the numbers in Q3.", "ja2": "新しい施策が第3四半期の数字を押し上げた。", "note": "Stage 6 / 7 に別語義あり", "nuance": "車を止める（Stage6）とは別に、数値を引き上げる意味。", "groups": ["pull_up_senses"], "etymology": "pull（引く）＋up（上へ）\n→ 上向き・完了や増加のイメージ\n→ そこから「（成績・数値を）引き上げる」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#9A5B2E\"/><g transform=\"rotate(0,32,32)\"><path d=\"M22 40 L22 24 Q22 20 26 20 Q30 20 30 24 L30 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M30 34 L30 22 Q30 18 34 18 Q38 18 38 22 L38 34\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M38 34 L38 24 Q38 20 42 20 Q46 20 46 24 L46 36\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><path d=\"M18 40 Q18 48 26 48 L40 48 Q48 48 48 40 L46 36 L18 40 Z\" fill=\"#C79A3D\" opacity=\"0.25\" stroke=\"#C79A3D\" stroke-width=\"2.5\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L8 0 L16 8 M8 0 L8 16\" stroke=\"#B5392F\" stroke-width=\"2.5\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></g></svg>"}, {"no": 400, "stage": 8, "verb": "stand up to", "meaning": "立ち向かう、耐える", "def": "to resist someone unfairly powerful; to withstand", "ex1": "She stood up to the bully.", "ja1": "彼女はいじめっ子に立ち向かった。", "ex2": "He stood up to unreasonable demands from the client.", "ja2": "彼は顧客の不当な要求に立ち向かった。", "note": "", "nuance": "不当な力や要求に屈せず立ち向かう、勇気ある行動。", "groups": ["oppose_resist"], "etymology": "stand（立つ）＋to（～へ）\n→ 目的地・相手に向かうイメージ\n→ そこから「立ち向かう、耐える」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#8A4B8A\"/><g transform=\"rotate(9,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 8 L12 8\" stroke=\"#B5392F\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><circle cx=\"14\" cy=\"8\" r=\"2\" fill=\"#B5392F\"/></g></svg>"}, {"no": 401, "stage": 8, "verb": "slip out", "meaning": "こっそり抜け出す／（言葉が）口をつく", "def": "to leave quietly; to say something accidentally", "ex1": "I slipped out before the speech.", "ja1": "スピーチの前にこっそり抜けた。", "ex2": "The figure slipped out before it was official.", "ja2": "正式発表の前にその数字が漏れてしまった。", "note": "", "nuance": "こっそり抜け出す意味と、言葉が思わず口をつく意味。", "groups": ["sneak_out"], "etymology": "slip（すべる）＋out（外へ）\n→ 内側から外に出る・出現や消失、完全にやり切るイメージ\n→ そこから「こっそり抜け出す／（言葉が）口をつく」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#4A7A3E\"/><g transform=\"rotate(-14,32,32)\"><path d=\"M14 32 Q20 22 26 32 Q32 42 38 32 Q44 22 50 32\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"2.5\" stroke-linecap=\"round\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><circle cx=\"8\" cy=\"8\" r=\"3\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2\"/><path d=\"M8 8 L16 0 M8 8 L16 16 M8 8 L16 8\" stroke=\"#B5392F\" stroke-width=\"2\" stroke-linecap=\"round\"/></g></svg>"}, {"no": 402, "stage": 8, "verb": "run by", "meaning": "（確認のため）意見を聞く", "def": "to tell someone about something to get their opinion", "ex1": "Run it by me first.", "ja1": "まず私に確認させて。", "ex2": "Let me run the draft by my manager.", "ja2": "草案を上司に確認させてください。", "note": "run something by someone の語順", "nuance": "確認のため人に意見を聞く、run something by someoneの形。", "groups": ["confirm_check"], "etymology": "run（走る）＋by（そばを）\n→ すぐそばを通り過ぎるイメージ\n→ そこから「（確認のため）意見を聞く」という意味に。", "illustration": "<svg width=\"64\" height=\"64\" viewBox=\"0 0 64 64\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"32\" cy=\"32\" r=\"30\" fill=\"#FBFAF6\" stroke=\"#C79A3D\" stroke-width=\"1.5\"/><circle cx=\"14\" cy=\"14\" r=\"4\" fill=\"#7A5C1E\"/><g transform=\"scale(-1,1) translate(-64,0) rotate(-4,32,32)\"><path d=\"M26 18 L22 46 M38 18 L42 46 M26 18 L38 18\" fill=\"none\" stroke=\"#C79A3D\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"32\" cy=\"14\" r=\"6\" fill=\"#C79A3D\"/></g><g transform=\"translate(40,40)\"><circle cx=\"8\" cy=\"8\" r=\"11\" fill=\"#FBFAF6\" stroke=\"#B5392F\" stroke-width=\"1.5\"/><path d=\"M0 12 Q8 -2 16 12\" fill=\"none\" stroke=\"#B5392F\" stroke-width=\"2.2\"/></g></svg>"}];


const GROUP_INFO = {"visit_casually": {"label": "ふらっと立ち寄る", "note": "共通するのは「予定せず訪れる」こと。drop byは訪問先そのものに主眼があり、come byは「立ち寄って何かを受け取る・得る」ニュアンスも持つ。drop inは3つの中で最も軽く、突然性が強い。"}, "board_vehicle": {"label": "乗り物に乗る", "note": "get onは電車やバスへの標準的な乗車動作。hop onはそれをより身軽に、ひょいと乗り込む軽快でカジュアルな響きに変える。"}, "return": {"label": "戻る・戻す", "note": "come backは話し手のいる場所へ戻ってくる（聞き手視点）、go backは元いた場所へ帰る（話者側の視点）。get backは口語的な万能形。take back*2／bring backは「（物を）戻す・持ち帰る」という他動詞的な使い方。"}, "move_house": {"label": "引っ越し（反意語）", "note": "move inは新居への入居、move outはそこからの退去。ちょうど反対の意味のペア。"}, "appear": {"label": "現れる", "note": "show upは単に姿を見せるという中立的な表現。turn upは「ひょっこり」「意外にも」という予想外のニュアンスが強く、なくし物が出てくる場合にもよく使う。"}, "postpone": {"label": "延期する", "note": "put offが最も一般的な「延期する」。hold offは「様子を見て一旦保留する」という判断のニュアンスが強く、push back*2はすでに決まっていた予定を後ろにずらす具体的な動作を指す。"}, "submit": {"label": "提出する", "note": "hand inとturn inはほぼ同義（宿題やレポートなど）で、turn inの方がやや口語的。put in*2は「申請書を提出する」といった特定の文脈で使われやすい。"}, "leave_place": {"label": "立ち去る", "note": "go awayは単純に立ち去る、または症状が消えるという意味でも使う中立的な表現。walk outは抗議や不満を示して途中で退席する、より強い意味合いを持つ。"}, "power": {"label": "電源（反意語）", "note": "turn onは電源・明かりをつける、turn offは消す。日常会話で最頻出クラスの反意語ペア。"}, "encounter": {"label": "偶然出会う", "note": "run intoとbump intoは主に「人に」偶然出会う際に使う。come acrossは「物・情報に」偶然出くわす場合が中心。stumble onはそこからさらに「たまたま発見する」という驚きのニュアンスが加わる。"}, "tidy_up": {"label": "片づける", "note": "clean upは掃除して綺麗にすること全般。put awayは使った物を元の場所へしまう動作。pack upは旅行や引っ越しの文脈で荷物をまとめることを指す。"}, "turn_out_end_up": {"label": "結局〜になる", "note": "turn outは「蓋を開けてみたら〜だった」という判明のニュアンス。end upは「最終的にそうなった」という結果そのものを重視する。come down toは「要するに〜次第だ」と要因を絞り込む表現。"}, "discard": {"label": "捨てる", "note": "ほぼ同義。throw outの方が「その場から外へ放り出す」という物理的な動作がわずかに強く出る。"}, "hotel_checkin": {"label": "チェックイン（反意語）", "note": "check inはホテルや空港での手続きを済ませて入ること、check outはその逆の退出・精算の手続き。"}, "choose": {"label": "選ぶ", "note": "pick outは複数の中から選び出す動作そのもの。go forは「これに決める」という積極的な選択。go withは「これで合わせる／これにしておく」という、やや消極的・妥協的な選択も含む。"}, "gather": {"label": "集まる", "note": "get togetherはやや広い意味の「集まる」。meet upは「事前に約束して落ち合う」という待ち合わせのニュアンスが強い。"}, "wait": {"label": "少し待つ", "note": "ほぼ同義。hold onの方が電話口などでやや丁寧に響き、hang onはよりカジュアルな響きを持つ。"}, "distribute": {"label": "配る", "note": "ほぼ同義で「配る」。pass out*2の方がやや口語的に使われる。"}, "fall_down": {"label": "転ぶ・倒れる", "note": "ほぼ同義。fall overは「バランスを崩して転ぶ」動作そのものに寄り、fall downは結果として「倒れている」状態も含めて指せる。"}, "use_up": {"label": "使い果たす", "note": "run out ofは「主語（人や物）が〜を切らす」という視点。use upは「〜を使い切る」という、使う側の動作そのものに焦点がある。"}, "succeed": {"label": "うまくいく", "note": "work outは物事が「うまくいく」という全般的な表現。pull offは「難しいことをやってのける」達成感を伴う。come offは口語的でくだけた響き。pay off*2は「努力や投資が実を結ぶ」場合に使い、make out*2 (2)は「首尾よくやる」というインフォーマルな表現。"}, "speak_loudly": {"label": "大きな声で話す", "note": "speak upは「もっと大きな声で／勇気を持って意見を言う」ことを促す表現。call outは「大声で呼ぶ」意味に加え、「公然と非難する」という意味でも使われる。"}, "convey_info": {"label": "考えを伝える", "note": "pass onは情報を人から人へ伝達すること。get acrossは「考えを相手に理解させる」、伝わることそのものに焦点がある。"}, "opportunity_arises": {"label": "機会・話が持ち上がる", "note": "come upは話題や用事がふと持ち上がること。come up*2は機会そのものが生じること。come along*2やcome around*3は「機会や時期が巡ってくる」という周期性・偶然性のニュアンスを持つ。"}, "head_toward": {"label": "〜へ向かう", "note": "head toは目的地に向かう方向性そのものを表す。go over toは「そちらへ移動する」という意味のほか、比喩的に「（考え方などの）立場を変える」という意味でも使われる。"}, "accomplish_through": {"label": "やり遂げる", "note": "get throughはやり遂げる・乗り切るという全般的な表現。follow throughは「最後まで計画通りにやり遂げる」有言実行のニュアンス。push throughは「抵抗を押し切って成立させる」強い推進力を伴う。"}, "return_money": {"label": "返す", "note": "give backは物を返す一般的な表現。pay backは「借金や恩を返済する」場合に使う。take backは「返品する」、または「発言を撤回する」という意味で使われる。"}, "call_phone": {"label": "電話をかける", "note": "call backは「折り返し電話する」。call upはただ電話をかけるという中立的な表現。hit upはかなりカジュアルな「連絡する」という響きを持つ。"}, "match_suit": {"label": "合う・似合う", "note": "ほぼ同義で「合う・似合う」。go togetherの方がより一般的に、物事の調和を表す場面で使われる。"}, "understand": {"label": "理解する", "note": "take inは情報を吸収して理解すること。figure outは考えを巡らせて答えにたどり着くこと。catch on*2は口語的に「わかる、飲み込む」という響きを持つ。"}, "be_careful": {"label": "気をつける", "note": "ほぼ同義の警告表現。多くの場面で置き換え可能。"}, "organize": {"label": "整理する・まとめる", "note": "get together*2は物や情報をひとまとめにすること。put togetherは部品などを組み立てること。wrap upは物事を仕上げて終えること。sort outは混乱した状況を整理して解決することを指す。"}, "made_of_from": {"label": "材料・原料（作る）", "note": "make fromとmake out ofは「原料が姿を変えて」別のものになる場合に使う（例：ぶどうからワイン）。make ofは「材料がそのままの形で見える」場合に使う（例：木製の机）。make intoは「〜に作り変える」という変化の方向そのものを示す。"}, "avoid_stay_away": {"label": "近づかない・避ける", "note": "keep awayは他動詞的に「（何かを）近づかせない」。stay awayは自動詞的に「自分が近寄らない」。keep offは「（表面や話題に）触れない」という意味で使われる。"}, "volume": {"label": "音量・温度（反意語）", "note": "turn upは音量や温度を上げる、turn downは下げる。日常会話で頻出する反意語ペア。"}, "help_cover": {"label": "代理を務める・手伝う", "note": "help outは一般的な「手伝う」。cover forとfill in forはどちらも「人の代理を務める」という意味だが、cover forには「かばう」というニュアンスも含まれる。"}, "review_check": {"label": "確認する・見直す", "note": "go overは資料などを見直すこと。look intoは問題を詳しく調査すること。check out*2は気軽に「確認してみる」という軽さを持つ。"}, "avoid_evade": {"label": "回避する・逃れる", "note": "get around*2は「規則や制約を巧妙に回避する」こと。get out ofは「義務や責任から逃れる」ことを指す。"}, "break_into_parts": {"label": "分解する", "note": "break up*2は全体を細かく分けること。break down*2は要素ごとに分解して分析すること（内訳を示す場合にも使う）。take apartは物理的に分解する動作そのものを指す。"}, "calm_down": {"label": "落ち着く", "note": "calm downは興奮や怒りを鎮めること。settle downは気持ちが落ち着く、または生活が安定するという意味も持つ。chill outは非常にカジュアルな「リラックスする」という響き。"}, "rely_on": {"label": "頼る", "note": "turn toは困った時に頼る対象を求めること。count onは「当てにできる」という信頼のニュアンス。bank onは「それを前提に計画する」という、より強い依存を表す。"}, "deceive": {"label": "だます・だまされる", "note": "take in*2は「だます」側からの視点。fall forは「だまされる」（または「恋に落ちる」）という、される側の視点で使われる。"}, "write_down": {"label": "書き留める", "note": "ほぼ同義で「書き留める」。多くの場面で置き換え可能。"}, "come_along_together": {"label": "一緒に連れて行く・ついていく", "note": "bring alongは自分が誰かを連れて行くこと。tag alongは誘われていないのに自分からくっついていくことを指す。"}, "distinguish": {"label": "見分ける", "note": "make out*2は「かろうじて識別する」という困難さを伴う。tell apartは似たもの同士を比較して見分けるというニュアンスが強い。"}, "pull_over_stop_car": {"label": "車を止める", "note": "pull overは「路肩に寄せて止まる」という典型的な表現。pull upは単に「車が止まる」ことを指す。pull off*2は「道路脇に車を寄せる」動作そのものに焦点がある。"}, "fill_form": {"label": "記入する", "note": "ほぼ同義で「記入する」。fill outの方がアメリカ英語でより一般的に使われる。"}, "endure": {"label": "我慢する・耐える", "note": "put up withは「不快なことを我慢する」という広い意味で使われる。sit throughは「退屈でも最後まで座って耐える」という、より具体的な場面を指す。"}, "begin": {"label": "〜として始まる", "note": "ほぼ同義で「〜として始まる」。start offはその後の展開に、start outは出発点そのものに、それぞれ焦点がある。"}, "impression": {"label": "印象を与える", "note": "ほぼ同義で「〜という印象を与える」。互換性が高く、どちらを使ってもよい場面が多い。"}, "hand_over": {"label": "引き渡す", "note": "turn in*2は「犯人などを当局に引き渡す」という特定の文脈で使われる。hand overは物や権限を一般的に「引き渡す」という意味を持つ。"}, "interrupt": {"label": "口を挟む", "note": "butt inは「無礼に割り込む」という否定的なニュアンスが強い。chip inは「（お金や意見を）少しずつ出し合う」場合にも使われ、口を挟むという意味ではより中立的。"}, "sneak_out": {"label": "こっそり抜け出す", "note": "ほぼ同義で「こっそり抜け出す」。slip outは「言葉がつい口をついて出る」という意味でも使われる点が異なる。"}, "disturb_creep_out": {"label": "不快にさせる・戸惑わせる", "note": "gross outは「気持ち悪くさせる」という嫌悪感を表す。weird outは「気味悪がらせる・戸惑わせる」という、奇妙さに対する反応を表す。"}, "vehicle_actions": {"label": "乗り物に関する動作", "note": "get inは車などに「乗り込む」こと。get offはバス・電車などから「降りる」こと。pull inは車が目的地に「入って止まる」ことを表す。"}, "clothing_wear": {"label": "着る・脱ぐ・試着", "note": "put onは「身につける」動作そのもの、take offは「脱ぐ」動作。try onは購入前などに「試着する」こと。dress upは「着飾る、正装する」という結果重視の表現。"}, "escape_run_away": {"label": "逃げる", "note": "run awayは家出や逃走など「その場から逃げ出す」こと。get awayは危険から逃げる場合にも、休暇で「日常から離れる」場合にも使う。"}, "enter_various": {"label": "入る", "note": "come inは自然に「入ってくる」こと。get intoは物理的に中に入る、または比喩的に「夢中になる」こと。break intoは許可なく「押し入る」こと。get in*2は組織・学校に「入る、合格する」こと。buzz inは解錠して人を「中に入れてあげる」こと。"}, "home_or_out": {"label": "家にいる・外出する", "note": "stay inは「家にいて外出しない」こと。go outは「外出する」こと。stay outは「外にいて（夜遅くまで）帰らない」こと。"}, "undertake_continue_work": {"label": "引き受ける・続ける・取り組む", "note": "take onは新しい仕事や責任を「引き受ける」こと。hold downは今の仕事を「維持し続ける」こと。keep onは「〜し続ける」という継続そのもの。take upは新しいことを「始める」こと。work onやget on withは実際に「取り組む、進める」という作業寄りの表現。"}, "give_up_in": {"label": "あきらめる・妥協する", "note": "give upは目標や努力を完全に「あきらめる」こと。give inは相手の要求などに「屈する」こと。back offは対立や要求から「引き下がる」こと。settle forは不満は残るが「妥協して受け入れる」こと。"}, "catch_up_behind": {"label": "遅れる・追いつく", "note": "keep upは「遅れずについていく」こと。get behindは「遅れをとる」こと。catch upは遅れた状態から「追いつく」こと。"}, "put_up_senses": {"label": "put upの意味の違い", "note": "put upは看板やテントなどを「掲げる、建てる」こと。put up*2は人を自宅に「泊める」という意味で使われる。"}, "go_down_senses": {"label": "go downの意味の違い", "note": "go downは物理的に「下がる」、日が「沈む」という意味。go down*2はシステムが「停止する」、または記録に「残る」という意味で使われる。"}, "imperative_expr": {"label": "強い命令表現", "note": "shut upは「黙れ」という強い命令。listen upは「よく聞け、注目しろ」という注意喚起の命令。どちらも口語的で直接的な言い方。"}, "skim_review": {"label": "ざっと目を通す", "note": "go throughは資料などに「一通り目を通す」こと（つらい経験を「経る」の意味もある）。look throughはより「ざっと」目を通すニュアンス。"}, "put_down_senses": {"label": "put downの意味の違い", "note": "put downは物理的に「下に置く」こと。put down*2は人を「けなす、こきおろす」という比喩的な意味。"}, "get_up_stand_up": {"label": "起きる・立ち上がる", "note": "get upは寝ている状態から「起きる」こと（立ち上がる意味もある）。stand upは座っていた状態から「立ち上がる」こと。"}, "stand_out_show_off": {"label": "目立つ・見せびらかす", "note": "stand outは自然と「目立つ、際立つ」こと。show offはわざと「見せびらかす」という、やや否定的なニュアンスを持つ。"}, "relationship_harmony": {"label": "仲良くやる・一緒にいる", "note": "get alongは人と「仲良くやる、うまくやっていく」こと。stay togetherは「一緒にいる、離れずにいる」という状態そのものを表す。"}, "scold_yell": {"label": "叱る・怒鳴る", "note": "tell offは「叱る、きつく注意する」こと。go off onは感情的に「怒鳴りつける」という、より激しいニュアンス。"}, "reflect_step_back": {"label": "振り返る・一歩引く", "note": "look back onは過去を「振り返る」こと。step backは一歩引いて「冷静に考える」こと。sit backはゆったり座る、または「静観する」ことを表す。"}, "break_malfunction": {"label": "壊れる・故障する", "note": "give out*2は機械などが「壊れる、尽きる」こと。break downは「故障する」こと、または人が感情的に「取り乱す」こと。wear outは使い込んで「すり減る」こと、または人を「疲れ果てさせる」こと。"}, "pay_related": {"label": "支払う", "note": "pay forは代金を「支払う、負担する」こと。pay offは借金などを「完済する」こと。"}, "come_around_senses": {"label": "come aroundの意味の違い", "note": "come aroundは「立ち寄る」こと、または考えを変えて「同意する」こと。come around*2は気絶した状態から「意識を取り戻す」という意味。"}, "break_up_apart": {"label": "壊れる・別れる", "note": "break upは関係が「別れる」こと、または物事が「解散する」こと。fall apartはより物理的・比喩的に「ばらばらになる、崩壊する」こと。"}, "bring_up_senses": {"label": "bring upの意味の違い", "note": "bring upは話題を「持ち出す」こと。bring up*2は子どもを「育てる、養育する」という意味。"}, "take_out_senses": {"label": "take outの意味の違い", "note": "take outは物を「取り出す、持ち出す」こと。take out*2は保険やローンを「契約する」という意味で使われる。"}, "reveal_secret": {"label": "秘密を漏らす", "note": "give awayは物を「ただであげる」こと、または秘密を「漏らす」こと。let outは情報などを「外に漏らす」こと。let onは秘密をほのめかす、そぶりを「見せる」こと。"}, "get_to_senses": {"label": "get toの意味の違い", "note": "get toは場所に「到着する」こと。get to*2は「〜する機会を得る」こと。get to*3は人を「悩ませる、こたえる」という意味で使われる。"}, "pick_up_senses": {"label": "pick upの意味の違い", "note": "pick upは物を「拾い上げる」こと、または車で人を「迎えに行く」こと。pick up*2は技能や言語を自然に「身につける」こと。pick up*3は体調や状況が「回復する、勢いを増す」こと。pick up*4は電話に「出る」こと。"}, "make_up_senses": {"label": "make upの意味の違い", "note": "make upは話を「でっちあげる」こと。make up*2はけんかの後に「仲直りする」こと。make up*3は不足分を「埋め合わせる」こと。make up*4は全体を「構成する、占める」という意味。"}, "put_out_senses": {"label": "put outの意味の違い", "note": "put outは火や明かりを「消す」こと。put out*2は物を「外に出す」こと。put out*3は人に「迷惑をかける、手間をかけさせる」という意味。"}, "keep_in_out": {"label": "中に入れる・締め出す", "note": "keep outは人を「立ち入らせない、締め出す」こと。keep inは逆に、人や物を「中にとどめておく」こと。"}, "stand_for_senses": {"label": "stand forの意味の違い", "note": "stand forは略語が「〜を表す」こと。stand for*2は好ましくない状況などを「容認する、我慢する」という意味。"}, "open_up_senses": {"label": "open upの意味の違い", "note": "open upは物理的に「開ける」こと、または店を「開設する」こと。open up*2は人が心を開いて「打ち明け話をする」という意味。"}, "bully_mistreat": {"label": "いじめる・乱暴に扱う", "note": "pick onは特定の人を「いじめる、目の敵にする」こと。rough upはより直接的・身体的に「手荒に扱う、暴行する」こと。"}, "turn_direction": {"label": "向きを変える", "note": "turn aroundは「向きを変える」こと、または業績などを「好転させる」こと。turn backは来た道を「引き返す」こと。"}, "bring_in_out": {"label": "導入する・世に出す", "note": "bring inは新しい制度や人を「導入する、呼び込む」こと。bring outは製品やアイデアなどを「世に出す」こと、または人の性質を「引き出す」こと。"}, "exit_leave_briefly": {"label": "抜け出す・少し席を外す", "note": "get outはその場から「出る、抜け出す」こと。step outは「少しの間、席を外す」という短時間のニュアンス。"}, "pull_out_away": {"label": "離れる・撤退する", "note": "pull outは計画や場所から「撤退する」こと、または物を「引き抜く」こと。pull awayは物理的に「離れていく」こと。"}, "cheer_encourage": {"label": "応援する・励ます", "note": "cheer upは落ち込んでいる人を「元気づける」こと。cheer onは声を出して「応援する」こと。get behind*2は人や案を「支持する、後押しする」こと。"}, "take_down_senses": {"label": "take downの意味の違い", "note": "take down*2は建物などを「取り壊す、撤去する」こと。take down*3は相手を「やり込める、打ち負かす」という意味。"}, "hold_out_off": {"label": "持ちこたえる・食い止める", "note": "hold outは苦しい状況で「持ちこたえる」こと。hold off*2は問題などを「食い止める、寄せつけない」こと。"}, "study_review": {"label": "復習する・予習する", "note": "brush upは以前学んだことを「復習する、磨き直す」こと。read up onはある話題について事前に「読み込む、調べる」こと。"}, "oppose_resist": {"label": "抵抗する・立ち向かう", "note": "push backは要求や意見に「反発する、難色を示す」こと。stand up toは困難や相手に「立ち向かう、耐える」こと。"}, "elaborate_dig": {"label": "詳しく述べる・深く掘り下げる", "note": "go intoは話題について「詳しく述べる」こと。dig intoはより「深く掘り下げて調べる」というニュアンス。"}, "hold_in_senses": {"label": "hold inの意味の違い", "note": "hold inは感情などを「抑える」こと。hold in*2は熱や水などを「閉じ込める」という物理的な意味。"}, "gain_popularity": {"label": "人気が出る・急に伸びる", "note": "catch onは「人気が出る、広まる」こと。take off*2は離陸のイメージから転じて、売上や人気が「急伸する」こと。"}, "slack_off_group": {"label": "怠ける・ふざける", "note": "slack offは仕事などで「手を抜く、怠ける」こと。fool aroundは「ふざける、時間を無駄にする」こと。"}, "move_on_over": {"label": "気持ちを切り替える・立ち直る", "note": "move onは次の段階へ「気持ちを切り替える」こと。get overはつらい経験や別れから「立ち直る、克服する」こと。"}, "adapt_fit_in": {"label": "慣れる・なじむ", "note": "fit inは周囲に「なじむ、溶け込む」こと。settle inは新しい環境に「慣れる」という、時間をかけて馴染んでいくニュアンス。"}, "schedule_fit": {"label": "予定に入れる・都合をつける", "note": "fit in*2は忙しい予定の中に何かを「入れる、都合をつける」こと。squeeze inは限られた時間や隙間に「無理に詰め込む」という、より切迫したニュアンス。"}, "dive_jump_in": {"label": "勢いよく取りかかる・加わる", "note": "dive inは物事に「勢いよく取りかかる」こと。jump inは会話や活動に「途中から加わる、口を挟む」こと。"}, "cut_off_senses": {"label": "cut offの意味の違い", "note": "cut offは電気やガスなどを「遮断する、停止する」こと。cut off*2は人の話を「遮る」こと。cut off*3は関係や支援を「断つ」こと。"}, "cancel_stop": {"label": "中止する・中断する", "note": "break offは物事を「中断する、打ち切る」こと。call offは予定していたイベントなどを「中止する」こと。"}, "pretend_pass_off": {"label": "偽る・話を合わせる", "note": "pass offは何かを偽って「〜として通用させる」こと。make out*3は実際とは違うことを「〜であるかのように主張する」こと。play alongは話を合わせて「調子を合わせる」こと。"}, "dating_romance": {"label": "恋愛・交際", "note": "go out withは人と「付き合う」こと。come on toは「言い寄る」こと。ask outはデートに「誘う」こと。get back togetherは別れた関係で「よりを戻す」こと。"}, "contact_related": {"label": "連絡する・情報を伝える", "note": "hear fromは人から「連絡をもらう」こと。check in withは相手の状況を「確認する、連絡を取る」こと。fill in*2は不在の間の出来事を「伝える」こと。"}, "revenge_group": {"label": "仕返しする・八つ当たりする", "note": "get back atは相手に「仕返しをする」こと。take out onは自分の怒りやストレスを、関係ない人に「八つ当たりする」こと。"}, "comply_defy": {"label": "従う・逆らう", "note": "go along withは意見や方針に「同意する、従う」こと。go againstはそれに「反する、逆らう」こと。ちょうど反対の意味を持つペア。"}, "dining_location": {"label": "外食する・家で食べる", "note": "eat outは「外食する」こと。eat inは「家で食べる」、または店内で「食事をする」ことを表す。"}, "confirm_check": {"label": "確認する", "note": "check out*3は情報の「裏が取れる、確認が取れる」こと。run byは確認のために「（人に）意見を聞く」こと。"}, "mess_disrupt": {"label": "台無しにする・狂わせる", "note": "mess upは物事を「台無しにする、しくじる」こと。throw offは人の調子やペースを「狂わせる」こと。"}, "probe_sniff": {"label": "探る", "note": "feel outはやんわりと相手の反応を「探る」こと。sniff outはより積極的に何かを「嗅ぎつける、探り当てる」こと。"}, "discuss_thoroughly": {"label": "じっくり話し合う", "note": "talk overは物事について「じっくり話し合う」こと。hash outは意見の違いなどを「議論して詰める」こと。"}, "gradual_pace": {"label": "徐々に・ゆっくり", "note": "ease intoは新しいことに「徐々に慣らす、ゆっくり始める」こと。wind downは活動などが「徐々に終わる」こと、または「くつろぐ」こと。"}, "pull_up_senses": {"label": "pull upの意味の違い", "note": "pull up*2はデータや画面を「呼び出す」こと。pull up*3は成績や数値を「引き上げる」という意味。"}, "stick_persist": {"label": "固執する・居残る", "note": "stick toは決めたことを「守り続ける、固執する」こと。stick aroundはその場に「残る、居残る」こと。"}, "gradual_reduce": {"label": "少しずつ削る・減らす", "note": "chip away atは少しずつ物事を「削る、地道に取り組む」こと。narrow downは選択肢などを「絞り込む」こと。cut back onは量や頻度を「減らす、切り詰める」こと。"}, "hook_up_senses": {"label": "hook upの意味の違い", "note": "hook upは機器などを「接続する、つなぐ」こと。hook up withは人と「落ち合う、組む」という意味で使われる。"}, "socialize_catch_up": {"label": "近況を語り合う・一緒に過ごす", "note": "catch up*2は久しぶりに会った人と「近況を語り合う」こと。hang outは友人などと「ぶらぶら過ごす、一緒に時間を過ごす」こと。"}, "accept_take_up": {"label": "提案を受け入れる", "note": "take up*2は提案などを「受け入れる」こと、または問題を「取り上げる」こと。take up onは相手の申し出を「受ける」こと。"}, "spend_time_effort": {"label": "時間・労力を費やす", "note": "put inは時間や労力を「注ぐ」という、主体的・前向きな投資のニュアンス。eat upは時間や資源を「食う」という、意図せず消費されてしまう、やや否定的なニュアンス。"}};
